-- =============================================================================

insert into public.exercise_templates (slug, title, description, kind, approach, audience, collection, estimated_minutes, sort_order, steps) values
  ('brujula-punto-de-partida', 'Mi punto de partida', 'Para saber desde dónde arrancás y elegir lo que hoy pesa más. No es un test ni un diagnóstico.', 'custom', 'general', 'adolescentes', 'brujula', 8, 101,
   $steps$[ { "id": "bienvenida", "type": "info", "title": "Este cuadernillo es tuyo", "content": "Lo vamos a usar entre sesión y sesión, de a poco. No hay respuestas correctas ni incorrectas, no se ponen notas y podés escribir como te salga. Cada tarea lleva entre 5 y 15 minutos. Si un ejercicio no tiene que ver con lo que te pasa, lo salteamos. Traé a cada sesión lo que anotes: nos ayuda a ver qué te sirve.\n\n**Cómo vamos a trabajar:** Entender → Observar → Practicar → Probar → Repetir." }, { "id": "momento_dificil", "type": "info", "title": "Si estás pasando un momento muy difícil", "content": "Andá directo a «Mi plan para momentos muy difíciles». Lo encontrás en **Calmarme**.\n\nSi estás en peligro ahora, pedí ayuda ya a un adulto, a emergencias o en la guardia del hospital más cercano. En **Calmarme** está el recuadro «Si necesitás ayuda urgente» con los teléfonos." }, { "id": "privacidad", "type": "info", "title": "Lo que escribís es tuyo", "content": "Vos elegís qué compartir y qué no. No hace falta contar nada que no quieras.\n\nTus respuestas quedan guardadas en cada ejercicio, en «Mis respuestas». Tu psicólogo/a solo las puede leer si activás **«Compartir mis registros con mi psicólogo»** en tu perfil. Si te sugirió un ejercicio, ve si lo hiciste, pero no lo que escribiste.\n\n**Hay un límite:** si aparece algo que pone en riesgo tu seguridad o la de otra persona, tu psicólogo o psicóloga va a buscar ayuda con un adulto responsable o con un servicio de protección. Siempre que se pueda, lo va a hablar antes con vos.\n\nSi te preocupa que alguien lea lo que escribís (por ejemplo, si compartís el celular), acordá con tu psicólogo/a cómo cuidarlo." }, { "id": "como_me_dicen", "type": "text", "prompt": "¿Cómo me gusta que me digan?", "help": "Tu nombre, un apodo o como prefieras que te llamen.", "placeholder": "Por ejemplo: Cami, Tobi…", "optional": true }, { "id": "punto_intro", "type": "info", "title": "Mi punto de partida", "content": "**No hace falta trabajar todo. Elegí lo que hoy pesa más.**\n\nEsto sirve para saber desde dónde arrancás. No es un test ni un diagnóstico. Podés dejar en blanco lo que no quieras contestar.\n\nEste cuadernillo acompaña tu tratamiento psicológico y no reemplaza una evaluación profesional." }, { "id": "me_pasa", "type": "checklist", "prompt": "¿Qué me pasa o me preocupa?", "help": "Marcá las que quieras.", "optional": true, "options": [ "Discusiones o tensión en casa", "Me siento solo/a o fuera del grupo", "Burlas, bullying o cyberbullying", "Nervios o ansiedad", "Tristeza o desgano", "El colegio", "POD, vape o cigarrillo", "Enojo que explota", "Me cuesta decir lo que necesito", "Me cuesta pedir ayuda", "Cómo me veo a mí mismo/a", "Otra" ] }, { "id": "me_pasa_otra", "type": "text", "prompt": "Si marcaste «Otra»: ¿qué otra cosa te pasa o te preocupa?", "help": "Si no marcaste «Otra», salteá esta pregunta.", "optional": true }, { "id": "diferente", "type": "text", "prompt": "¿Qué me gustaría que fuera diferente dentro de 2 o 3 meses?", "help": "**Una idea:** un buen objetivo se puede ver desde afuera. En vez de «estar bien», Lucas escribió: «volver a entrenar una vez por semana».", "placeholder": "Algo que se pueda ver desde afuera…", "optional": true }, { "id": "tres_cosas", "type": "list", "prompt": "Las 3 cosas que quiero trabajar", "help": "No hace falta trabajar todo: elegí lo que hoy pesa más.", "count": 3, "min": 1, "optional": true }, { "id": "hoy_animo", "type": "scale", "prompt": "¿Cómo estoy hoy de ánimo?", "help": "Ahora, siete preguntas rápidas sobre cómo estás hoy. Elegí un número: 0 es muy mal y 10 es muy bien.", "min": 0, "max": 10, "min_label": "Muy mal", "max_label": "Muy bien", "optional": true }, { "id": "hoy_nervios", "type": "scale", "prompt": "¿Cómo estoy hoy con los nervios o la ansiedad?", "help": "Acá el 0 es «me desbordan» y el 10 es «los manejo bien».", "min": 0, "max": 10, "min_label": "Me desbordan", "max_label": "Los manejo bien", "optional": true }, { "id": "hoy_relaciones", "type": "scale", "prompt": "¿Cómo estoy hoy en mis relaciones?", "help": "Amigos, compañeros. 0 es muy mal y 10 es muy bien.", "min": 0, "max": 10, "min_label": "Muy mal", "max_label": "Muy bien", "optional": true }, { "id": "hoy_familia", "type": "scale", "prompt": "¿Cómo estoy hoy con mi familia?", "help": "0 es muy mal y 10 es muy bien.", "min": 0, "max": 10, "min_label": "Muy mal", "max_label": "Muy bien", "optional": true }, { "id": "hoy_colegio", "type": "scale", "prompt": "¿Cómo estoy hoy en el colegio?", "help": "0 es muy mal y 10 es muy bien.", "min": 0, "max": 10, "min_label": "Muy mal", "max_label": "Muy bien", "optional": true }, { "id": "hoy_confianza", "type": "scale", "prompt": "¿Cómo estoy hoy con la confianza en mí?", "help": "0 es muy mal y 10 es muy bien.", "min": 0, "max": 10, "min_label": "Muy mal", "max_label": "Muy bien", "optional": true }, { "id": "hoy_emociones", "type": "scale", "prompt": "¿Cómo estoy hoy con el manejo de mis emociones?", "help": "0 es muy mal y 10 es muy bien.", "min": 0, "max": 10, "min_label": "Muy mal", "max_label": "Muy bien", "optional": true }, { "id": "resumen", "type": "reflect", "title": "Desde acá arranco", "template": "Lo que hoy me pasa o me preocupa: {{me_pasa}}. Lo que me gustaría que fuera diferente dentro de 2 o 3 meses: «{{diferente}}». Lo que quiero trabajar: {{tres_cosas}}", "content": "Lo podés volver a ver cuando quieras en este ejercicio, en «Mis respuestas»." }, { "id": "semana", "type": "info", "title": "Para esta semana", "content": "**Unos 5 minutos.** Observá una situación que te movió algo por dentro y anotá:\n\n- ¿Qué pasó?\n- ¿Qué sentiste?\n- ¿Cuánto? (de 0 a 10)\n\nSi querés, lo podés anotar en **«Registrar cómo me siento»**. Después seguimos con «Entender lo que me pasa»." } ]$steps$::jsonb),
  ('brujula-entender-lo-que-me-pasa', 'Entender lo que me pasa', 'Descubrí tu cadena: situación, pensamiento, emoción, cuerpo, conducta y consecuencia.', 'thought_record', 'tcc', 'adolescentes', 'brujula', 8, 102,
   $steps$[ { "id": "cadena", "type": "info", "title": "Lo que te pasa no viene solo: es una cadena", "content": "No reaccionamos solo a lo que pasa, sino también a lo que pensamos sobre lo que pasa. Ese pensamiento mueve una emoción, la emoción se siente en el cuerpo y nos empuja a hacer algo. Y lo que hacemos tiene consecuencias.\n\n**Situación → Pensamiento → Emoción → Cuerpo → Conducta → Consecuencia**\n\nSi conocés tu cadena, podés cortarla en algún eslabón." }, { "id": "ejemplo_cami", "type": "info", "title": "Así le pasó a Cami (13 años)", "content": "- **Situación** (lo que vería una cámara): le escribió a una amiga y hace 3 horas que no le contesta.\n- **Pensamiento** (lo que se le cruzó por la cabeza): «Está enojada conmigo».\n- **Emoción** (qué sintió y cuánto, de 0 a 10): tristeza y nervios, 7.\n- **Cuerpo** (dónde lo sintió): nudo en el estómago.\n- **Conducta** (qué hizo): revisa el celular a cada rato. Al otro día no le habla.\n- **Consecuencia** (qué pasó después): se alejan un poco más y Cami se siente peor." }, { "id": "situacion", "type": "text", "prompt": "Situación: ¿qué pasó?", "help": "Ahora probalo con algo que te pasó esta semana. Escribí lo que vería una cámara.\n\nAsí le pasó a Cami: le escribió a una amiga y hace 3 horas que no le contesta.", "placeholder": "Qué pasó, dónde, con quién…" }, { "id": "pensamiento", "type": "text", "prompt": "Pensamiento: ¿qué se te cruzó por la cabeza?", "help": "Escribilo tal cual apareció.\n\nCami pensó: «Está enojada conmigo»." }, { "id": "emocion", "type": "checklist", "prompt": "Emoción: ¿qué sentiste?", "help": "Elegí hasta 3 palabras.\n\nCami sintió tristeza y nervios.", "options": [ "Bronca", "Tristeza", "Miedo", "Vergüenza", "Culpa", "Nervios", "Soledad", "Frustración", "Celos", "Alegría", "Calma", "Orgullo" ], "max": 3 }, { "id": "intensidad", "type": "scale", "prompt": "¿Cuánto lo sentiste?", "help": "De 0 a 10. Si marcaste más de una, puntuá la más fuerte. Cami: 7.", "min": 0, "max": 10, "min_label": "Nada", "max_label": "Muchísimo", "maps_to": "emotion_before" }, { "id": "cuerpo", "type": "checklist", "prompt": "Cuerpo: ¿dónde lo sentiste?", "help": "Marcá las señales que notaste.\n\nCami lo sintió como un nudo en el estómago.", "options": [ "Corazón rápido", "Nudo en la garganta", "Panza revuelta", "Calor en la cara", "Hombros tensos", "Ganas de llorar", "Cansancio", "Otra señal" ] }, { "id": "cuerpo_otra", "type": "text", "prompt": "¿Querés contar dónde y cómo lo sentiste?", "help": "Sobre todo si marcaste «Otra señal».", "placeholder": "Por ejemplo: nudo en el estómago.", "optional": true }, { "id": "conducta", "type": "text", "prompt": "Conducta: ¿qué hiciste?", "help": "Cami revisa el celular a cada rato. Al otro día no le habla." }, { "id": "consecuencia", "type": "text", "prompt": "Consecuencia: ¿qué pasó después?", "help": "En el caso de Cami: se alejan un poco más y ella se siente peor." }, { "id": "mi_cadena", "type": "reflect", "title": "Tu cadena", "template": "Situación: {{situacion}} → Pensamiento: «{{pensamiento}}» → Emoción: {{emocion}} → Cuerpo: {{cuerpo}} → Conducta: {{conducta}} → Consecuencia: {{consecuencia}}", "content": "Mirala entera, eslabón por eslabón. Si conocés tu cadena, podés cortarla en algún eslabón." }, { "id": "semana", "type": "info", "title": "Para esta semana", "content": "**Unos 10 minutos.** Anotá 3 momentos en un registro rápido. De cada uno:\n\n- Situación\n- Pensamiento\n- Emoción (de 0 a 10)\n- Qué hice\n\nPara anotarlos rápido podés usar **«Registrar cómo me siento»**, que pregunta justo eso. También podés volver a hacer este ejercicio con cada momento. Esos momentos los vas a usar en «Mi detector de pensamientos»." } ]$steps$::jsonb),
  ('brujula-detector-de-pensamientos', 'Mi detector de pensamientos', 'Separá hechos de pensamientos y reconocé ocho trampas frecuentes de la mente.', 'custom', 'tcc', 'adolescentes', 'brujula', 9, 103,
   $steps$[ { "id": "intro", "type": "info", "title": "Tu mente cuenta historias", "content": "Algunas son ciertas y otras, no tanto.\n\nLos pensamientos automáticos aparecen solos, rápido, y suenan a verdad. Para cazarlos, preguntate: **«¿Qué se me pasó por la cabeza justo antes?»**" }, { "id": "camara", "type": "info", "title": "La prueba de la cámara", "content": "Si una cámara lo podría grabar, es un **hecho**. Si no, es un **pensamiento**: una forma de interpretar lo que pasó.\n\n- Hecho: «Mi amiga no me saludó».\n- Pensamiento: «Está enojada conmigo».\n\n**Ojo:** que algo sea un pensamiento no quiere decir que sea falso. Y si alguien te trata mal, eso es un hecho, no un invento de tu mente." }, { "id": "quiz_1", "type": "choice", "prompt": "¿Hecho o pensamiento? «Desaprobé Matemática»", "help": "Usá la prueba de la cámara. Frase 1 de 6.", "options": [ "Hecho", "Pensamiento" ], "feedback": { "Hecho": "**¡Bien! Es un hecho.** Una cámara lo podría grabar: la nota está en la prueba.", "Pensamiento": "**Es un hecho.** Una cámara lo podría grabar: la nota está en la prueba. Lo que pienses después sobre esa nota ya sería un pensamiento." } }, { "id": "quiz_2", "type": "choice", "prompt": "¿Hecho o pensamiento? «Soy un burro»", "help": "Frase 2 de 6.", "options": [ "Hecho", "Pensamiento" ], "feedback": { "Hecho": "**Es un pensamiento.** Ninguna cámara puede grabar que alguien «es un burro». Lo que se puede grabar es, por ejemplo, una nota; «soy un burro» es una forma de interpretarla.", "Pensamiento": "**¡Bien! Es un pensamiento.** Ninguna cámara puede grabar que alguien «es un burro»: es una forma de interpretar lo que pasó." } }, { "id": "quiz_3", "type": "choice", "prompt": "¿Hecho o pensamiento? «Subieron una foto mía sin permiso»", "help": "Frase 3 de 6.", "options": [ "Hecho", "Pensamiento" ], "feedback": { "Hecho": "**¡Bien! Es un hecho.** Una cámara lo podría grabar: la foto está subida.\n\nSi alguien te trata mal, eso es un hecho, no un invento de tu mente, y no es tu culpa. De esto hablamos en «Cuando otros me hacen sentir menos».", "Pensamiento": "**Es un hecho.** Una cámara lo podría grabar: la foto está subida.\n\nSi alguien te trata mal, eso es un hecho, no un invento de tu mente, y no es tu culpa. De esto hablamos en «Cuando otros me hacen sentir menos»." } }, { "id": "quiz_4", "type": "choice", "prompt": "¿Hecho o pensamiento? «Nadie me va a querer nunca»", "help": "Frase 4 de 6.", "options": [ "Hecho", "Pensamiento" ], "feedback": { "Hecho": "**Es un pensamiento.** Ninguna cámara puede grabar el futuro. Suena a verdad, pero es una historia que cuenta tu mente.", "Pensamiento": "**¡Bien! Es un pensamiento.** Ninguna cámara puede grabar el futuro. Aunque suene a verdad, es una historia que cuenta tu mente." } }, { "id": "quiz_5", "type": "choice", "prompt": "¿Hecho o pensamiento? «La profe me pidió que me quede después de clase»", "help": "Frase 5 de 6.", "options": [ "Hecho", "Pensamiento" ], "feedback": { "Hecho": "**¡Bien! Es un hecho.** Una cámara lo podría grabar: la profe lo dijo. Lo que imagines sobre para qué te lo pidió ya sería un pensamiento.", "Pensamiento": "**Es un hecho.** Una cámara lo podría grabar: la profe lo dijo. Lo que imagines sobre para qué te lo pidió ya sería un pensamiento (mirá la frase que sigue)." } }, { "id": "quiz_6", "type": "choice", "prompt": "¿Hecho o pensamiento? «Me van a retar»", "help": "Frase 6 de 6.", "options": [ "Hecho", "Pensamiento" ], "feedback": { "Hecho": "**Es un pensamiento.** Es lo que tu mente imagina que va a pasar después de que la profe te pidió que te quedes. Ninguna cámara lo puede grabar todavía: puede pasar o no.", "Pensamiento": "**¡Bien! Es un pensamiento.** Es lo que tu mente imagina que va a pasar después de que la profe te pidió que te quedes. Ninguna cámara lo puede grabar todavía: puede pasar o no." } }, { "id": "trampas_1", "type": "info", "title": "Ocho trampas frecuentes de la mente (1 de 3)", "content": "Fijate si alguna te suena.\n\n**1. Todo o nada.** Si no es perfecto, es un desastre.\n«No me saqué 5: soy un desastre».\n\n**2. Leer la mente.** Creés saber lo que piensa el otro.\n«Papá llegó callado. Seguro está enojado conmigo».\n\n**3. Película de terror.** Imaginás lo peor como si ya hubiera pasado.\n«Si me va mal en la prueba, se me arruina el año»." }, { "id": "trampas_2", "type": "info", "title": "Ocho trampas frecuentes de la mente (2 de 3)", "content": "**4. Ponerse etiquetas.** Un error se vuelve lo que sos.\n«Soy un fracasado».\n\n**5. Siempre o nunca.** Una vez se vuelve todas las veces.\n«Nunca me sale nada bien».\n\n**6. Lente oscuro.** Solo ves lo malo.\n«Me dijeron cinco cosas buenas y una mala. Solo pienso en la mala»." }, { "id": "trampas_3", "type": "info", "title": "Ocho trampas frecuentes de la mente (3 de 3)", "content": "**7. Bola de cristal.** Das por seguro el futuro.\n«En el colegio nuevo no voy a tener amigos».\n\n**8. Lo siento, entonces es así.** Confundís lo que sentís con lo que pasó.\n«Me dio vergüenza, así que hice el ridículo»." }, { "id": "caigo_mas", "type": "checklist", "prompt": "¿En cuáles caigo más?", "help": "Marcá las tuyas.", "options": [ "Todo o nada", "Leer la mente", "Película de terror", "Ponerse etiquetas", "Siempre o nunca", "Lente oscuro", "Bola de cristal", "Lo siento, entonces es así" ] }, { "id": "la_que_mas", "type": "choice", "prompt": "¿Cuál es la que más me pasa?", "options": [ "Todo o nada", "Leer la mente", "Película de terror", "Ponerse etiquetas", "Siempre o nunca", "Lente oscuro", "Bola de cristal", "Lo siento, entonces es así" ] }, { "id": "historia_intro", "type": "info", "title": "¿Qué historia me contó mi mente?", "content": "Ahora elegí un momento tuyo. Puede ser uno que anotaste esta semana (con «Registrar cómo me siento» o en «Entender lo que me pasa») o algo que te pasó hace poco.\n\nVas a separar lo que pasó de la historia que te contó tu mente." }, { "id": "camara_vio", "type": "text", "prompt": "Lo que pasó: ¿qué vería una cámara?", "help": "Solo lo que se podría grabar. Por ejemplo: «Mi amiga no me saludó»." }, { "id": "historia", "type": "text", "prompt": "¿Qué historia me contó mi mente?", "help": "Por ejemplo: «Está enojada conmigo»." }, { "id": "trampa", "type": "choice", "prompt": "¿En qué trampa caí?", "help": "Si caíste en más de una, elegí la que más se nota.", "options": [ "Todo o nada (si no es perfecto, es un desastre)", "Leer la mente (creés saber lo que piensa el otro)", "Película de terror (imaginás lo peor como si ya hubiera pasado)", "Ponerse etiquetas (un error se vuelve lo que sos)", "Siempre o nunca (una vez se vuelve todas las veces)", "Lente oscuro (solo ves lo malo)", "Bola de cristal (das por seguro el futuro)", "Lo siento, entonces es así (confundís lo que sentís con lo que pasó)", "No estoy seguro/a" ] }, { "id": "cuanto_creo", "type": "scale", "prompt": "¿Cuánto me creo esa historia?", "help": "De 0 a 100 %.", "min": 0, "max": 100, "min_label": "Nada", "max_label": "Totalmente" }, { "id": "resumen", "type": "reflect", "title": "Lo que pasó y la historia", "template": "Una cámara vería: «{{camara_vio}}». Mi mente me contó: «{{historia}}». Trampa: {{trampa}}. En general caigo en: {{caigo_mas}}. La que más me pasa: {{la_que_mas}}.", "content": "Que algo sea un pensamiento no quiere decir que sea falso. Lo que sigue es ponerlo a prueba." }, { "id": "semana", "type": "info", "title": "Para esta semana", "content": "La tarea de esta semana está en el próximo ejercicio, **«Poner a prueba lo que pienso»** (10 a 15 minutos): vas a tomar un pensamiento que te haya pesado y ponerlo a prueba como un detective. Puede ser la historia que anotaste hoy.\n\nSi querés, antes repetí este ejercicio con otros momentos de tu registro." } ]$steps$::jsonb),
  ('brujula-poner-a-prueba', 'Poner a prueba lo que pienso', 'Revisá un pensamiento como un detective: datos a favor, en contra y una forma más justa de verlo.', 'thought_record', 'tcc', 'adolescentes', 'brujula', 12, 104,
   $steps$[ { "id": "intro", "type": "info", "title": "Pensar más completo", "content": "**No se trata de pensar lindo, sino de pensar más completo.**\n\nUn pensamiento no es verdad solo porque se siente fuerte. Ponelo a prueba como haría un detective: juntá datos a favor y en contra, y buscá una forma de verlo más realista.\n\nNo hace falta que sea positiva: alcanza con que sea más justa." }, { "id": "detective", "type": "info", "title": "Preguntas de detective", "content": "Estas preguntas te van a ayudar en cada paso:\n\n- ¿Qué pruebas tengo de que es así?\n- ¿Hay algo que no encaja?\n- ¿Hay otra explicación posible?\n- ¿Qué es lo peor, lo mejor y lo más probable?\n- ¿Qué le diría a alguien que quiero?\n- ¿Pensar así me ayuda con lo que quiero?" }, { "id": "lucas_1", "type": "info", "title": "Así lo hizo Lucas (15 años)", "content": "- **Situación:** desaprobó Matemática. Fue el día después de una pelea fuerte en casa.\n- **Pensamiento:** «Soy un burro, no sirvo para estudiar.»\n- **¿Cuánto lo creo?** 85 %.\n- **Emoción:** tristeza, 8 de 10.\n- **Lo que apoya el pensamiento:** «Desaprobé este examen.»\n- **Lo que no encaja:** «Aprobé Lengua y Sociales. Esa noche casi no dormí. Nunca pedí ayuda en Matemática.»" }, { "id": "lucas_2", "type": "info", "title": "Lucas sigue", "content": "- **Otra forma de verlo:** «Me fue mal en un día muy difícil, y Matemática me cuesta.»\n- **¿Qué le diría a alguien que quiero?** «Un examen no dice cuánto valés.»\n- **Pensamiento nuevo:** «Me fue mal en este examen y todavía no pedí ayuda. Puedo pedirla.»\n- **¿Cuánto creo ahora el pensamiento del principio?** 40 %.\n- **¿Cómo me siento ahora?** Tristeza, 5 de 10." }, { "id": "mi_turno", "type": "info", "title": "Mi turno", "content": "Ahora te toca a vos. Elegí un pensamiento que te haya pesado y seguí los mismos pasos que Lucas, una pregunta por vez.\n\n**Ojo:** esta hoja es para pensamientos, no para discutir si te trataron mal. Si alguien te lastimó o te hizo sentir menos, eso no se «corrige»: se cuenta. Para eso están «Cuando otros me hacen sentir menos» y «Mi red de apoyo»." }, { "id": "situation", "type": "text", "prompt": "Situación: ¿qué pasó?", "help": "Contalo con pocas palabras: qué pasó, cuándo, con quién.\n\nAsí lo hizo Lucas: desaprobó Matemática. Fue el día después de una pelea fuerte en casa." }, { "id": "thought", "type": "text", "prompt": "Pensamiento: ¿qué pensaste?", "help": "La frase que apareció en tu cabeza, tal cual.\n\nAsí lo hizo Lucas: «Soy un burro, no sirvo para estudiar.»" }, { "id": "belief_before", "type": "scale", "prompt": "¿Cuánto lo creés? (de 0 a 100 %)", "help": "Lucas: 85 %.", "min": 0, "max": 100, "min_label": "Nada", "max_label": "Totalmente" }, { "id": "emotion", "type": "checklist", "prompt": "Emoción: ¿qué sentiste?", "help": "Elegí hasta tres. Lucas sintió tristeza.", "options": [ "Bronca", "Tristeza", "Miedo", "Vergüenza", "Culpa", "Nervios", "Soledad", "Frustración", "Celos", "Alegría", "Calma", "Orgullo" ], "max": 3 }, { "id": "emotion_intensity", "type": "scale", "prompt": "¿Qué tan fuerte fue la emoción? (de 0 a 10)", "help": "Si marcaste más de una, puntuá la más fuerte. Lucas: tristeza, 8.", "min": 0, "max": 10, "min_label": "Nada", "max_label": "Muchísimo", "maps_to": "emotion_before" }, { "id": "evidence_for", "type": "text", "prompt": "¿Qué apoya el pensamiento?", "help": "Datos, como un detective: ¿qué pruebas tenés de que es así?\n\nAsí lo hizo Lucas: «Desaprobé este examen.»" }, { "id": "evidence_against", "type": "text", "prompt": "¿Qué no encaja con el pensamiento?", "help": "Preguntate: ¿hay algo que no encaja?\n\nAsí lo hizo Lucas: «Aprobé Lengua y Sociales. Esa noche casi no dormí. Nunca pedí ayuda en Matemática.»" }, { "id": "other_view", "type": "text", "prompt": "¿Hay otra forma de verlo?", "help": "Preguntate: ¿hay otra explicación posible? ¿Qué es lo peor, lo mejor y lo más probable?\n\nAsí lo hizo Lucas: «Me fue mal en un día muy difícil, y Matemática me cuesta.»" }, { "id": "friend", "type": "text", "prompt": "¿Qué le dirías a alguien que querés si pensara lo mismo?", "help": "Así lo hizo Lucas: «Un examen no dice cuánto valés.»" }, { "id": "new_thought", "type": "text", "prompt": "¿Cuál es tu pensamiento nuevo?", "help": "No hace falta que sea positivo: alcanza con que sea más justo. Preguntate también: ¿pensar así me ayuda con lo que quiero?\n\nAsí lo hizo Lucas: «Me fue mal en este examen y todavía no pedí ayuda. Puedo pedirla.»" }, { "id": "belief_after", "type": "scale", "prompt": "¿Cuánto creés ahora el pensamiento del principio? (de 0 a 100 %)", "help": "Lucas: 40 %.", "min": 0, "max": 100, "min_label": "Nada", "max_label": "Totalmente" }, { "id": "emotion_after", "type": "scale", "prompt": "¿Cómo te sentís ahora? (de 0 a 10)", "help": "Puntuá la misma emoción de antes. Lucas: tristeza, 5.", "min": 0, "max": 10, "min_label": "Nada", "max_label": "Muchísimo", "maps_to": "emotion_after" }, { "id": "summary", "type": "reflect", "title": "Tu hoja de detective", "template": "Pensamiento del principio: «{{thought}}». Lo que no encaja: «{{evidence_against}}». Otra forma de verlo: «{{other_view}}». Pensamiento nuevo: «{{new_thought}}».", "content": "Cuando toques «Terminar», tus respuestas quedan guardadas: las podés volver a ver en este ejercicio, en «Mis respuestas». Si en tu perfil está activado «Compartir mis registros con mi psicólogo», tu psicólogo/a también las puede ver." }, { "id": "semana", "type": "info", "title": "Para esta semana", "content": "**10 a 15 minutos.** Hacé «Mi turno» otra vez con un pensamiento que te haya pesado esta semana: volvé a este ejercicio y ponelo a prueba con las preguntas de detective.\n\nAcordate: no se trata de pensar lindo, sino de pensar más completo." } ]$steps$::jsonb),
  ('brujula-cuando-me-quiero-aislar', 'Cuando me quiero aislar', 'Salir del aislamiento con pasos chicos: ideas que no cuestan plata, tu escalera y un plan de 7 días.', 'custom', 'tcc', 'adolescentes', 'brujula', 10, 105,
   $steps$[ { "id": "intro", "type": "info", "title": "Encerrarse da alivio", "content": "**No esperes a tener ganas: da un paso chico y fijate qué pasa.**\n\nCuando estamos mal, encerrarnos da alivio. A veces es una forma de protegerse, y está bien.\n\nEl problema es cuando se vuelve lo único: hacemos cada vez menos y las ganas no vuelven solas." }, { "id": "circle", "type": "info", "title": "El círculo", "content": "Funciona como un círculo:\n\n1. **Evito, me aíslo.**\n2. **Alivio corto.**\n3. **Más aislamiento.**\n4. **Menos cosas buenas.**\n…y vuelve a empezar.\n\nPor eso, con el ánimo bajo, muchas veces primero viene la acción y después, de a poco, las ganas." }, { "id": "lucas", "type": "info", "title": "Lucas, 15 años", "content": "Después de las discusiones en casa, se encierra en la pieza. Dejó el fútbol.\n\nUn rato se siente mejor, pero los fines de semana se le hacen eternos." }, { "id": "ideas", "type": "checklist", "prompt": "Ideas que no cuestan plata: ¿cuáles te gustaría probar?", "help": "Cada idea tiene su letra:\n\n- **P: placer**, algo que disfrutás.\n- **L: logro**, algo que cuesta un poco y te deja conforme.\n- **C: conexión**, algo con otra persona.\n\nMarcá todas las que quieras.", "options": [ "Caminar o andar en bici (P)", "Escuchar música (P)", "Dibujar o escribir (P)", "Jugar al fútbol o al vóley (P, C)", "Tomar tereré con alguien (C)", "Ayudar en una tarea de la casa (L)", "Ordenar mi espacio (L)", "Estudiar 15 minutos (L)", "Salir al patio un rato (P)", "Jugar con una mascota (P)", "Escribirle a alguien (C)", "Retomar un hobby (P, L)" ] }, { "id": "escalera", "type": "info", "title": "Mi escalera", "content": "Una escalera va del paso más fácil al más difícil, hacia una meta tuya. Cada escalón es un paso chico.\n\nLa escalera de Lucas:\n\n- **1. Muy fácil:** mirar un entrenamiento desde afuera.\n- **2. Fácil:** escribirle al técnico.\n- **3. Medio:** ir a un entrenamiento.\n- **4. Difícil:** ir dos veces por semana." }, { "id": "goal", "type": "text", "prompt": "Mi escalera: ¿cuál es tu meta?", "help": "Algo tuyo a lo que te gustaría llegar, de a poco." }, { "id": "ladder", "type": "list", "prompt": "Escribí 4 escalones, del más fácil al más difícil", "help": "Uno por renglón, en orden: 1. Muy fácil · 2. Fácil · 3. Medio · 4. Difícil.\n\nLucas empezó por «mirar un entrenamiento desde afuera».", "count": 4 }, { "id": "plan_intro", "type": "info", "title": "Mi plan de 7 días", "content": "Ahora armá tu plan para esta semana: una actividad por día. Pueden ser ideas de la lista o escalones de tu escalera.\n\nDurante la semana vas a anotar tu ánimo antes y después de cada actividad, y cuánto logro sentiste, de 0 a 10." }, { "id": "plan", "type": "list", "prompt": "¿Qué actividad vas a hacer cada día?", "help": "Un renglón por día: el día, la actividad y su letra (P, L o C). Por ejemplo: «Lunes: escuchar música (P)».", "count": 7, "min": 3 }, { "id": "summary", "type": "reflect", "title": "Tu plan", "template": "Mi meta: «{{goal}}». Mi escalera, del paso más fácil al más difícil: {{ladder}}.", "content": "Cuando toques «Terminar», tu plan de 7 días queda guardado junto con tu escalera: lo podés volver a ver en este ejercicio, en «Mis respuestas»." }, { "id": "discovered", "type": "text", "prompt": "Lo que descubrí: ¿qué notaste en tu ánimo?", "help": "Si ya hiciste alguna actividad del plan, anotá qué pasó con tu ánimo antes y después. Si todavía no, tocá «Saltar»: la completás cuando vuelvas a este ejercicio al final de la semana.", "optional": true }, { "id": "semana", "type": "info", "title": "Para esta semana", "content": "**5 minutos por día.** Hacé al menos 3 actividades del plan. Después de cada una, anotá en «Registro de actividad» qué hiciste, tu ánimo antes y después (de 0 a 10) y cuánto logro sentiste.\n\nAl final de la semana, hacé este ejercicio de nuevo: armá el plan de la semana siguiente y anotá lo que descubriste.\n\nNo esperes a tener ganas: da un paso chico y fijate qué pasa." } ]$steps$::jsonb),
  ('brujula-no-todo-lo-que-pienso', 'No todo lo que pienso es una orden', 'Mirar tus pensamientos desde afuera: una frase que da distancia, «Hojas en el río» y nombrar la historia.', 'defusion', 'act', 'adolescentes', 'brujula', 10, 106,
   $steps$[ { "id": "intro", "type": "info", "title": "Una radio que no se apaga", "content": "**Tu mente habla todo el tiempo. No tenés que obedecer todo lo que dice.**\n\nLos pensamientos son como una radio que no se apaga. No los podés callar a la fuerza, pero podés escucharlos sin que te manejen.\n\nEn «Poner a prueba lo que pienso» discutías con el pensamiento; acá probás otra cosa: mirarlo desde afuera. Las dos herramientas sirven." }, { "id": "not_equal", "type": "info", "title": "Un pensamiento no es…", "content": "- **Pensamiento ≠ hecho.** Que lo pienses no lo vuelve verdad.\n- **Pensamiento ≠ orden.** Podés pensar «no vayas» e ir igual.\n- **Pensamiento ≠ quién sos.** Pensar «soy un fracaso» no te convierte en uno." }, { "id": "phrase", "type": "info", "title": "La frase que da distancia", "content": "Probá agregarle una frase adelante al pensamiento:\n\n- «Soy un fracaso.» → **«Estoy teniendo el pensamiento de que soy un fracaso.»**\n- «Todos se ríen de mí.» → **«Mi mente me está diciendo que todos se ríen de mí.»**\n\n**Ojo:** esto sirve para lo que pensás sobre vos, no para negar lo que pasó. Si se rieron de vos, eso pasó: contalo. Para eso están «Cuando otros me hacen sentir menos» y «Mi red de apoyo»." }, { "id": "thought", "type": "text", "prompt": "Probalo: escribí un pensamiento que te enganche", "help": "Escribilo tal cual aparece en tu cabeza. Por ejemplo: «soy un fracaso». En la pantalla siguiente le vas a agregar la frase adelante.", "placeholder": "Mi pensamiento…" }, { "id": "hook_before", "type": "scale", "prompt": "¿Cuánto te engancha ese pensamiento? (de 0 a 10)", "min": 0, "max": 10, "min_label": "Nada", "max_label": "Totalmente" }, { "id": "with_phrase", "type": "reflect", "title": "Ahora con la frase", "template": "«Estoy teniendo el pensamiento de que {{thought}}»", "content": "Leela despacio, una o dos veces. También podés probar con «Mi mente me está diciendo que…»." }, { "id": "hook_after", "type": "scale", "prompt": "¿Y ahora, con la frase, cuánto te engancha? (de 0 a 10)", "min": 0, "max": 10, "min_label": "Nada", "max_label": "Totalmente" }, { "id": "river", "type": "timed_info", "title": "Hojas en el río", "content": "**3 minutos.** Si preferís, imaginá nubes que cruzan el cielo.\n\n1. Imaginá un río tranquilo con hojas que pasan flotando.\n2. Cada vez que aparezca un pensamiento, ponelo en una hoja y dejá que el agua se lo lleve.\n3. Si te enganchás con uno, está bien: date cuenta y volvé al río.\n\nNo es para que los pensamientos desaparezcan ni para relajarte: es para practicar mirarlos desde afuera.\n\nCuando estés listo/a, tocá «Iniciar». Al terminar, la app pasa sola a la pantalla siguiente.", "seconds": 180 }, { "id": "leaves", "type": "list", "prompt": "¿Qué pensamientos aparecieron en las hojas?", "help": "Escribí uno por renglón, como si los pusieras en cada hoja.", "count": 5, "optional": true }, { "id": "story_name", "type": "text", "prompt": "¿Hay un pensamiento que vuelve siempre? Ponele nombre", "help": "Completá la frase «Ahí viene la historia de…» con un nombre corto.", "placeholder": "El nombre de la historia…", "optional": true }, { "id": "summary", "type": "reflect", "title": "Para mirar desde afuera", "template": "«Estoy teniendo el pensamiento de que {{thought}}». Y cuando vuelva el pensamiento de siempre: «Ahí viene la historia de {{story_name}}».", "content": "La próxima vez que aparezcan, probá decírtelo así. Podés volver a este ejercicio cuando quieras para probarlo con otros pensamientos.\n\nCuando toques «Terminar», tus respuestas quedan guardadas en este ejercicio, en «Mis respuestas»." }, { "id": "semana", "type": "info", "title": "Para esta semana", "content": "La tarea de esta semana está en el próximo ejercicio: **«Lo que realmente me importa»**.\n\nTu mente va a seguir hablando. No tenés que obedecer todo lo que dice." } ]$steps$::jsonb),
  ('brujula-lo-que-me-importa', 'Lo que realmente me importa', 'Diferenciar un valor de una meta, elegir tus 3 valores y una acción chiquita para cada uno esta semana.', 'values', 'act', 'adolescentes', 'brujula', 8, 107,
   $steps$[ { "id": "intro", "type": "info", "title": "Lo que realmente me importa", "content": "**Tus valores son como una brújula: no te dicen adónde llegar, te dicen hacia dónde ir.**\n\nUn valor es una dirección: algo que te importa y que podés vivir todos los días. Una meta es un punto concreto que se puede tachar.\n\nTus valores son tuyos, no los que otros esperan de vos. Y podés actuar según un valor aunque tengas miedo o pocas ganas." }, { "id": "quiz_value", "type": "choice", "prompt": "Vale dice: «Ser buena amiga». ¿Es un valor o una meta?", "options": [ "Un valor", "Una meta" ], "feedback": { "Un valor": "¡Sí! Es una dirección: no se termina nunca. Vale puede seguir siendo buena amiga todos los días.", "Una meta": "Mirá de nuevo: «ser buena amiga» no se hace una vez y se tacha. Es una dirección que no se termina nunca, así que es un valor." } }, { "id": "quiz_goal", "type": "choice", "prompt": "«Escribirle hoy a alguien que me importa». ¿Es un valor o una meta?", "options": [ "Un valor", "Una meta" ], "feedback": { "Una meta": "¡Exacto! Es un punto concreto: se hace y se tacha. Y va en la dirección del valor de Vale: ser buena amiga.", "Un valor": "Casi: es algo concreto que se hace hoy y se tacha, así que es una meta. El valor es la dirección (ser buena amiga) y la meta es un paso hacia ese lado." } }, { "id": "values_check", "type": "checklist", "prompt": "¿Qué te importa a vos?", "help": "Marcá los que más te importan.", "options": [ "Amigos", "Familia", "Estudio", "Salud", "Respeto", "Confianza", "Futuro", "Diversión", "Responsabilidad", "Ayudar", "Independencia", "Otro" ] }, { "id": "other_value", "type": "text", "prompt": "Si marcaste «Otro», ¿cuál es?", "placeholder": "Otro valor que me importa…", "optional": true }, { "id": "top_values", "type": "list", "prompt": "Mi brújula: elegí tus 3 valores más importantes", "help": "Pueden ser de los que marcaste recién. Uno por renglón.", "count": 3, "min": 3 }, { "id": "actions", "type": "list", "prompt": "Una acción chiquita para cada valor, esta semana", "help": "Una por renglón, en el mismo orden que tus valores. Que sea concreta y se pueda tachar, como «Escribirle hoy a alguien que me importa».", "count": 3, "min": 3 }, { "id": "brake", "type": "info", "title": "Si aparece un pensamiento que te frena", "content": "Cuando vayas a hacer la acción, puede aparecer un pensamiento que te frene. Acordate: podés actuar según un valor aunque tengas miedo o pocas ganas.\n\nUsá la frase de «No todo lo que pienso es una orden»:\n\n**«Estoy teniendo el pensamiento de que…»**\n\nY hacé la acción igual." }, { "id": "brake_thought", "type": "text", "prompt": "¿Qué pensamiento creés que podría frenarte?", "help": "Escribilo tal cual aparecería en tu cabeza. En la próxima pantalla lo vas a ver con la frase adelante.", "placeholder": "El pensamiento que me frena…", "optional": true }, { "id": "compass", "type": "reflect", "title": "Mi brújula", "template": "Mis valores: {{top_values}}. Mis acciones chiquitas para esta semana: {{actions}}. Si aparece un pensamiento que me frena, me digo: «Estoy teniendo el pensamiento de que {{brake_thought}}». Y hago la acción igual.", "content": "No te dice adónde llegar: te dice hacia dónde ir. Cuando termines, tu brújula queda guardada en «Mis respuestas» de este ejercicio, para que la mires durante la semana." }, { "id": "did_it", "type": "choice", "prompt": "¿Ya hiciste alguna de las tres acciones?", "help": "Si recién armaste tu brújula, es normal que todavía no.", "options": [ "Sí", "Todavía no" ], "feedback": { "Sí": "¡Bien! En la próxima pantalla contá qué pensamiento apareció y qué hiciste con él.", "Todavía no": "Está bien: son para esta semana. En la próxima pantalla tocá «Saltar»." } }, { "id": "what_happened", "type": "text", "prompt": "¿Qué pensamiento apareció y qué hiciste con él?", "help": "Si todavía no hiciste ninguna acción, tocá «Saltar».", "optional": true }, { "id": "semana", "type": "info", "title": "Para esta semana", "content": "**Unos 10 minutos.** Hacé al menos una de las tres acciones.\n\nSi aparece un pensamiento que te frena, usá la frase de «No todo lo que pienso es una orden» («Estoy teniendo el pensamiento de que…») y hacé la acción igual.\n\nDespués podés anotar qué pensamiento apareció y qué hiciste con él en «Registrar cómo me siento», o contarlo la próxima vez que hagas este ejercicio." } ]$steps$::jsonb),
  ('brujula-emocion-sube-a-100', 'Cuando la emoción sube a 100', 'Tu termómetro emocional, STOP y tu caja de herramientas para cuando la emoción sube mucho.', 'dbt_skill', 'dbt', 'adolescentes', 'brujula', 10, 108,
   $steps$[ { "id": "intro", "type": "info", "title": "Cuando la emoción sube a 100", "content": "**La emoción no es el enemigo: es información. Lo que importa es qué hacés cuando sube.**\n\nEn este ejercicio vas a conocer tu termómetro y una habilidad para frenar (STOP), y vas a armar tu caja de herramientas para los momentos en que la emoción sube mucho." }, { "id": "thermometer", "type": "info", "title": "Mi termómetro", "content": "Tu emoción puede ir de 0 a 10, como un termómetro. Según en qué número estés, te conviene hacer algo distinto:\n\n- **9–10: Seguridad y ayuda.** Buscá a una persona segura. Si pensás en hacerte daño, andá a «Mi plan para momentos muy difíciles» (lo encontrás en **Calmarme**).\n- **7–8: Primero, bajar la intensidad.** Usá STOP y algo de tu caja de herramientas.\n- **4–6: Necesito regular.** Ponele nombre a lo que sentís, respirá, hacé una pausa.\n- **0–3: Puedo pensar.** Es buen momento para usar «Poner a prueba lo que pienso», «No todo lo que pienso es una orden» o «Decir lo que necesito sin explotar ni callarme»." }, { "id": "now_band", "type": "choice", "prompt": "¿En qué número está tu termómetro ahora?", "options": [ "9–10", "7–8", "4–6", "0–3" ], "feedback": { "9–10": "**Seguridad y ayuda.** Buscá ya a una persona segura. Si pensás en hacerte daño, abrí «Mi plan para momentos muy difíciles»: lo encontrás en **Calmarme**.\n\nSi estás en peligro ahora, pedí ayuda ya a un adulto, a emergencias o en la guardia del hospital más cercano. En la app, la sección **Calmarme** tiene el recuadro «Si necesitás ayuda urgente» con los teléfonos.\n\nEste ejercicio puede esperar.", "7–8": "**Primero, bajar la intensidad.** Usá STOP y algo de tu caja de herramientas: los vas a ver en las próximas pantallas. En **Calmarme** tenés la «Respiración guiada» y el «Grounding 5-4-3-2-1». Podés volver a este ejercicio después.", "4–6": "**Necesitás regular.** Ponele nombre a lo que sentís, respirá, hacé una pausa. Después seguí con el ejercicio.", "0–3": "**Podés pensar.** Es un buen momento para seguir con este ejercicio y armar tu caja de herramientas." } }, { "id": "regulate", "type": "info", "title": "Regular no es reprimir", "content": "**Reprimir** es hacer como que no pasa y tragarse todo. Suele explotar después.\n\n**Regular** es notar la emoción, ponerle nombre, bajarle la intensidad y decidir qué hacer." }, { "id": "stop", "type": "info", "title": "STOP", "content": "Para cuando estás en 7 u 8, una letra por vez:\n\n- **S: Frená.** No hagas ni digas nada todavía.\n- **T: Tomá distancia.** Un paso atrás. Salí un momento si podés.\n- **O: Observá.** ¿Qué siento? ¿Qué pienso? ¿Qué está pasando?\n- **P: Procedé con conciencia.** ¿Qué me conviene hacer ahora?" }, { "id": "tobi", "type": "info", "title": "Tobi, 14 años", "content": "Vio que subieron una foto suya para burlarse. **Bronca: 9.** Quería ir a pegarle al que la subió.\n\nFrenó, salió del aula, respiró y se lo contó a la orientadora. **La bronca bajó a 6** y pudo pensar qué hacer.\n\nSi te pasa algo parecido, mirá también «Cuando otros me hacen sentir menos»." }, { "id": "toolbox", "type": "checklist", "prompt": "Mi caja de herramientas para cuando estoy en 8", "help": "Marcá las que te sirven. En la próxima pantalla agregás las tuyas.\n\n- **Respiración lenta:** inhalá contando 4 y exhalá contando 6, durante 1 o 2 minutos. Sirve para bajar un cambio y poder pensar.\n- **5-4-3-2-1:** nombrá 5 cosas que ves, 4 que podés tocar, 3 que escuchás, 2 que olés y 1 que saboreás.\n\nLas dos están en **Calmarme**, paso a paso: «Respiración guiada» y «Grounding 5-4-3-2-1».", "options": [ "Respiración lenta", "5-4-3-2-1", "Tomar agua despacio", "Cambiar de lugar (salir de la pieza, ir al patio)", "Hablar o escribirle a una persona segura", "Moverte un rato (caminar, subir escaleras)" ] }, { "id": "my_tools", "type": "text", "prompt": "Lo que a mí me sirve: ¿qué agregarías a tu caja?", "help": "Algo tuyo que te ayude a bajar cuando estás en 8, o la herramienta de la lista que más te sirve.", "placeholder": "Lo que a mí me sirve…" }, { "id": "signals", "type": "text", "prompt": "Mis señales de que estoy subiendo", "help": "¿Qué notás en tu **cuerpo**, en tus **pensamientos** y en **lo que hacés** cuando la emoción empieza a subir?", "placeholder": "En el cuerpo… En lo que pienso… En lo que hago…" }, { "id": "last_what", "type": "text", "prompt": "La última vez que llegué a 8: ¿qué pasó?", "help": "Contalo en pocas palabras. Si no te acordás de una vez en 8, pensá en la última vez que la emoción subió mucho." }, { "id": "last_did", "type": "text", "prompt": "¿Qué hiciste en ese momento?", "help": "Tal cual pasó. Es para entender, no para juzgarte." }, { "id": "last_try", "type": "text", "prompt": "¿Qué probarías la próxima vez?", "help": "Puede ser STOP o algo de tu caja de herramientas." }, { "id": "summary", "type": "reflect", "title": "Mi caja de herramientas", "template": "Mis señales de que estoy subiendo: {{signals}}. Mi caja para cuando estoy en 8: {{toolbox}}. Lo que a mí me sirve: {{my_tools}}. La próxima vez voy a probar: {{last_try}}.", "content": "Cuando notes esas señales, frená con STOP y abrí tu caja. Si llegás a 9 o 10, primero la seguridad: buscá a una persona segura y abrí tu plan para momentos muy difíciles.\n\nCuando termines, todo queda guardado en «Mis respuestas» de este ejercicio." }, { "id": "semana", "type": "info", "title": "Para esta semana", "content": "**Unos 5 minutos.** Usá STOP o una herramienta de tu caja una vez.\n\n- **Antes:** ¿en qué número de tu termómetro estás, de 0 a 10?\n- **Después:** ¿y ahora?\n\nPodés anotarlo en «Registrar cómo me siento».\n\nLa emoción no es el enemigo: es información." } ]$steps$::jsonb),
  ('brujula-decir-lo-que-necesito', 'Decir lo que necesito sin explotar ni callarme', 'Decir lo que necesitás de forma clara y respetuosa: la fórmula, cómo poner un límite y tu propia frase.', 'dbt_skill', 'dbt', 'adolescentes', 'brujula', 10, 109,
   $steps$[ { "id": "intro", "type": "info", "title": "Sin explotar ni callarme", "content": "**Ser asertivo no es ser agresivo: es decir lo que necesitás de forma clara y respetuosa.**\n\nCuando algo te molesta con otra persona, hay tres caminos:\n\n- **Callarme:** «No pasa nada», y por dentro sí pasa.\n- **Decirlo claro:** lo que pasa, lo que siento y lo que necesito.\n- **Explotar:** gritos, portazos, insultos." }, { "id": "formula", "type": "info", "title": "La fórmula", "content": "Para decirlo claro, usá estas cuatro partes:\n\n- **Cuando…** lo que pasa, sin insultos.\n- **me siento…** la emoción.\n- **necesito…** lo que me hace falta.\n- **te pido… o me ayudaría que…** algo concreto." }, { "id": "lucas", "type": "info", "title": "Así lo dijo Lucas (15 años)", "content": "«Cuando discutimos y todos empiezan a gritar, me siento muy tenso. Necesito poder terminar de explicar lo que pasó. Me ayudaría que podamos hablar de a uno.»\n\nParte por parte:\n\n- **Cuando** discutimos y todos empiezan a gritar,\n- **me siento** muy tenso.\n- **Necesito** poder terminar de explicar lo que pasó.\n- **Me ayudaría que** podamos hablar de a uno." }, { "id": "tips", "type": "info", "title": "Para que funcione mejor", "content": "- **Elegí el momento:** no en plena pelea.\n- **Sostené el tema sin subir el tono.** Si te cambian de tema, volvé con calma.\n- **Estate dispuesto/a a negociar:** buscá algo que sirva a los dos.\n- **Vos podés cuidar cómo lo decís.** Cómo reacciona el otro no depende de vos." }, { "id": "limit_info", "type": "info", "title": "Poner un límite", "content": "Poner un límite es decir hasta dónde sí y hasta dónde no.\n\n- **Con amigos:** «No quiero vapear. Si van a hacerlo, me voy un rato y después vuelvo».\n- **En casa:** «No quiero que me griten. Si pasa, me voy a mi pieza y hablamos cuando estemos más tranquilos»." }, { "id": "safety", "type": "info", "title": "Comunicar no siempre es la primera opción", "content": "Si en esa situación hay miedo, amenazas o violencia, **primero está tu seguridad**: buscá a un adulto seguro de «Mi red de apoyo» o pedí ayuda con «Mi plan para momentos muy difíciles» (lo abrís rápido desde **Calmarme**).\n\nSi estás en peligro ahora, pedí ayuda ya a un adulto, a emergencias o en la guardia del hospital más cercano. En la app, la sección **Calmarme** tiene el recuadro «Si necesitás ayuda urgente» con los teléfonos." }, { "id": "avoided", "type": "text", "prompt": "Tu turno: ¿qué conversación estás evitando?", "help": "Con quién y sobre qué, en pocas palabras.", "placeholder": "Una conversación que estoy evitando…" }, { "id": "usual", "type": "choice", "prompt": "En esa situación, ¿qué solés hacer?", "options": [ "Me callo", "Exploto", "Otra cosa" ], "feedback": { "Me callo": "Callarte es decir «no pasa nada» cuando por dentro sí pasa. La fórmula te ayuda a decirlo claro.", "Exploto": "Explotar es gritos, portazos, insultos. La fórmula te ayuda a decirlo claro, sin explotar.", "Otra cosa": "Si querés, contá en la próxima pantalla qué hacés." } }, { "id": "usual_other", "type": "text", "prompt": "Si elegiste «Otra cosa», ¿qué hacés?", "placeholder": "Lo que suelo hacer…", "optional": true }, { "id": "f_when", "type": "text", "prompt": "Armá tu frase: «Cuando…», ¿qué pasa?", "help": "Cómo podrías decirlo, parte por parte. Primero, lo que pasa, sin insultos. Seguí la frase sin volver a escribir «cuando».\n\nLucas: «Cuando **discutimos y todos empiezan a gritar**…»", "placeholder": "Lo que pasa, sin insultos…" }, { "id": "f_feel", "type": "text", "prompt": "«Me siento…»: ¿qué emoción?", "help": "Seguí la frase sin volver a escribir «me siento».\n\nLucas: «…me siento **muy tenso**.»", "placeholder": "La emoción…" }, { "id": "f_need", "type": "text", "prompt": "«Necesito…»: ¿qué te hace falta?", "help": "Seguí la frase sin volver a escribir «necesito».\n\nLucas: «Necesito **poder terminar de explicar lo que pasó**.»", "placeholder": "Lo que me hace falta…" }, { "id": "f_ask_start", "type": "choice", "prompt": "Para pedirlo, ¿qué te sale más natural?", "help": "Las dos sirven. Lucas eligió «Me ayudaría que…».", "options": [ "Te pido que", "Me ayudaría que" ] }, { "id": "f_ask", "type": "text", "prompt": "¿Qué cosa concreta pedís?", "help": "Seguí la frase sin volver a escribir el comienzo.\n\nLucas: «Me ayudaría que **podamos hablar de a uno**.»", "placeholder": "Algo concreto…" }, { "id": "phrase", "type": "reflect", "title": "Tu frase", "template": "«Cuando {{f_when}}, me siento {{f_feel}}. Necesito {{f_need}}. {{f_ask_start}} {{f_ask}}.»", "content": "Así podrías decirlo. Si algo no te suena a vos, volvé atrás y cambialo. Y acordate: elegí el momento, no en plena pelea." }, { "id": "my_limit", "type": "text", "prompt": "¿Qué límite necesitás?", "help": "Hasta dónde sí y hasta dónde no. Por ejemplo, en casa: «No quiero que me griten. Si pasa, me voy a mi pieza y hablamos cuando estemos más tranquilos».", "placeholder": "No quiero que… Si pasa, voy a…", "optional": true }, { "id": "is_safe", "type": "choice", "prompt": "¿Es seguro tener esta conversación?", "options": [ "Sí", "No sé", "No: primero lo hablo con mi psicólogo/a" ], "feedback": { "Sí": "Bien. Elegí un buen momento, no en plena pelea. Vos podés cuidar cómo lo decís; cómo reacciona el otro no depende de vos.", "No sé": "Está bien no estar seguro/a. Si hay miedo, amenazas o violencia, primero está tu seguridad: antes de hablar, contáselo a tu psicólogo/a o a un adulto seguro de «Mi red de apoyo».", "No: primero lo hablo con mi psicólogo/a": "Bien pensado: comunicar no siempre es la primera opción, y primero está tu seguridad. Cuando termines, tu frase queda guardada en «Mis respuestas» para hablarla en la próxima sesión. Si te sentís en peligro, buscá a un adulto seguro de «Mi red de apoyo» o abrí «Mi plan para momentos muy difíciles» desde **Calmarme**." } }, { "id": "how_it_went", "type": "text", "prompt": "¿Cómo te fue?", "help": "Si ya probaste la fórmula con algo chico, contá cómo te fue. Si todavía no, tocá «Saltar»: es la tarea para esta semana.", "optional": true }, { "id": "semana", "type": "info", "title": "Para esta semana", "content": "**Unos 5 minutos.** Probá la fórmula una vez con algo chico, no con la conversación más difícil.\n\nDespués anotá cómo te fue: podés hacerlo en «Registrar cómo me siento» o la próxima vez que hagas este ejercicio.\n\nSer asertivo no es ser agresivo: es decir lo que necesitás de forma clara y respetuosa." } ]$steps$::jsonb),
  ('brujula-cuando-me-hacen-sentir-menos', 'Cuando otros me hacen sentir menos', 'Distinguí conflicto, broma y bullying, ubicá lo que te pasa en el semáforo y armá tu plan anti-bullying.', 'custom', 'general', 'adolescentes', 'brujula', 15, 110,
   $steps$[ { "id": "intro", "type": "info", "title": "Cuando otros me hacen sentir menos", "content": "**El bullying no es culpa de quien lo sufre.**\n\nPrimero vas a ver la diferencia entre un conflicto, una broma y el bullying. Después, dónde está lo que te pasa y qué podés hacer.\n\nSi estás en peligro ahora, pedí ayuda ya a un adulto, a emergencias o en la guardia del hospital más cercano. En la app, la sección **Calmarme** tiene el recuadro «Si necesitás ayuda urgente» con los teléfonos." }, { "id": "tipos", "type": "info", "title": "Conflicto, broma o bullying", "content": "- **Conflicto.** Un desacuerdo entre personas que están a la par. Pasa a veces y se puede hablar.\n- **Broma.** Se ríen todos, también vos. Si pedís que pare, para.\n- **Bullying.** Se repite, es a propósito y el otro tiene más poder: es más fuerte, más popular o son varios.\n- **Cyberbullying.** Lo mismo, por celular o redes: mensajes, fotos, memes, grupos. Llega a cualquier hora y lo ve mucha gente." }, { "id": "semaforo", "type": "choice", "prompt": "El semáforo: ¿dónde está lo que te pasa?", "help": "- **Verde.** Un conflicto o una broma que no lastima. Se puede hablar o resolver.\n- **Amarillo.** Algo te molesta, se repite o no para cuando lo pedís.\n- **Rojo.** Amenazas, golpes, te dejan afuera a propósito una y otra vez, publican cosas tuyas, o te presionan para mandar fotos o hacer algo que no querés.\n\nSi ahora no te pasa nada de esto, podés saltear esta pregunta.", "options": [ "Verde", "Amarillo", "Rojo" ], "feedback": { "Verde": "**Verde: se puede hablar o resolver.** Un conflicto o una broma que no lastima pasa a veces. Si empieza a repetirse o no para cuando lo pedís, ya es amarillo.", "Amarillo": "**Amarillo: contáselo a alguien y anotá qué pasa.** En unos pasos vas a armar tu plan anti-bullying: a quién le vas a contar y qué.", "Rojo": "**Rojo: contáselo ya a un adulto seguro. No lo enfrentes solo/a.** Lo que te pasa no es culpa tuya.\n\nSi estás en peligro, abrí «Mi plan para momentos muy difíciles» desde **Calmarme** y pedí ayuda ya a un adulto, a emergencias o en la guardia del hospital más cercano. En la app, la sección **Calmarme** tiene el recuadro «Si necesitás ayuda urgente» con los teléfonos." }, "optional": true }, { "id": "redes", "type": "info", "title": "En redes", "content": "Si pasa por celular o redes:\n\n- Guardá capturas con la fecha.\n- No contestes en caliente.\n- Bloqueá y reportá.\n- Contáselo a un adulto.\n\n**No borres las pruebas.**" }, { "id": "tobi", "type": "info", "title": "Lo que pasó y lo que pensé sobre mí", "content": "**El hecho no se discute: se trabaja lo que te quedó pensando de vos.**\n\nAsí lo hizo Tobi, 14 años:\n\n- **Lo que pasó:** Se burlaron de mi cuerpo. Pasó, y estuvo mal.\n- **Lo que pensé sobre mí después:** «Entonces soy horrible.»\n- **Lo que me diría alguien que me quiere:** «Que se burlen habla de cómo tratan ellos, no de lo que valés.»\n- **Lo que elijo creer sobre mí:** «Me dolió. No me define.»\n\nAhora te toca a vos, con algo que te haya pasado." }, { "id": "que_paso", "type": "text", "prompt": "¿Qué pasó?", "help": "Contá el hecho. No hace falta discutirlo: si te trataron mal, estuvo mal.\n\nTobi escribió: «Se burlaron de mi cuerpo. Pasó, y estuvo mal.»" }, { "id": "pense", "type": "text", "prompt": "¿Qué pensaste sobre vos después?", "help": "Tobi pensó: «Entonces soy horrible.»" }, { "id": "alguien_quiere", "type": "text", "prompt": "¿Qué te diría alguien que te quiere?", "help": "A Tobi le dirían: «Que se burlen habla de cómo tratan ellos, no de lo que valés.»" }, { "id": "elijo_creer", "type": "text", "prompt": "¿Qué elegís creer sobre vos?", "help": "Tobi eligió: «Me dolió. No me define.»" }, { "id": "resumen_pense", "type": "reflect", "title": "Lo que pasó y lo que pensé sobre mí", "template": "Pasó esto: «{{que_paso}}». Después pensé: «{{pense}}». Alguien que me quiere me diría: «{{alguien_quiere}}». Elijo creer: «{{elijo_creer}}».", "content": "**El bullying no es culpa de quien lo sufre.**" }, { "id": "plan_intro", "type": "info", "title": "Mi plan anti-bullying", "content": "Ahora armá tu plan: a quién le vas a contar, qué le vas a contar y cómo cuidarte mientras tanto.\n\nSon seis preguntas cortas." }, { "id": "adulto_colegio", "type": "text", "prompt": "¿A qué adulto del colegio le vas a contar?", "help": "Puede ser un profe, el orientador o la orientadora, o alguien del colegio en quien confíes." }, { "id": "adulto_fuera", "type": "text", "prompt": "¿Y a qué adulto fuera del colegio?", "help": "Alguien de tu familia, tu psicólogo/a, tu entrenador/a, alguien del club o del barrio." }, { "id": "que_contar", "type": "text", "prompt": "¿Qué le vas a contar?", "help": "Si te sirve, usá lo que anotaste en «¿Qué pasó?»." }, { "id": "pruebas", "type": "text", "prompt": "¿Dónde guardás las pruebas?", "help": "Capturas con la fecha, mensajes, fotos. No las borres.\n\nSi no hay pruebas que guardar, podés saltear esta pregunta.", "optional": true }, { "id": "acompanado", "type": "text", "prompt": "¿Dónde y cuándo estás más acompañado/a?", "help": "Pensá en lugares y momentos del día." }, { "id": "companeros", "type": "text", "prompt": "¿Qué compañeros/as te hacen bien?", "help": "Si ahora no se te ocurre nadie, podés saltear esta pregunta.", "optional": true }, { "id": "resumen_plan", "type": "reflect", "title": "Mi plan anti-bullying", "template": "En el colegio le voy a contar a {{adulto_colegio}}, y fuera del colegio, a {{adulto_fuera}}. Les voy a contar: «{{que_contar}}». Las pruebas están en: {{pruebas}}. Estoy más acompañado/a: {{acompanado}}. Compañeros/as que me hacen bien: {{companeros}}.", "content": "Tu plan queda guardado: lo podés volver a ver en este ejercicio, en «Mis respuestas»." }, { "id": "otra_persona", "type": "info", "title": "¿Le pasa a otra persona?", "content": "Si ves que a alguien le pasa:\n\n- No te sumes.\n- Acompañala.\n- Avisá a un adulto." }, { "id": "semana", "type": "info", "title": "Para esta semana", "content": "La tarea de esta semana está en «Mi red de apoyo» (unos 10 minutos): vas a armar tu mapa de personas seguras y hablar con uno de los adultos de tu mapa. Si te está pasando algo de lo que viste acá, ese es el tema.\n\n**El bullying no es culpa de quien lo sufre.**" } ]$steps$::jsonb),
  ('brujula-red-de-apoyo', 'Mi red de apoyo', 'Armá tu mapa de personas seguras y anotá a quién podés recurrir según lo que te pase.', 'custom', 'general', 'adolescentes', 'brujula', 12, 111,
   $steps$[ { "id": "intro", "type": "info", "title": "Mi red de apoyo", "content": "**No todas las personas tienen que poder ayudarte con todo.**\n\nUna **persona segura** te escucha sin burlarse, no te lastima, te cree y puede ayudarte o buscar a alguien que pueda." }, { "id": "afuera", "type": "info", "title": "Si en tu casa no hay alguien así", "content": "Se puede buscar afuera:\n\n- Un profe.\n- El orientador o la orientadora.\n- Tu psicólogo/a.\n- Un médico o una médica.\n- Tu entrenador/a.\n- Un vecino o una vecina de confianza.\n- Alguien del club, de la iglesia o del barrio." }, { "id": "mapa_info", "type": "info", "title": "Tu mapa", "content": "Vas a armar un mapa con vos en el centro y tres zonas alrededor, de la más cercana a la más lejana:\n\n- **A quién le puedo contar algo.**\n- **A quién le puedo pedir ayuda.**\n- **Profesionales y adultos responsables.**\n\n**Meta: al menos 2 adultos.**\n\n**Tobi, 14:** en su mapa están su abuelo, el entrenador de básquet y la orientadora del colegio.\n\n**Tu mapa, tus reglas.** Si alguien te lastima o te da miedo, no tiene que estar en tu mapa." }, { "id": "zona_contar", "type": "list", "prompt": "¿A quién le puedo contar algo?", "help": "La zona más cercana a vos. Un nombre por renglón.", "count": 3, "min": 1 }, { "id": "zona_ayuda", "type": "list", "prompt": "¿A quién le puedo pedir ayuda?", "help": "La zona del medio. Un nombre por renglón.", "count": 3, "min": 1 }, { "id": "zona_profesionales", "type": "list", "prompt": "Profesionales y adultos responsables: ¿quiénes son?", "help": "La zona de afuera. Por ejemplo, tu psicólogo/a, un profe, el orientador o la orientadora, un médico o una médica, tu entrenador/a.", "count": 3, "min": 1 }, { "id": "meta", "type": "choice", "prompt": "¿Llegaste a la meta de al menos 2 adultos en tu mapa?", "options": [ "Sí", "Todavía no" ], "feedback": { "Sí": "**¡Bien!** Tenés más de un adulto a quien recurrir. No todas las personas tienen que poder ayudarte con todo.", "Todavía no": "**Está bien: es un punto de partida.** Mirá de nuevo quiénes pueden ser personas seguras fuera de tu casa (un profe, el orientador o la orientadora, tu entrenador/a, alguien del club, de la iglesia o del barrio) y, si querés, pensalo con tu psicólogo/a.\n\nPodés volver a este ejercicio y sumar nombres cuando quieras." } }, { "id": "temas_intro", "type": "info", "title": "¿Quién puede ayudarme con…?", "content": "Ahora pensá en temas concretos. Para cada uno, anotá una persona y cómo la contactás (en persona, por mensaje, en el colegio…).\n\nSi un tema no tiene que ver con vos, podés saltearlo." }, { "id": "tema_tristeza", "type": "text", "prompt": "Tristeza: ¿quién te puede ayudar y cómo la contactás?", "placeholder": "Persona y cómo la contacto", "optional": true }, { "id": "tema_bullying", "type": "text", "prompt": "Bullying: ¿quién te puede ayudar y cómo la contactás?", "help": "Si ya armaste tu plan anti-bullying en «Cuando otros me hacen sentir menos», podés usar lo que anotaste ahí.", "placeholder": "Persona y cómo la contacto", "optional": true }, { "id": "tema_casa", "type": "text", "prompt": "Problemas en casa: ¿quién te puede ayudar y cómo la contactás?", "placeholder": "Persona y cómo la contacto", "optional": true }, { "id": "tema_colegio", "type": "text", "prompt": "El colegio: ¿quién te puede ayudar y cómo la contactás?", "placeholder": "Persona y cómo la contacto", "optional": true }, { "id": "tema_consumo", "type": "text", "prompt": "Consumo (POD, alcohol u otras): ¿quién te puede ayudar y cómo la contactás?", "placeholder": "Persona y cómo la contacto", "optional": true }, { "id": "tema_crisis", "type": "text", "prompt": "Una crisis: ¿quién te puede ayudar y cómo la contactás?", "help": "Para los momentos muy difíciles también tenés «Mi plan para momentos muy difíciles», que se abre rápido desde **Calmarme**.\n\nSi estás en peligro ahora, pedí ayuda ya a un adulto, a emergencias o en la guardia del hospital más cercano. En la app, la sección **Calmarme** tiene el recuadro «Si necesitás ayuda urgente» con los teléfonos.", "placeholder": "Persona y cómo la contacto", "optional": true }, { "id": "resumen", "type": "reflect", "title": "Mi red de apoyo", "template": "Le puedo contar algo a: {{zona_contar}}. Le puedo pedir ayuda a: {{zona_ayuda}}. Profesionales y adultos responsables: {{zona_profesionales}}.", "content": "**Tu mapa, tus reglas.** Queda guardado, junto con a quién recurrir en cada tema: lo podés volver a ver en este ejercicio, en «Mis respuestas»." }, { "id": "semana", "type": "info", "title": "Para esta semana", "content": "**Unos 10 minutos.** Hablá con uno de los adultos de tu mapa, del tema que vos elijas.\n\nSi te está pasando algo de lo que vimos en «Cuando otros me hacen sentir menos», ese es el tema." } ]$steps$::jsonb),
  ('brujula-pod-vape-presion', 'POD, vape y presión de grupo', 'Entendé cómo funcionan las ganas, surfeá la ola con un plan de 10 minutos y practicá cómo decir que no.', 'custom', 'general', 'adolescentes', 'brujula', 18, 112,
   $steps$[ { "id": "intro", "type": "info", "title": "POD, vape y presión de grupo", "content": "**Tener ganas no es ser débil: es la forma en que aprende el cerebro.**\n\nSi no usás POD, este ejercicio igual te sirve: practicá cómo decir que no, o usalo con otra costumbre que te cueste frenar, como el celular." }, { "id": "nicotina", "type": "info", "title": "Cómo aprende el cerebro", "content": "Los POD suelen tener nicotina. La nicotina da un alivio rápido porque activa el sistema de recompensa del cerebro, y el cerebro aprende: «cuando me siento así, uso el POD».\n\nCon el tiempo, las ganas pueden aparecer más seguido y puede hacer falta más para sentir lo mismo. **Eso es la dependencia.**" }, { "id": "cadena", "type": "info", "title": "La cadena", "content": "**Disparador**\n↓\n**Pensamiento o emoción**\n↓\n**Ganas de vapear**\n↓\n**Uso el POD**\n↓\n**Alivio breve**\n\n…y la próxima vez es más probable que se repita." }, { "id": "vale_quiz", "type": "choice", "prompt": "En la cadena de Vale, ¿qué es «me relaja, me lo merezco»?", "help": "**Vale, 17:** vapea en la previa con sus amigas y antes de los exámenes. Piensa: «me relaja, me lo merezco». Ganas: 8 de 10.", "options": [ "Un disparador", "Un pensamiento", "Las ganas" ], "feedback": { "Un disparador": "**Es un pensamiento.** Los disparadores de Vale son las situaciones: la previa con sus amigas y antes de los exámenes. Después aparece lo que piensa, «me relaja, me lo merezco», y las ganas llegan a 8 de 10.", "Un pensamiento": "**¡Bien! Es un pensamiento.** Los disparadores de Vale son la previa con sus amigas y antes de los exámenes. Después aparece lo que piensa, «me relaja, me lo merezco», y las ganas llegan a 8 de 10.", "Las ganas": "**Es un pensamiento.** Las ganas son lo que Vale mide de 0 a 10: 8. «Me relaja, me lo merezco» es lo que piensa antes, después del disparador (la previa con sus amigas o los exámenes)." } }, { "id": "ola", "type": "info", "title": "Surfear la ola", "content": "Las ganas son como una ola: suben, llegan a un pico y bajan, aunque no hagas nada.\n\n**Aparecen → Suben → Llegan a un pico → Bajan → Pasan**\n\nNo hace falta que desaparezcan: alcanza con no seguirlas. Mientras tanto, observalas: ¿dónde las sentís? ¿Cuánto miden, de 0 a 10?" }, { "id": "plan_10", "type": "checklist", "prompt": "Mi plan de 10 minutos: ¿qué vas a hacer cuando aparezcan las ganas?", "help": "Marcá todo lo que pienses usar mientras pasa la ola.\n\nPara respirar lento podés usar «Respiración guiada», en **Calmarme**.", "options": [ "Espero 10 minutos (miro la hora)", "Me cambio de lugar", "Respiro lento", "Hago otra cosa con las manos o con el cuerpo", "Le escribo o hablo con alguien" ], "min": 1 }, { "id": "ganas_antes", "type": "scale", "prompt": "Ganas antes: ¿cuánto miden, de 0 a 10?", "help": "Completalo si tenés ganas ahora y vas a probar el plan. Si no, tocá «Saltar»: lo podés completar cuando vuelvas a este ejercicio.", "min": 0, "max": 10, "min_label": "Nada", "max_label": "Muchísimas", "optional": true }, { "id": "espera", "type": "timed_info", "title": "Espero 10 minutos", "content": "Si tenés ganas ahora, iniciá el temporizador y, mientras tanto, hacé lo que marcaste en tu plan.\n\nObservá la ola: sube, llega a un pico y baja.\n\nSi ahora no tenés ganas, tocá «Continuar».", "seconds": 600 }, { "id": "ganas_despues", "type": "scale", "prompt": "A los 10 minutos: ¿cuánto miden las ganas?", "help": "Comparalo con lo que marcaste antes. Si no probaste el plan todavía, tocá «Saltar».", "min": 0, "max": 10, "min_label": "Nada", "max_label": "Muchísimas", "optional": true }, { "id": "disparadores_intro", "type": "info", "title": "Mis disparadores", "content": "Ahora pensá en **una** vez que tuviste ganas y anotala paso a paso, como en la cadena.\n\nSi no usás POD, pensá en una vez que te ofrecieron, o en esa otra costumbre que te cuesta frenar." }, { "id": "disp_situacion", "type": "text", "prompt": "¿Cuál fue la situación?", "help": "Dónde estabas y qué estaba pasando. Para Vale: la previa, o antes de un examen." }, { "id": "disp_con_quien", "type": "text", "prompt": "¿Con quién estabas?", "help": "Vale, en la previa: con sus amigas." }, { "id": "disp_sentia", "type": "checklist", "prompt": "¿Qué sentías?", "help": "Elegí hasta 3 palabras.", "options": [ "Bronca", "Tristeza", "Miedo", "Vergüenza", "Culpa", "Nervios", "Soledad", "Frustración", "Celos", "Alegría", "Calma", "Orgullo" ], "min": 1, "max": 3 }, { "id": "disp_pense", "type": "text", "prompt": "¿Qué pensaste?", "help": "Vale pensó: «me relaja, me lo merezco»." }, { "id": "disp_ganas", "type": "scale", "prompt": "¿Cuántas ganas tenías, de 0 a 10?", "help": "Vale: 8 de 10.", "min": 0, "max": 10, "min_label": "Nada", "max_label": "Muchísimas" }, { "id": "disp_hice", "type": "text", "prompt": "¿Qué hiciste?", "help": "Sin juzgarte: solo anotá qué pasó." }, { "id": "decir_no", "type": "checklist", "prompt": "Decir que no sin quedar afuera: ¿qué frases te sirven?", "help": "Marcá las que te salgan más naturales.", "options": [ "«No, gracias, estoy bien así.»", "«Hoy paso, mañana tengo partido.»", "«No me pinta, pero me quedo un rato.»", "Cambiar de tema o proponer otra cosa: «¿Salimos a caminar?»" ], "min": 1 }, { "id": "mi_frase", "type": "text", "prompt": "Mi frase: ¿qué vas a decir la próxima vez?", "help": "Puede ser una de estas con tus palabras, o una tuya." }, { "id": "me_da", "type": "text", "prompt": "¿Qué te da el POD?", "help": "Si no usás POD, pensalo con esa costumbre que te cuesta frenar, o salteá esta pregunta.", "optional": true }, { "id": "me_cuesta", "type": "text", "prompt": "¿Y qué te cuesta?", "optional": true }, { "id": "desliz_intro", "type": "info", "title": "Si vuelvo a hacerlo", "content": "**Un desliz no borra todo lo que avanzaste.** Usalo para aprender.\n\nSi tuviste un desliz, respondé estas tres preguntas. Si no, podés saltearlas y volver cuando lo necesites." }, { "id": "desliz_antes", "type": "text", "prompt": "¿Qué pasó antes?", "optional": true }, { "id": "desliz_aprendi", "type": "text", "prompt": "¿Qué aprendiste?", "optional": true }, { "id": "desliz_proxima", "type": "text", "prompt": "¿Qué vas a probar la próxima vez?", "optional": true }, { "id": "resumen", "type": "reflect", "title": "Lo que armaste", "template": "Mi plan de 10 minutos: {{plan_10}}. Un disparador: «{{disp_situacion}}», y pensé: «{{disp_pense}}». Mi frase para decir que no: «{{mi_frase}}».", "content": "**Tener ganas no es ser débil: es la forma en que aprende el cerebro.**\n\nTodo queda guardado: lo podés volver a ver en este ejercicio, en «Mis respuestas»." }, { "id": "semana", "type": "info", "title": "Para esta semana", "content": "**Unos 10 minutos.** Anotá tus ganas 3 veces y probá el plan de 10 minutos una vez. Si no usás POD, practicá tu frase.\n\nPara anotar las ganas podés volver a este ejercicio, a «Mis disparadores»: cada vez queda guardado en «Mis respuestas». Traé lo que anotes a la sesión." } ]$steps$::jsonb),
  ('brujula-plan-momentos-dificiles', 'Mi plan para momentos muy difíciles', 'Un plan para ganar tiempo y conectar con ayuda en los momentos más difíciles. Lo armás con tu psicólogo/a.', 'custom', 'general', 'adolescentes', 'brujula', 15, 113,
   $steps$[ { "id": "para_que", "type": "info", "title": "Mi plan para momentos muy difíciles", "content": "**Un plan para ganar tiempo y conectar con ayuda.**\n\nEste plan lo armás con tu psicólogo/a y, si se puede, con un adulto de confianza. No reemplaza una evaluación profesional.\n\nTiene seis partes, una por pantalla. Si alguna te cuesta, la pueden completar juntos en la sesión." }, { "id": "pedi_ayuda_ya", "type": "info", "title": "Pedí ayuda ya si…", "content": "**Pedí ayuda ya a un adulto, a emergencias o en la guardia del hospital más cercano, si:**\n\n- pensás en quitarte la vida y tenés intención o un plan;\n- te hiciste daño o tomaste algo para hacerte daño;\n- estás intoxicado/a o tenés una lesión importante;\n- sentís que no podés mantenerte a salvo.\n\n**Para hablar con alguien ahora**, también hay una línea de crisis en salud mental, gratis y las 24 horas.\n\nEn la app, la sección **Calmarme** tiene el recuadro «Si necesitás ayuda urgente» con los teléfonos." }, { "id": "senales", "type": "list", "prompt": "Señales de que estoy empezando a estar mal", "help": "**Parte 1 de 6.** Una señal por renglón: algo que notás en tu cuerpo, en lo que pensás o en lo que hacés.\n\nPodés usar tus señales de «Cuando la emoción sube a 100».", "count": 4, "min": 1 }, { "id": "cosas_solo", "type": "list", "prompt": "Cosas que puedo hacer solo/a para ganar tiempo", "help": "**Parte 2 de 6.** Una por renglón. Por ejemplo, algo de tu caja de herramientas de «Cuando la emoción sube a 100» o de **Calmarme**.", "count": 4, "min": 1 }, { "id": "lugares_personas", "type": "list", "prompt": "Lugares y personas que me ayudan a distraerme o calmarme", "help": "**Parte 3 de 6.** Uno por renglón.", "count": 4, "min": 1 }, { "id": "adultos", "type": "list", "prompt": "Adultos a quienes les puedo pedir ayuda", "help": "**Parte 4 de 6.** En cada renglón, el **nombre** y el **teléfono** de un adulto.\n\nPodés usar los adultos de tu mapa de «Mi red de apoyo».", "count": 4, "min": 1 }, { "id": "psicologo", "type": "text", "prompt": "Profesionales y servicios: mi psicólogo/a", "help": "**Parte 5 de 6.** Su nombre y su teléfono.\n\nLos teléfonos de emergencias y de la línea de crisis en salud mental ya están en **Calmarme**, en el recuadro «Si necesitás ayuda urgente».", "placeholder": "Nombre y teléfono…", "optional": true }, { "id": "guardia", "type": "text", "prompt": "Profesionales y servicios: guardia del hospital más cercano", "help": "Cuál es y su teléfono.", "placeholder": "Hospital y teléfono…", "optional": true }, { "id": "otro_servicio", "type": "text", "prompt": "Profesionales y servicios: otro servicio", "help": "Si hay otro servicio que te pueda ayudar, su nombre y su teléfono.", "placeholder": "Servicio y teléfono…", "optional": true }, { "id": "entorno", "type": "text", "prompt": "Cómo hacer mi entorno más seguro: lo acordé con…", "help": "**Parte 6 de 6.** Con un adulto de confianza, acordar que guarde lo que podría usarse para hacerte daño. Escribí con quién lo acordaste.\n\nSi todavía no lo acordaste con nadie, hablalo con tu psicólogo/a.", "placeholder": "Lo acordé con…", "optional": true }, { "id": "importa", "type": "text", "prompt": "Algo que me importa y me ayuda a seguir", "help": "Podés mirar tu brújula de «Lo que realmente me importa».", "optional": true }, { "id": "si_peligro", "type": "info", "title": "Algo importante", "content": "Si tu psicólogo/a cree que estás en peligro, va a buscar ayuda con un adulto responsable. Siempre que se pueda, lo va a hablar antes con vos." }, { "id": "mi_plan", "type": "reflect", "title": "Mi plan", "template": "Mis señales de que estoy empezando a estar mal: {{senales}} — Lo que puedo hacer solo/a para ganar tiempo: {{cosas_solo}} — Lugares y personas que me ayudan a distraerme o calmarme: {{lugares_personas}} — Adultos a quienes les puedo pedir ayuda: {{adultos}}", "content": "Tu plan completo queda guardado en este ejercicio, en «Mis respuestas». Tu psicólogo/a solo lo puede ver si activaste **«Compartir mis registros con mi psicólogo»** en tu perfil." }, { "id": "semana", "type": "info", "title": "Para esta semana", "content": "**Unos 10 minutos.** Copiá este plan en un papel que tengas siempre a mano. Sumale los teléfonos del recuadro «Si necesitás ayuda urgente», en **Calmarme**.\n\nTambién queda guardado en la app y lo podés abrir rápido desde **Calmarme**, en «Mi plan para momentos muy difíciles». Si cambia algo, como una persona o un teléfono, lo podés actualizar desde ahí.\n\n**Si estás en peligro ahora**, pedí ayuda ya a un adulto, a emergencias o en la guardia del hospital más cercano." } ]$steps$::jsonb),
  ('brujula-lo-que-aprendi', 'Lo que aprendí y mi plan para seguir', 'Para mirar cuánto recorriste, elegir tus herramientas y armar tu plan para seguir.', 'custom', 'general', 'adolescentes', 'brujula', 15, 114,
   $steps$[ { "id": "intro", "type": "info", "title": "Lo que aprendí y mi plan para seguir", "content": "**Mirá cuánto recorriste.**\n\nPrimero vas a comparar cómo estás ahora con cómo estabas al empezar. Después vas a pensar qué aprendiste, elegir tus herramientas y armar tu plan para seguir." }, { "id": "antes_ahora", "type": "info", "title": "Antes y ahora", "content": "Son las mismas siete preguntas de «Mi punto de partida», de 0 a 10.\n\nLo que contestaste ahí está guardado en ese ejercicio, en «Mis respuestas». Miralo antes o después para comparar.\n\n**Si algo no cambió o empeoró, no es un fracaso: es información para seguir.**" }, { "id": "ahora_animo", "type": "scale", "prompt": "¿Cómo estoy ahora de ánimo?", "help": "Elegí un número: 0 es muy mal y 10 es muy bien.", "min": 0, "max": 10, "min_label": "Muy mal", "max_label": "Muy bien", "optional": true }, { "id": "ahora_nervios", "type": "scale", "prompt": "¿Cómo estoy ahora con los nervios o la ansiedad?", "help": "Acá el 0 es «me desbordan» y el 10 es «los manejo bien».", "min": 0, "max": 10, "min_label": "Me desbordan", "max_label": "Los manejo bien", "optional": true }, { "id": "ahora_relaciones", "type": "scale", "prompt": "¿Cómo estoy ahora en mis relaciones?", "help": "Amigos, compañeros. 0 es muy mal y 10 es muy bien.", "min": 0, "max": 10, "min_label": "Muy mal", "max_label": "Muy bien", "optional": true }, { "id": "ahora_familia", "type": "scale", "prompt": "¿Cómo estoy ahora con mi familia?", "help": "0 es muy mal y 10 es muy bien.", "min": 0, "max": 10, "min_label": "Muy mal", "max_label": "Muy bien", "optional": true }, { "id": "ahora_colegio", "type": "scale", "prompt": "¿Cómo estoy ahora en el colegio?", "help": "0 es muy mal y 10 es muy bien.", "min": 0, "max": 10, "min_label": "Muy mal", "max_label": "Muy bien", "optional": true }, { "id": "ahora_confianza", "type": "scale", "prompt": "¿Cómo estoy ahora con la confianza en mí?", "help": "0 es muy mal y 10 es muy bien.", "min": 0, "max": 10, "min_label": "Muy mal", "max_label": "Muy bien", "optional": true }, { "id": "ahora_emociones", "type": "scale", "prompt": "¿Cómo estoy ahora con el manejo de mis emociones?", "help": "0 es muy mal y 10 es muy bien.", "min": 0, "max": 10, "min_label": "Muy mal", "max_label": "Muy bien", "optional": true }, { "id": "entendi", "type": "text", "prompt": "¿Qué entendí sobre mí?", "help": "Ahora, cinco preguntas para mirar lo que aprendiste. Escribí como te salga." }, { "id": "funciona_mejor", "type": "text", "prompt": "¿Qué herramienta me funciona mejor?", "help": "Puede ser de cualquier ejercicio de Brújula o de **Calmarme**." }, { "id": "siguen_dificiles", "type": "text", "prompt": "¿Qué situaciones siguen siendo difíciles?" }, { "id": "pedir_ayuda", "type": "text", "prompt": "¿Cuándo sé que necesito pedir ayuda?", "help": "Podés mirar tus señales en «Mi plan para momentos muy difíciles»." }, { "id": "seguir_practicando", "type": "text", "prompt": "¿Qué quiero seguir practicando?" }, { "id": "herramientas", "type": "list", "prompt": "Mis 5 herramientas", "help": "Una por renglón, con el nombre del ejercicio donde está. Por ejemplo: STOP, de «Cuando la emoción sube a 100».", "count": 5, "min": 1 }, { "id": "sentir_mal_intro", "type": "info", "title": "Si me empiezo a sentir mal otra vez", "content": "Vas a armar una frase en tres partes:\n\n- **Si noto…**\n- **voy a…**\n- **y voy a hablar con…**" }, { "id": "si_noto", "type": "text", "prompt": "Si noto…", "help": "Una señal de que estás empezando a estar mal: en tu cuerpo, en lo que pensás o en lo que hacés.", "placeholder": "Si noto…" }, { "id": "voy_a", "type": "text", "prompt": "voy a…", "help": "Algo que vas a hacer: por ejemplo, una de tus herramientas.", "placeholder": "voy a…" }, { "id": "hablar_con", "type": "text", "prompt": "y voy a hablar con…", "help": "Una persona de confianza.", "placeholder": "y voy a hablar con…" }, { "id": "frase", "type": "reflect", "title": "Si me empiezo a sentir mal otra vez", "template": "Si noto {{si_noto}}, voy a {{voy_a}} y voy a hablar con {{hablar_con}}." }, { "id": "proximo_paso", "type": "text", "prompt": "Mi próximo paso", "help": "Algo concreto, que se pueda ver desde afuera.", "placeholder": "Mi próximo paso es…" }, { "id": "resumen", "type": "reflect", "title": "Mirá cuánto recorriste", "template": "Lo que entendí sobre mí: «{{entendi}}» — Lo que quiero seguir practicando: «{{seguir_practicando}}» — Mis herramientas: {{herramientas}} — Mi próximo paso: «{{proximo_paso}}»", "content": "Todo queda guardado en este ejercicio, en «Mis respuestas». Para comparar, mirá también tus respuestas de «Mi punto de partida»." }, { "id": "recorda", "type": "info", "title": "Recordá", "content": "**Pedir ayuda también es una habilidad.**\n\nSi un día lo necesitás, tu plan para momentos muy difíciles está en **Calmarme**." } ]$steps$::jsonb),
  ('brujula-registro-actividad', 'Registro de actividad', 'Anotá una actividad de tu plan: tu ánimo antes y después, y cuánto logro sentiste.', 'custom', 'tcc', 'adolescentes', 'brujula', 3, 150,
   $steps$[ { "id": "intro", "type": "info", "title": "Mi plan de 7 días", "content": "Usá este registro cada vez que hagas una actividad de tu plan de «Cuando me quiero aislar». Son menos de 3 minutos.\n\nCon el ánimo bajo, muchas veces primero viene la acción y después, de a poco, las ganas. Anotarlo te ayuda a ver qué te hace bien." }, { "id": "activity", "type": "text", "prompt": "¿Qué actividad hiciste?", "help": "Por ejemplo: «Caminé 15 minutos», «Le escribí a Martina», «Ordené mi escritorio».", "placeholder": "Lo que hice" }, { "id": "type", "type": "checklist", "prompt": "¿Qué tipo de actividad fue?", "help": "Puede ser más de uno.", "options": [ "P: placer, algo que disfrutás", "L: logro, algo que cuesta un poco y te deja conforme", "C: conexión, algo con otra persona" ] }, { "id": "mood_before", "type": "scale", "prompt": "¿Cómo estaba tu ánimo antes?", "min": 0, "max": 10, "min_label": "Muy bajo", "max_label": "Muy bien" }, { "id": "mood_after", "type": "scale", "prompt": "¿Y después?", "min": 0, "max": 10, "min_label": "Muy bajo", "max_label": "Muy bien" }, { "id": "achievement", "type": "scale", "prompt": "¿Cuánto logro sentiste?", "min": 0, "max": 10, "min_label": "Nada", "max_label": "Mucho" }, { "id": "discovered", "type": "text", "prompt": "¿Qué descubriste?", "help": "¿Cambió algo en tu ánimo? ¿Te costó empezar? Si no cambió nada, también es información.", "optional": true }, { "id": "summary", "type": "reflect", "title": "Guardado en tu plan", "template": "Hice: {{activity}}.", "content": "Lo podés volver a ver en «Mis respuestas», con el ánimo de antes y de después. Traelo a la sesión: nos ayuda a ver qué te sirve." } ]$steps$::jsonb),
  ('tcc-antes-de-empezar', 'Antes de empezar', 'Qué vas a aprender, por qué funciona la TCC, qué dice la evidencia y cómo usar este cuadernillo.', 'custom', 'tcc', 'adultos', 'tcc', 8, 200,
   $steps$[ { "id": "bienvenida", "type": "info", "title": "Antes de empezar", "content": "Este cuadernillo es una guía práctica para entender cómo pensamos, cómo eso influye en lo que sentimos y hacemos, y cómo podemos aprender a intervenir sobre ese proceso.\n\nEstá escrito en dos niveles al mismo tiempo: uno cercano, para cualquier persona que quiera empezar a trabajar sobre su bienestar, y otro más técnico, para estudiantes y colegas en formación. En la app, la parte técnica aparece en pantallas tituladas **«Para profundizar»**." }, { "id": "que_vas_a_aprender", "type": "info", "title": "¿Qué vas a aprender?", "content": "A lo largo de estos capítulos vas a recorrer, paso a paso, las herramientas centrales de la Terapia Cognitivo-Conductual (TCC).\n\nCada capítulo combina:\n\n- una explicación simple;\n- una explicación clínica;\n- señales para reconocer el fenómeno en la vida diaria;\n- ejemplos;\n- un caso desarrollado;\n- un ejercicio guiado;\n- hojas de trabajo para completar." }, { "id": "temas", "type": "info", "title": "Los siete temas", "content": "- **El modelo cognitivo:** cómo la interpretación de una situación —y no la situación en sí— moldea la emoción y la conducta.\n- **Los pensamientos automáticos:** esas ideas rápidas que aparecen sin que las llamemos y tiñen nuestro estado de ánimo.\n- **Las distorsiones cognitivas:** los errores sistemáticos con los que la mente deforma la información.\n- **Las creencias intermedias y nucleares:** las reglas profundas desde las que interpretamos el mundo.\n- **El cuestionamiento socrático y la reestructuración cognitiva:** cómo poner a prueba un pensamiento y construir alternativas más útiles y ajustadas.\n- **El modelo ABC de Ellis:** una forma complementaria de mirar el mismo proceso.\n- **La tríada cognitiva y la activación conductual:** cómo entender la depresión y cómo salir del círculo de la inactividad." }, { "id": "por_que", "type": "info", "title": "¿Por qué funcionan estas herramientas?", "content": "La idea central de la TCC es sencilla de enunciar y poderosa en la práctica: entre lo que nos pasa y lo que sentimos hay siempre un paso intermedio, **la interpretación**.\n\nNo reaccionamos a los hechos en bruto, sino al significado que les damos. Como ese significado puede aprenderse, examinarse y modificarse, también puede cambiar la forma en que nos sentimos y actuamos." }, { "id": "como_usar", "type": "info", "title": "Cómo usar este cuadernillo", "content": "Cada capítulo es un ejercicio de esta colección y termina con preguntas para completar, tareas para casa y preguntas de reflexión. El material rinde cuando lo completás, no solo cuando lo leés.\n\nAvanzá a tu ritmo: podés dedicar una semana a cada capítulo.\n\nAl final de la colección están los **registros** (los anexos del cuadernillo): podés repetirlos las veces que quieras.\n\nSi sos terapeuta en formación, podés usar las hojas y los casos como recursos para sesión y como plantillas para tus pacientes." }, { "id": "tus_respuestas", "type": "info", "title": "Tus respuestas", "content": "Lo que escribas en cada ejercicio queda guardado. Lo podés volver a ver cuando quieras, entrando al ejercicio, en **«Mis respuestas»**.\n\nTu psicólogo solo puede ver tus respuestas si activás **«Compartir mis registros con mi psicólogo»** en tu perfil." }, { "id": "evidencia", "type": "info", "title": "La evidencia detrás de la TCC", "content": "La TCC es uno de los enfoques psicoterapéuticos más estudiados. Nació del trabajo de Aaron T. Beck en la depresión durante los años sesenta y setenta, y del modelo racional-emotivo de Albert Ellis, desarrollado en paralelo desde mediados de los cincuenta. Desde entonces se ha investigado y refinado para un amplio rango de problemas.\n\nRevisiones y metaanálisis han mostrado que produce beneficios clínicamente relevantes en depresión y en los trastornos de ansiedad, con tamaños de efecto que suelen ubicarse en el rango moderado a grande. Guías como las del *National Institute for Health and Care Excellence* (NICE) del Reino Unido la recomiendan como tratamiento de primera línea para varios cuadros, y la *American Psychological Association* (APA) la incluye entre los tratamientos con apoyo empírico." }, { "id": "aclaracion", "type": "info", "title": "Una aclaración honesta sobre la evidencia", "content": "La TCC es eficaz para muchas personas, pero **no es mágica ni universal**. Su efecto varía según el problema, la calidad del vínculo terapéutico y el compromiso con la práctica.\n\nEste cuadernillo es un recurso psicoeducativo y de autoayuda guiada; no reemplaza una evaluación ni un tratamiento profesional. Si atravesás un malestar intenso o persistente, buscá acompañamiento.\n\nEn caso de crisis, pedí ayuda ya a emergencias o en la guardia del hospital más cercano. En la app, la sección **Calmarme** tiene el recuadro «Si necesitás ayuda urgente» con los teléfonos." }, { "id": "faq_1", "type": "info", "title": "Preguntas frecuentes (1 de 2)", "content": "**¿Esto reemplaza a la terapia?**\n\nNo. Es un recurso de psicoeducación y autoayuda guiada. Puede acompañar un proceso terapéutico o ayudarte a empezar a observar tu funcionamiento, pero no sustituye una evaluación ni un tratamiento profesional.\n\n**¿Tengo que hacer todos los ejercicios?**\n\nCuantos más hagas, más vas a notar el cambio. Si tenés poco tiempo, priorizá el «Registro de pensamientos (RPD)», el «Registro ABC» y la hoja de reestructuración de «Cuestionamiento socrático y reestructuración»: son el corazón del método." }, { "id": "faq_2", "type": "info", "title": "Preguntas frecuentes (2 de 2)", "content": "**¿Y si un pensamiento no cambia por más que lo cuestiono?**\n\nEs normal. Algunos pensamientos se sostienen en creencias profundas (lo vas a ver en «Creencias intermedias y nucleares») o necesitan un experimento en la vida real, no solo un debate mental. La constancia y, si hace falta, el acompañamiento profesional marcan la diferencia.\n\n**¿Esto es «pensar en positivo»?**\n\nNo. Buscamos pensamientos ajustados y creíbles, no optimistas a la fuerza. La meta es ver la realidad completa —lo bueno y lo malo— en lugar de solo la mitad negativa." }, { "id": "mapa", "type": "info", "title": "Un mapa del recorrido", "content": "- **1. El modelo cognitivo:** entender la relación situación–pensamiento–emoción–conducta–fisiología.\n- **2. Los pensamientos automáticos:** detectar y registrar las ideas rápidas que disparan el malestar.\n- **3. Las distorsiones cognitivas:** reconocer los errores típicos del pensamiento.\n- **4. Creencias intermedias y nucleares:** llegar a las reglas y creencias de fondo.\n- **5. Cuestionamiento socrático y reestructuración:** poner a prueba pensamientos y construir alternativas.\n- **6. El modelo ABC de Ellis:** una mirada complementaria del mismo proceso.\n- **7. Tríada cognitiva y activación conductual:** comprender la depresión y volver a la acción.\n\nDespués vienen los registros para repetir y, para consultar, «50 preguntas socráticas» y el «Glosario de TCC»." }, { "id": "empezar", "type": "choice", "prompt": "¿Por qué capítulo te gustaría empezar?", "help": "No hay respuesta correcta. Los capítulos están pensados para recorrerse paso a paso, en orden, pero lo podés hablar con tu psicólogo.", "optional": true, "options": [ "1. El modelo cognitivo", "2. Los pensamientos automáticos", "3. Las distorsiones cognitivas", "4. Creencias intermedias y nucleares", "5. Cuestionamiento socrático y reestructuración", "6. El modelo ABC de Ellis", "7. Tríada cognitiva y activación conductual", "Todavía no lo sé" ] }, { "id": "siguiente", "type": "info", "title": "Tu próximo paso", "content": "Cuando quieras, seguí con el capítulo 1, **«El modelo cognitivo»**. Es la base de todo lo que viene después.\n\nAvanzá a tu ritmo y llevá tus dudas a la próxima sesión." } ]$steps$::jsonb),
  ('tcc-modelo-cognitivo', 'El modelo cognitivo', 'Entendé cómo la interpretación de lo que pasa moldea lo que sentís y hacés, y hacé tu primer desglose.', 'custom', 'tcc', 'adultos', 'tcc', 20, 201,
   $steps$[ { "id": "intro", "type": "info", "title": "El modelo cognitivo de Beck", "content": "No nos alteran las cosas que pasan, sino **la lectura que hacemos de ellas**.\n\nEse es el corazón del modelo que Aaron T. Beck construyó a partir de su trabajo con personas con depresión." }, { "id": "ruido", "type": "info", "title": "Un ruido de noche", "content": "Imaginá que estás en casa de noche y escuchás un ruido fuerte.\n\nSi pensás «entró alguien», vas a sentir miedo, el corazón se acelera y quizás buscás algo para defenderte. Si pensás «fue el gato que tiró algo», te quedás tranquilo y seguís con lo tuyo.\n\nEl ruido fue el mismo; lo que cambió fue el pensamiento. Y ese pensamiento cambió la emoción, el cuerpo y la conducta.\n\nEl modelo cognitivo dice justamente eso: entre lo que ocurre y lo que sentimos siempre se cuela una interpretación. Muchas veces es tan rápida y automática que ni la notamos, pero está ahí, dirigiendo la escena." }, { "id": "esquema", "type": "info", "title": "El esquema básico", "content": "**Situación → Pensamiento → Emoción + Respuesta física → Conducta**\n\nEl pensamiento es la bisagra. Trabajar sobre él es trabajar sobre todo lo demás.\n\nEn el ejemplo del ruido:\n\n- **Situación:** un ruido fuerte, de noche, en casa.\n- **Pensamiento:** «entró alguien».\n- **Emoción:** miedo.\n- **Respuesta física:** el corazón se acelera.\n- **Conducta:** buscás algo para defenderte." }, { "id": "clinica_1", "type": "info", "title": "Para profundizar (1 de 2)", "content": "*Explicación clínica. Si preferís, pasá a la pantalla siguiente.*\n\nEl modelo cognitivo propone que el procesamiento de la información media la respuesta emocional y conductual. Ante un estímulo (interno o externo), la persona activa **esquemas** —estructuras cognitivas de significado— que orientan la atención, la interpretación y la memoria, y que se expresan en pensamientos automáticos situacionales. Estos pensamientos generan respuestas emocionales, fisiológicas y conductuales que, a su vez, retroalimentan el sistema." }, { "id": "clinica_2", "type": "info", "title": "Para profundizar (2 de 2)", "content": "En su formulación más reciente (Beck y Haigh, 2014), el modelo subraya el carácter continuo entre respuestas normales y disfuncionales: no hay pensamientos «anormales», sino sesgos de interpretación que, cuando se vuelven rígidos, excesivos o desajustados respecto de la evidencia, sostienen el malestar. El objetivo no es «pensar en positivo», sino recuperar flexibilidad y ajuste.\n\nNiveles de cognición, de menor a mayor profundidad:\n\n- **Pensamientos automáticos:** superficiales, situacionales.\n- **Creencias intermedias:** reglas, supuestos y actitudes.\n- **Creencias nucleares:** esquemas absolutos sobre uno mismo, los demás y el mundo.\n\nLos capítulos siguientes recorren cada nivel." }, { "id": "cotidiano", "type": "checklist", "prompt": "¿Cuáles de estas señales reconocés en tu vida cotidiana?", "help": "Así se reconoce el modelo en acción. Cuando notás un cambio emocional brusco y no sabés bien por qué, casi siempre hubo un pensamiento en el medio. Marcá las que te pasan.", "optional": true, "options": [ "Noto un cambio emocional brusco (angustia, bronca, tristeza) y no sé bien por qué", "Frente a un mismo hecho, otra persona y yo reaccionamos de manera muy distinta", "Mi cuerpo reacciona (tensión, taquicardia, nudo en el estómago) antes de que pueda nombrar lo que pensé", "Tomo una decisión (evitar, callar, irme) para aliviar una emoción que apareció «de la nada»" ] }, { "id": "ejemplos_1", "type": "info", "title": "Ejemplos por área (1 de 2)", "content": "Situación → pensamiento → emoción y conducta.\n\n- **Ansiedad.** Suena el teléfono con número desconocido → «Seguro es una mala noticia» → angustia; no atiende.\n- **Depresión.** Un amigo tarda en responder un mensaje → «Se cansó de mí» → tristeza; se aísla.\n- **Pareja.** La pareja llega callada del trabajo → «Está enojada conmigo» → inseguridad; reclama.\n- **Autoestima.** Se equivoca al hablar en una reunión → «Quedé como un tonto» → vergüenza; se calla el resto.\n- **Trabajo.** El jefe pide «hablar un momento» → «Me van a echar» → miedo; no duerme." }, { "id": "ejemplos_2", "type": "info", "title": "Ejemplos por área (2 de 2)", "content": "- **Universidad.** Ve una consigna difícil en el examen → «No voy a poder, soy un desastre» → bloqueo; deja el examen.\n- **Duelo.** Se ríe con amigos tras una pérdida → «No tengo derecho a estar bien» → culpa; se retira.\n- **Perfeccionismo.** Entrega un informe con un error menor → «Está todo arruinado» → frustración; rehace todo.\n- **Ansiedad social.** Alguien no le devuelve el saludo → «Le caigo mal» → malestar; evita cruzarlo.\n- **Autoestima.** Recibe un elogio → «Lo dice por compromiso» → incomodidad; lo minimiza." }, { "id": "errores", "type": "info", "title": "Errores frecuentes", "content": "Qué se confunde y cómo evitarlo:\n\n- **Creer que el modelo dice «la culpa es tuya por pensar mal».** No. Dice que la interpretación influye, no que la persona elige sufrir. Los pensamientos automáticos no se eligen; se aprenden.\n- **Confundirlo con «pensamiento positivo».** El objetivo es pensar de forma más ajustada y flexible, no más optimista a la fuerza.\n- **Saltear la emoción.** Identificar y nombrar la emoción es parte del trabajo, no un paso menor.\n- **Buscar «el» pensamiento correcto.** Suele haber varios pensamientos encadenados; conviene mapearlos todos." }, { "id": "diferencias", "type": "info", "title": "Diferencias con conceptos similares", "content": "- **Situación:** el hecho observable. Es neutral; no contiene interpretación.\n- **Pensamiento:** la lectura que hacemos del hecho. Es lo que cambia entre personas.\n- **Emoción:** la respuesta afectiva (una palabra). Se siente; no se discute como verdadera o falsa.\n- **Conducta:** lo que hacemos. Es observable; suele buscar aliviar la emoción.\n\nEn las próximas pantallas, probá distinguirlos con uno de los ejemplos." }, { "id": "quiz_1", "type": "choice", "prompt": "«Un amigo tarda en responder un mensaje». ¿Qué es?", "help": "Ejemplo del área depresión. 1 de 4.", "options": [ "Situación", "Pensamiento", "Emoción", "Conducta" ], "feedback": { "Situación": "**¡Bien! Es la situación:** el hecho observable. Es neutral; no contiene interpretación.", "Pensamiento": "**Es la situación:** el hecho observable. Es neutral; no contiene interpretación. El pensamiento sería la lectura que hacemos de ese hecho, como «se cansó de mí».", "Emoción": "**Es la situación:** el hecho observable. Una emoción se nombra con una palabra (tristeza, miedo) y se siente; esto es algo que pasó afuera.", "Conducta": "**Es la situación:** el hecho observable, lo que pasó. La conducta es lo que hace la persona después, para aliviar lo que siente." } }, { "id": "quiz_2", "type": "choice", "prompt": "«Se cansó de mí». ¿Qué es?", "help": "Mismo ejemplo. 2 de 4.", "options": [ "Situación", "Pensamiento", "Emoción", "Conducta" ], "feedback": { "Situación": "**Es un pensamiento:** la lectura que hacemos del hecho. Lo observable es que el amigo tarda en responder; «se cansó de mí» es una interpretación, y es lo que cambia entre personas.", "Pensamiento": "**¡Bien! Es el pensamiento:** la lectura que hacemos del hecho. Es lo que cambia entre personas: frente al mismo mensaje sin respuesta, otra persona podría leerlo de otra manera.", "Emoción": "**Es un pensamiento:** se puede escribir como una frase. La emoción que trae se nombra con una palabra: tristeza.", "Conducta": "**Es un pensamiento:** la lectura que hacemos del hecho. La conducta es lo que la persona hace, y eso se puede observar." } }, { "id": "quiz_3", "type": "choice", "prompt": "«Tristeza». ¿Qué es?", "help": "Mismo ejemplo. 3 de 4.", "options": [ "Situación", "Pensamiento", "Emoción", "Conducta" ], "feedback": { "Situación": "**Es la emoción:** la respuesta afectiva, que se nombra con una palabra. La situación es el hecho de afuera: el amigo que tarda en responder.", "Pensamiento": "**Es la emoción:** se nombra con una sola palabra. El pensamiento es una frase, como «se cansó de mí».", "Emoción": "**¡Bien! Es la emoción:** la respuesta afectiva, en una palabra. Se siente; no se discute como verdadera o falsa.", "Conducta": "**Es la emoción:** se siente por dentro. La conducta es lo que hacemos, y suele buscar aliviar esa emoción." } }, { "id": "quiz_4", "type": "choice", "prompt": "«Se aísla». ¿Qué es?", "help": "Mismo ejemplo. 4 de 4.", "options": [ "Situación", "Pensamiento", "Emoción", "Conducta" ], "feedback": { "Situación": "**Es la conducta:** lo que hace la persona después de pensar «se cansó de mí» y sentirse triste. La situación fue el mensaje sin respuesta.", "Pensamiento": "**Es la conducta:** algo que la persona hace y que se puede observar. El pensamiento fue «se cansó de mí».", "Emoción": "**Es la conducta:** lo que la persona hace. La emoción fue la tristeza; aislarse suele buscar aliviarla.", "Conducta": "**¡Bien! Es la conducta:** lo que hacemos. Es observable y suele buscar aliviar la emoción." } }, { "id": "marcos_1", "type": "info", "title": "Marcos, 34 años (1 de 2)", "content": "*Consulta por ansiedad.*\n\nMarcos llega a sesión angustiado tras una reunión de trabajo. Cuenta: «El gerente miró su celular mientras yo hablaba; supe que lo estaba haciendo mal». Desde entonces evita hablar en reuniones.\n\n**Desglose con el modelo:**\n\n- **Situación:** el gerente mira el celular.\n- **Pensamiento automático:** «lo estoy haciendo mal, no sirvo para esto».\n- **Emoción:** ansiedad y vergüenza.\n- **Respuesta física:** sudoración, voz temblorosa.\n- **Conducta:** acorta su intervención y evita futuras reuniones." }, { "id": "marcos_2", "type": "info", "title": "Marcos, 34 años (2 de 2)", "content": "**Intervención inicial:** el terapeuta no discute si el gerente estaba o no aburrido. Ayuda a Marcos a ver el paso intermedio —el pensamiento— y a considerar lecturas alternativas: «tal vez respondía un mensaje urgente».\n\nEl objetivo de esta primera fase es que Marcos **observe su propio proceso**, no que se convenza de nada." }, { "id": "desglose_intro", "type": "info", "title": "Tu primer desglose", "content": "Elegí un momento reciente en que sentiste una emoción intensa. Vas a desglosarlo paso a paso, como Marcos: situación, emoción, cuerpo, pensamiento y conducta.\n\nEs la hoja de trabajo «mapa situación–pensamiento–emoción» del cuadernillo, una pregunta por vez." }, { "id": "situacion", "type": "text", "prompt": "Describí la situación en una frase, como si fuera una foto", "help": "Qué, quién, cuándo, dónde. Sin interpretaciones. Así lo anotó Marcos: «El gerente mira el celular»." }, { "id": "emocion", "type": "checklist", "prompt": "¿Qué emoción sentiste?", "help": "Cada emoción se nombra con una sola palabra. Marcá hasta tres. Marcos marcaría ansiedad y vergüenza.", "max": 3, "options": [ "Angustia", "Ansiedad", "Miedo", "Bronca", "Tristeza", "Vergüenza", "Culpa", "Frustración", "Inseguridad", "Incomodidad", "Otra" ] }, { "id": "emocion_otra", "type": "text", "prompt": "Si marcaste «Otra», ¿cuál fue?", "help": "Una sola palabra. Si no marcaste «Otra», tocá «Saltar».", "optional": true }, { "id": "intensidad", "type": "scale", "prompt": "¿Con qué intensidad la sentiste?", "help": "De 0 a 100. Si marcaste más de una, puntuá la más fuerte.", "min": 0, "max": 100, "min_label": "Nada", "max_label": "Máxima" }, { "id": "cuerpo", "type": "text", "prompt": "¿Qué pasó en tu cuerpo?", "help": "Por ejemplo: taquicardia, tensión, nudo en el estómago. Marcos notó sudoración y voz temblorosa." }, { "id": "pensamiento", "type": "text", "prompt": "¿Qué te pasó por la cabeza justo antes de sentir eso?", "help": "Anotá el pensamiento tal cual apareció, con sus palabras. Marcos: «Lo estoy haciendo mal, no sirvo para esto»." }, { "id": "conducta", "type": "text", "prompt": "¿Qué hiciste (o dejaste de hacer) para aliviar la emoción?", "help": "Marcos acortó su intervención y empezó a evitar las reuniones." }, { "id": "otra_lectura", "type": "text", "prompt": "¿Qué otra interpretación sería posible, aunque no la creas del todo?", "help": "Como la de Marcos: «tal vez respondía un mensaje urgente». No se trata de convencerte de nada, sino de ver el paso intermedio. Esto es parte de la tarea de la semana: podés hacerlo ahora o más adelante.", "optional": true }, { "id": "resumen", "type": "reflect", "title": "Tu desglose", "template": "Situación: «{{situacion}}» → Pensamiento: «{{pensamiento}}» → Emoción: {{emocion}} + Cuerpo: «{{cuerpo}}» → Conducta: «{{conducta}}». Otra lectura posible: «{{otra_lectura}}».", "content": "**Situación → Pensamiento → Emoción + Respuesta física → Conducta.** Fijate que el pensamiento quedó en el medio: es la bisagra.\n\nEste desglose queda guardado en «Mis respuestas»." }, { "id": "reflexion", "type": "info", "title": "Preguntas de reflexión", "content": "- ¿En qué situaciones tu cuerpo reacciona antes de que puedas nombrar lo que pensás?\n- ¿Recordás una vez en que interpretaste algo de un modo y después resultó ser distinto?\n- ¿Qué emociones te cuesta más nombrar?\n- ¿Notás que ciertas situaciones disparan siempre el mismo tipo de pensamiento?\n- ¿Qué conductas usás habitualmente para aliviar emociones incómodas?\n- ¿Cómo sería tu día si pudieras detectar el pensamiento antes de que decida por vos?" }, { "id": "reflexion_respuesta", "type": "text", "prompt": "Si querés, respondé alguna de estas preguntas", "help": "Elegí la que más te resuene. Podés llevar tu respuesta a la próxima sesión.", "optional": true }, { "id": "para_llevar", "type": "info", "title": "Para llevar", "content": "- No reaccionamos a los hechos, sino a nuestra interpretación de ellos.\n- El esquema básico es: situación → pensamiento → emoción + respuesta física → conducta.\n- El pensamiento es la bisagra: trabajarlo modifica la emoción y la conducta.\n- El objetivo no es pensar en positivo, sino pensar de forma más ajustada y flexible.\n- Hay tres niveles de cognición: pensamientos automáticos, creencias intermedias y creencias nucleares." }, { "id": "semana", "type": "info", "title": "Para esta semana", "content": "- Repetí este desglose con **tres situaciones distintas** durante la semana, lo antes posible después de que ocurran (unos 5 a 10 minutos cada vez).\n- Elegí una de esas situaciones y anotá una segunda interpretación posible, aunque no la creas del todo.\n- Observá si, al identificar el pensamiento, la emoción cambia aunque sea un poco.\n- Compartí un ejemplo con alguien de confianza y preguntale cómo lo habría interpretado esa persona.\n\nEl próximo capítulo es **«Los pensamientos automáticos»**." } ]$steps$::jsonb),
  ('tcc-pensamientos-automaticos', 'Los pensamientos automáticos', 'Aprendé a atrapar las ideas rápidas que disparan el malestar y registralas en las primeras columnas del RPD.', 'thought_record', 'tcc', 'adultos', 'tcc', 20, 202,
   $steps$[ { "id": "intro", "type": "info", "title": "Los pensamientos automáticos", "content": "Son las ideas rápidas, breves y espontáneas que atraviesan la mente todo el tiempo. No las llamamos; aparecen solas.\n\nAprender a atraparlas es **el primer gran trabajo de la TCC**." }, { "id": "radio", "type": "info", "title": "Una radio de fondo", "content": "Tu mente comenta la realidad sin parar, como una radio de fondo que casi nunca escuchás del todo. Esos comentarios son los pensamientos automáticos.\n\nSuelen ser cortos («no puedo», «me va a salir mal», «no le importo»), pasan muy rápido y los damos por ciertos sin revisarlos.\n\nComo una gota que no notás, pero que repetida termina mojando todo el día." }, { "id": "clinica", "type": "info", "title": "Para profundizar", "content": "*Explicación clínica. Si preferís, pasá a la pantalla siguiente.*\n\nLos pensamientos automáticos son cogniciones situacionales de nivel superficial que surgen de forma involuntaria ante estímulos concretos. Beck los describió como el nivel más accesible del sistema cognitivo y, por eso, el punto de entrada habitual en terapia. Reflejan el contenido de creencias más profundas, pero se trabajan primero porque son fáciles de detectar y de registrar.\n\nPueden presentarse como una frase, como imágenes mentales o como una mezcla. Su **credibilidad subjetiva** —cuánto los creemos— es una variable clave: no importa solo qué pensamos, sino cuánto lo compramos. Reducir esa credibilidad, más que eliminar el pensamiento, es un objetivo central." }, { "id": "caracteristicas", "type": "info", "title": "Características", "content": "- **Automáticos:** aparecen sin esfuerzo ni intención.\n- **Breves:** suelen ser frases telegráficas o imágenes fugaces.\n- **Plausibles:** se sienten verdaderos, aunque no siempre lo sean.\n- **Involuntarios:** no los elegimos; cuesta apagarlos a voluntad.\n- **Específicos de la situación:** cambian según el contexto que los dispara.\n- **Cargados de emoción:** suelen anteceder o acompañar un cambio afectivo." }, { "id": "pregunta_oro", "type": "info", "title": "La pregunta de oro", "content": "Para identificarlos, la pregunta clave, que vas a usar en todo el cuadernillo, es:\n\n**«¿Qué me pasó por la cabeza justo antes (o durante) el momento en que empecé a sentirme así?»**\n\nCuando cuesta encontrarlo, ayuda:\n\n- recrear la escena con detalle;\n- prestar atención a las imágenes que aparecen;\n- completar frases como «temo que…», «lo que esto significa de mí es…»." }, { "id": "diferencias", "type": "info", "title": "Diferencias con emociones, preocupaciones y rumiaciones", "content": "- **Pensamiento automático:** una idea puntual sobre una situación. Se puede escribir como frase; se refiere a un momento concreto.\n- **Emoción:** un estado afectivo. Se nombra con UNA palabra (miedo, tristeza). No es una frase.\n- **Preocupación:** una cadena de pensamientos «¿y si…?» sobre el futuro. Es anticipatoria y encadenada; busca prevenir una amenaza.\n- **Rumiación:** un repaso repetitivo del pasado o de un problema. Es circular, mira hacia atrás, sobre causas y significados («¿por qué a mí?»)." }, { "id": "regla", "type": "info", "title": "Regla práctica", "content": "- Si lo podés escribir como una oración que empieza con «que…», suele ser un **pensamiento**.\n- Si es una sola palabra, es una **emoción**.\n- Si mira al futuro y se encadena, es **preocupación**.\n- Si mira al pasado y gira en círculo, es **rumiación**.\n\nProbá la regla con cuatro ejemplos." }, { "id": "quiz_1", "type": "choice", "prompt": "«Me va a salir mal»", "help": "¿Qué es? Aplicá la regla práctica. 1 de 4.", "options": [ "Pensamiento automático", "Emoción", "Preocupación", "Rumiación" ], "feedback": { "Pensamiento automático": "**¡Bien! Es un pensamiento automático:** se puede escribir como frase y se refiere a un momento concreto. Aunque habla del futuro, es una idea puntual: no se encadena en «¿y si…?».", "Emoción": "**Es un pensamiento automático:** es una frase, no una sola palabra. La emoción que lo acompaña sí se nombraría con una palabra, por ejemplo, miedo.", "Preocupación": "**Es un pensamiento automático.** Habla del futuro, pero es una idea puntual sobre un momento concreto. La preocupación es una cadena de «¿y si…?» que busca prevenir una amenaza.", "Rumiación": "**Es un pensamiento automático:** una idea puntual sobre una situación. La rumiación mira hacia atrás y gira en círculo sobre causas y significados («¿por qué a mí?»)." } }, { "id": "quiz_2", "type": "choice", "prompt": "«Angustia»", "help": "¿Qué es? 2 de 4.", "options": [ "Pensamiento automático", "Emoción", "Preocupación", "Rumiación" ], "feedback": { "Pensamiento automático": "**Es una emoción:** es una sola palabra. Un pensamiento se puede escribir como frase; para encontrarlo, usá la pregunta de oro.", "Emoción": "**¡Bien! Es una emoción:** un estado afectivo que se nombra con una sola palabra.", "Preocupación": "**Es una emoción:** una sola palabra. La preocupación es una cadena de pensamientos «¿y si…?» sobre el futuro.", "Rumiación": "**Es una emoción:** una sola palabra. La rumiación es un repaso repetitivo del pasado que gira en círculo." } }, { "id": "quiz_3", "type": "choice", "prompt": "«¿Y si me equivoco en la presentación? ¿Y si se dan cuenta? ¿Y si pierdo el trabajo?»", "help": "¿Qué es? 3 de 4.", "options": [ "Pensamiento automático", "Emoción", "Preocupación", "Rumiación" ], "feedback": { "Pensamiento automático": "**Es una preocupación:** no es una idea puntual, sino una cadena de «¿y si…?» que mira al futuro.", "Emoción": "**Es una preocupación:** son varias frases, no una palabra. Mira al futuro y se encadena en «¿y si…?».", "Preocupación": "**¡Bien! Es una preocupación:** mira al futuro, se encadena y busca prevenir una amenaza. Ojo: no es lo mismo que planificar. Planificar resuelve; preocuparse gira sin resolver.", "Rumiación": "**Es una preocupación:** mira hacia adelante, al futuro. La rumiación mira hacia atrás, al pasado." } }, { "id": "quiz_4", "type": "choice", "prompt": "«Desde que me dejó, me pregunto una y otra vez qué hice mal, por qué a mí»", "help": "¿Qué es? 4 de 4.", "options": [ "Pensamiento automático", "Emoción", "Preocupación", "Rumiación" ], "feedback": { "Pensamiento automático": "**Es una rumiación:** no es una idea puntual sobre un momento concreto, sino un repaso repetitivo del pasado que vuelve una y otra vez.", "Emoción": "**Es una rumiación:** es un repaso del pasado, no una palabra que nombre un estado afectivo.", "Preocupación": "**Es una rumiación:** mira hacia atrás, al pasado, no al futuro. Gira en círculo sobre causas y significados («¿por qué a mí?»).", "Rumiación": "**¡Bien! Es una rumiación:** mira al pasado y gira en círculo, sobre causas y significados («¿por qué a mí?»)." } }, { "id": "ejemplos", "type": "checklist", "prompt": "¿Alguno de estos pensamientos te suena?", "help": "Son pensamientos automáticos típicos de distintas áreas. Marcá los que aparecen en tu cabeza, si hay alguno.", "optional": true, "options": [ "Ansiedad: «Algo malo va a pasar», «no lo voy a soportar»", "Depresión: «Nada tiene sentido», «soy una carga»", "Pareja: «Si me quisiera, se daría cuenta solo»", "Autoestima: «No valgo lo suficiente», «cualquiera lo haría mejor»", "Trabajo: «Si pido ayuda, van a ver que no sé»", "Universidad: «Si repruebo, se termina todo»", "Duelo: «Debería haber hecho más», «lo abandoné»", "Perfeccionismo: «Si no es perfecto, es un fracaso»", "Ansiedad: «Todos se dan cuenta de que estoy nervioso»", "Depresión: «Siempre fue así y siempre va a ser así»" ] }, { "id": "errores", "type": "info", "title": "Errores frecuentes", "content": "Qué se confunde y cómo evitarlo:\n\n- **Anotar la emoción como si fuera el pensamiento.** «Me sentí mal» no es un pensamiento; buscá la frase que estaba debajo.\n- **Escribir el pensamiento «traducido» o suavizado.** Registralo tal como apareció, con sus palabras crudas.\n- **Quedarse con el primero.** Preguntá «¿y qué más?» para encontrar el pensamiento más caliente, el que más emoción trae.\n- **Confundir preocupación con planificación.** Planificar resuelve; preocuparse gira sin resolver." }, { "id": "lucia", "type": "info", "title": "Lucía, 21 años", "content": "*Estudiante universitaria.*\n\nLucía consulta por «bloqueos» antes de rendir. Al recrear la escena del último examen, aparece una secuencia: ve la primera pregunta difícil (situación) y piensa:\n\n«no me acuerdo de nada» → «voy a reprobar» → «si repruebo, soy un fracaso» → «mis viejos se van a decepcionar».\n\nLa emoción escala de nerviosismo a pánico y entrega la hoja en blanco." }, { "id": "lucia_caliente", "type": "choice", "prompt": "¿Cuál es el pensamiento más caliente de la cadena de Lucía?", "help": "El pensamiento caliente es el que más emoción trae.", "options": [ "«No me acuerdo de nada»", "«Voy a reprobar»", "«Si repruebo, soy un fracaso»", "«Mis viejos se van a decepcionar»" ], "feedback": { "«No me acuerdo de nada»": "Es el primero de la cadena, y por eso conviene seguir preguntando «¿y qué más?». En el caso, el más caliente es **«soy un fracaso»**: no es sobre el examen, sino sobre ella misma. Lo que se trabaja es identificar la cadena completa y detectar ese pensamiento, que conecta con una creencia nuclear que se aborda más adelante.", "«Voy a reprobar»": "Pesa, pero sigue hablando del examen. En el caso, el más caliente es **«soy un fracaso»**: no es sobre el examen, sino sobre ella misma. Lo que se trabaja es identificar la cadena completa y detectar ese pensamiento, que conecta con una creencia nuclear que se aborda más adelante.", "«Si repruebo, soy un fracaso»": "**¡Exacto!** «Soy un fracaso» no es sobre el examen, sino sobre ella misma. Lo que se trabaja es identificar la cadena completa y detectar ese pensamiento, que conecta con una creencia nuclear que se aborda más adelante, en «Creencias intermedias y nucleares».", "«Mis viejos se van a decepcionar»": "Es parte de la cadena y puede pesar mucho. En el caso, el más caliente es **«soy un fracaso»**: no es sobre el examen, sino sobre ella misma. Lo que se trabaja es identificar la cadena completa y detectar ese pensamiento, que conecta con una creencia nuclear que se aborda más adelante." } }, { "id": "cazar", "type": "info", "title": "Cazar el pensamiento", "content": "El ejercicio guiado de este capítulo:\n\n- **1.** Durante tres días, cada vez que notes un cambio de ánimo, hacé una pausa de diez segundos.\n- **2.** Hacete la pregunta de oro y anotá la primera frase que aparezca, cruda.\n- **3.** Preguntate «¿y qué más?» hasta que no aparezcan pensamientos nuevos.\n- **4.** Marcá el pensamiento que más emoción te trae: ese es el «pensamiento caliente».\n- **5.** Poné la credibilidad de 0 a 100 (cuánto lo creés en ese momento)." }, { "id": "rpd_intro", "type": "info", "title": "Tu Registro de Pensamientos (RPD)", "content": "El Registro de Pensamientos Disfuncionales (RPD) es la herramienta más usada de la TCC.\n\nEn este capítulo trabajás las primeras cuatro columnas: **fecha y situación, emoción (0–100), pensamientos automáticos y credibilidad (0–100)**. En «Cuestionamiento socrático y reestructuración» vas a completar las últimas: evidencia y respuesta alternativa.\n\nProbalo ahora con un momento reciente en que notaste un cambio de ánimo." }, { "id": "situacion", "type": "text", "prompt": "¿Cuándo fue y qué pasó?", "help": "Fecha y situación, como una foto: qué, quién, cuándo, dónde. Sin interpretaciones. Lucía: «En el último examen, veo la primera pregunta, que es difícil»." }, { "id": "emocion", "type": "checklist", "prompt": "¿Qué emoción sentiste?", "help": "Cada emoción se nombra con una sola palabra, no con una frase. Marcá hasta tres. La de Lucía escaló de nerviosismo a pánico.", "max": 3, "options": [ "Angustia", "Ansiedad", "Miedo", "Nerviosismo", "Pánico", "Bronca", "Tristeza", "Vergüenza", "Culpa", "Frustración", "Inseguridad", "Otra" ] }, { "id": "emocion_otra", "type": "text", "prompt": "Si marcaste «Otra», ¿cuál fue?", "help": "Una sola palabra. Si no marcaste «Otra», tocá «Saltar».", "optional": true }, { "id": "intensidad", "type": "scale", "prompt": "¿Con qué intensidad la sentiste?", "help": "De 0 a 100. Si marcaste más de una, puntuá la más fuerte.", "min": 0, "max": 100, "min_label": "Nada", "max_label": "Máxima" }, { "id": "pensamientos", "type": "list", "prompt": "¿Qué te pasó por la cabeza justo antes de empezar a sentirte así?", "help": "Anotá la primera frase, cruda, tal como apareció. Después preguntate **«¿y qué más?»** y anotá cada pensamiento nuevo en otro renglón, hasta que no aparezcan más.\n\nSi cuesta: recreá la escena con detalle, prestá atención a las imágenes o completá «temo que…», «lo que esto significa de mí es…».\n\nLucía: «no me acuerdo de nada» → «voy a reprobar» → «si repruebo, soy un fracaso» → «mis viejos se van a decepcionar».", "count": 5, "min": 1 }, { "id": "caliente", "type": "text", "prompt": "¿Cuál es tu pensamiento caliente?", "help": "El que más emoción te trae (en el papel se marca con un asterisco). Copialo de tu lista. El de Lucía: «si repruebo, soy un fracaso»." }, { "id": "credibilidad", "type": "scale", "prompt": "¿Cuánto creés ese pensamiento?", "help": "Credibilidad de 0 a 100: cuánto lo creés en ese momento. No importa solo qué pensás, sino cuánto lo creés.", "min": 0, "max": 100, "min_label": "Nada", "max_label": "Totalmente" }, { "id": "clasificar", "type": "choice", "prompt": "Aplicá la regla práctica: lo que anotaste como pensamiento caliente, ¿qué es?", "help": "Clasificar cada anotación también es parte de la tarea de la semana.", "options": [ "Un pensamiento: una frase sobre un momento concreto", "Una emoción: una sola palabra", "Una preocupación: una cadena de «¿y si…?» sobre el futuro", "Una rumiación: vueltas en círculo sobre el pasado" ], "feedback": { "Un pensamiento: una frase sobre un momento concreto": "**Bien.** Eso es lo que va en esta columna del RPD. Fijate que esté tal como apareció, con sus palabras crudas, sin traducirlo ni suavizarlo.", "Una emoción: una sola palabra": "**Ojo:** anotar la emoción como si fuera el pensamiento es un error frecuente. «Me sentí mal» no es un pensamiento: buscá la frase que estaba debajo, con la pregunta de oro. Podés tocar «Atrás» y ajustarlo.", "Una preocupación: una cadena de «¿y si…?» sobre el futuro": "Si mira al futuro y se encadena, es preocupación. Como en el caso de Lucía, anotá cada eslabón de la cadena en un renglón y elegí como caliente el que más emoción te trae. Podés tocar «Atrás» y ajustarlo. Recordá: planificar resuelve; preocuparse gira sin resolver.", "Una rumiación: vueltas en círculo sobre el pasado": "Si mira al pasado y gira en círculo («¿por qué a mí?»), es rumiación. Buscá la frase puntual que apareció en el momento en que empezaste a sentirte así y anotala como pensamiento caliente. Podés tocar «Atrás» y ajustarlo." } }, { "id": "resumen", "type": "reflect", "title": "Tu registro", "template": "Situación: «{{situacion}}». Emoción: {{emocion}}. Pensamientos: {{pensamientos}}. Pensamiento caliente: «{{caliente}}».", "content": "Estas son las primeras cuatro columnas del RPD. En «Cuestionamiento socrático y reestructuración» vas a completar las últimas: evidencia y respuesta alternativa.\n\nTu registro queda guardado en «Mis respuestas»." }, { "id": "reflexion", "type": "info", "title": "Preguntas de reflexión", "content": "- ¿Qué pensamiento automático se repite más en tu semana?\n- ¿Notás diferencia entre pensar un problema y darle vueltas sin salida?\n- ¿Cuál de tus pensamientos automáticos te resulta más creíble, aunque sospeches que no es del todo cierto?\n- ¿En qué momento del día aparecen más? ¿Hay un patrón?\n- ¿Qué pasaría si trataras esos pensamientos como hipótesis en vez de como hechos?\n- ¿Cómo te hablás a vos mismo cuando algo sale mal?" }, { "id": "reflexion_respuesta", "type": "text", "prompt": "Si querés, respondé alguna de estas preguntas", "help": "Elegí la que más te resuene. Podés llevar tu respuesta a la próxima sesión.", "optional": true }, { "id": "para_llevar", "type": "info", "title": "Para llevar", "content": "- Los pensamientos automáticos son ideas breves, involuntarias y plausibles.\n- La pregunta de oro: «¿qué me pasó por la cabeza justo antes de sentirme así?».\n- Emoción = una palabra; pensamiento = una frase; preocupación = futuro; rumiación = pasado en círculo.\n- No importa solo qué pensás, sino cuánto lo creés (credibilidad).\n- El RPD es la herramienta base para registrarlos." }, { "id": "semana", "type": "info", "title": "Para esta semana", "content": "- Durante tres días, cada vez que notes un cambio de ánimo, hacé la pausa de diez segundos y cazá el pensamiento.\n- Completá al menos **cinco registros** durante la semana: repetí este ejercicio cada vez (unos 5 minutos). También podés usar el «Registro de pensamientos (RPD)», al final de la colección.\n- En dos de ellos, identificá y marcá el pensamiento caliente.\n- Clasificá cada anotación: ¿es pensamiento, emoción, preocupación o rumiación?\n- Elegí una preocupación recurrente y anotá si es algo que podés resolver hoy o no.\n\nEl próximo capítulo es **«Las distorsiones cognitivas»**." } ]$steps$::jsonb),
  ('tcc-distorsiones', 'Las distorsiones cognitivas', 'Conocé las 12 distorsiones más frecuentes, aprendé a reconocerlas y descubrí cuál es tu «lente» habitual.', 'custom', 'tcc', 'adultos', 'tcc', 30, 203,
   $steps$[ { "id": "intro", "type": "info", "title": "Lentes rayados", "content": "Las distorsiones cognitivas son errores sistemáticos en la forma de procesar la información: atajos mentales que deforman la realidad y sostienen el malestar. No son signo de poca inteligencia; los tenemos todos. La clave es aprender a reconocerlos.\n\nLa mente, para ahorrar esfuerzo, usa atajos. La mayoría son útiles, pero algunos nos hacen ver la realidad torcida, como **lentes rayados**. Una persona puede recibir nueve comentarios positivos y uno negativo, y quedarse toda la noche pensando solo en el negativo. Eso es una distorsión: no está mintiendo, está filtrando." }, { "id": "profundizar", "type": "info", "title": "Para profundizar (opcional)", "content": "Las distorsiones cognitivas son sesgos sistemáticos en el procesamiento de la información descritos por Beck y ampliados por Burns. Operan sobre los pensamientos automáticos y les dan forma.\n\nIdentificar el tipo de distorsión facilita el cuestionamiento, porque cada una tiene un «punto débil» característico. No se trata de etiquetar para descalificar el pensamiento, sino de entender el mecanismo para poder revisarlo." }, { "id": "tabla_1", "type": "info", "title": "Las principales distorsiones (1 de 4)", "content": "Estas son las más frecuentes, con su definición, un ejemplo y una vía para cuestionarla.\n\n**Todo o nada.** Ver en extremos, sin matices. «Si no es perfecto, es un desastre.»\nCuestionala: ¿hay puntos intermedios? ¿Qué habría entre 0 y 100?\n\n**Sobregeneralización.** De un hecho aislado a una regla universal. «Siempre me sale mal todo.»\nCuestionala: ¿«siempre»? ¿Podés nombrar excepciones concretas?\n\n**Filtro mental.** Fijarse solo en lo negativo. Un reproche borra diez elogios.\nCuestionala: ¿qué datos positivos estoy dejando afuera?" }, { "id": "tabla_2", "type": "info", "title": "Las principales distorsiones (2 de 4)", "content": "**Descalificar lo positivo.** Restar valor a lo bueno. «Me salió bien, pero fue suerte.»\nCuestionala: si un amigo lograra esto, ¿le dirías que fue solo suerte?\n\n**Lectura de mente.** Suponer lo que otros piensan. «Sé que le parezco aburrido.»\nCuestionala: ¿qué evidencia tengo? ¿Lo comprobé o lo asumí?\n\n**Adivinación del futuro.** Predecir lo peor como un hecho. «Voy a fracasar seguro.»\nCuestionala: ¿cuántas veces esta predicción se cumplió tal cual?" }, { "id": "tabla_3", "type": "info", "title": "Las principales distorsiones (3 de 4)", "content": "**Catastrofización.** Imaginar el peor escenario y darlo por cierto. «Si me tiembla la voz, es el fin.»\nCuestionala: ¿qué es lo más probable, no lo peor? ¿Y si pasara, cómo lo afrontaría?\n\n**Razonamiento emocional.** «Lo siento, entonces es verdad.» «Me siento inútil, luego lo soy.»\nCuestionala: ¿un sentimiento es una prueba? ¿Los hechos coinciden?\n\n**Debería / tener que.** Reglas rígidas sobre cómo deben ser las cosas. «No debería equivocarme nunca.»\nCuestionala: ¿esa regla es realista? ¿La aplicarías a otro?" }, { "id": "tabla_4", "type": "info", "title": "Las principales distorsiones (4 de 4)", "content": "**Etiquetación.** Ponerse (o poner) una etiqueta global. «Soy un fracaso.»\nCuestionala: ¿un error define a toda la persona? Describí la conducta, no la etiqueta.\n\n**Personalización.** Asumir responsabilidad de lo que no controlás. «Está de mal humor por mi culpa.»\nCuestionala: ¿qué otros factores pudieron influir?\n\n**Culpabilización.** Cargar toda la culpa en uno mismo o en otro.\nCuestionala: ¿qué parte es mía, qué parte del contexto y qué parte de otros?" }, { "id": "reconocer", "type": "info", "title": "¿Cómo reconocerlas?", "content": "Prestá atención a estas pistas:\n\n- Aparecen palabras absolutas: «siempre», «nunca», «todo», «nadie», «todos».\n- Hay etiquetas globales sobre vos o los demás: «soy un…», «es un…».\n- Se predice el futuro con certeza o se lee la mente ajena sin datos.\n- Un sentimiento se usa como prueba de un hecho.\n- Aparecen «debería», «tengo que», «no puedo fallar»." }, { "id": "areas", "type": "info", "title": "Ejemplos por área", "content": "Así se ven en distintas áreas de la vida. Fijate que un mismo pensamiento puede tener más de una.\n\n- **Ansiedad:** «Si tengo un ataque en el colectivo, va a ser catastrófico» → catastrofización.\n- **Autoestima:** «Soy un desastre» → etiquetación.\n- **Duelo:** «Debería haberlo salvado» → debería / culpabilización.\n- **Autoestima:** «Todos se dieron cuenta de mi error» → filtro mental + lectura de mente.\n- **Trabajo:** «El equipo falló por mi culpa» → personalización.\n\nAhora probá vos con otros cinco ejemplos." }, { "id": "quiz_depresion", "type": "choice", "prompt": "¿Qué distorsión hay en «Nunca voy a estar mejor»?", "help": "Ejemplo del área depresión (1 de 5).", "options": [ "Sobregeneralización", "Adivinación del futuro", "Razonamiento emocional", "Etiquetación" ], "feedback": { "Adivinación del futuro": "**Exacto.** Predice lo peor como si fuera un hecho. Para cuestionarla: ¿cuántas veces esta predicción se cumplió tal cual?", "Sobregeneralización": "**Casi.** El «nunca» es una buena pista de que hay una distorsión, pero el pensamiento no saca una regla de un hecho aislado: predice el futuro como si fuera un hecho. Es **adivinación del futuro**.", "Razonamiento emocional": "**No es la principal.** No usa un sentimiento como prueba («lo siento, entonces es verdad»): predice el futuro como si fuera un hecho. Es **adivinación del futuro**.", "Etiquetación": "**No.** No pone una etiqueta global («soy un…»): predice el futuro como si fuera un hecho. Es **adivinación del futuro**." } }, { "id": "quiz_pareja", "type": "choice", "prompt": "¿Qué distorsión hay en «Si no me escribe, es que ya no le importo»?", "help": "Ejemplo del área pareja (2 de 5).", "options": [ "Catastrofización", "Personalización", "Lectura de mente", "Debería / tener que" ], "feedback": { "Lectura de mente": "**Exacto.** Supone lo que el otro piensa o siente, sin datos. Para cuestionarla: ¿qué evidencia tengo? ¿Lo comprobé o lo asumí?", "Catastrofización": "**No es la principal.** No imagina el peor escenario: da por hecho lo que la otra persona siente sin haberlo comprobado. Es **lectura de mente**.", "Personalización": "**Se parece, pero no.** No se hace cargo de algo que no controla: supone lo que el otro siente. Es **lectura de mente**.", "Debería / tener que": "**No.** No hay una regla rígida («debería», «tengo que»): supone lo que el otro siente. Es **lectura de mente**." } }, { "id": "quiz_trabajo", "type": "choice", "prompt": "¿Qué distorsión hay en «Un error y arruiné todo el proyecto»?", "help": "Ejemplo del área trabajo (3 de 5).", "options": [ "Todo o nada", "Filtro mental", "Etiquetación", "Adivinación del futuro" ], "feedback": { "Todo o nada": "**Exacto.** Ve en extremos, sin matices: un error alcanza para que «todo» esté arruinado. Para cuestionarla: ¿hay puntos intermedios? ¿Qué habría entre 0 y 100?", "Filtro mental": "**Cerca.** El filtro se fija solo en lo negativo, pero acá lo central es el extremo: o sale perfecto o está todo arruinado. Es **todo o nada**.", "Etiquetación": "**No.** No le pone una etiqueta a la persona («soy un…»): ve el resultado en extremos. Es **todo o nada**.", "Adivinación del futuro": "**No.** No predice lo que va a pasar: juzga lo que pasó sin matices. Es **todo o nada**." } }, { "id": "quiz_universidad", "type": "choice", "prompt": "¿Qué distorsión hay en «Me fue bien de casualidad»?", "help": "Ejemplo del área universidad (4 de 5).", "options": [ "Filtro mental", "Lectura de mente", "Razonamiento emocional", "Descalificar lo positivo" ], "feedback": { "Descalificar lo positivo": "**Exacto.** Le resta valor a lo bueno. Para cuestionarla: si un amigo lograra esto, ¿le dirías que fue solo suerte?", "Filtro mental": "**Cerca.** El filtro deja afuera lo positivo; acá lo positivo se ve, pero se le resta valor («de casualidad»). Es **descalificar lo positivo**.", "Lectura de mente": "**No.** No supone lo que piensan otros: le resta valor a un logro propio. Es **descalificar lo positivo**.", "Razonamiento emocional": "**No.** No usa un sentimiento como prueba: le resta valor a lo bueno. Es **descalificar lo positivo**." } }, { "id": "quiz_perfeccionismo", "type": "choice", "prompt": "¿Qué distorsión hay en «Me siento incompetente, entonces lo soy»?", "help": "Ejemplo del área perfeccionismo (5 de 5).", "options": [ "Etiquetación", "Todo o nada", "Razonamiento emocional", "Lectura de mente" ], "feedback": { "Razonamiento emocional": "**Exacto.** «Lo siento, entonces es verdad»: usa un sentimiento como prueba de un hecho. Para cuestionarla: ¿un sentimiento es una prueba? ¿Los hechos coinciden?", "Etiquetación": "**Cerca.** «Incompetente» suena a etiqueta, pero la clave está en el «me siento…, entonces lo soy»: un sentimiento usado como prueba. Es **razonamiento emocional**.", "Todo o nada": "**No.** No ve en extremos: toma un sentimiento como prueba de un hecho. Es **razonamiento emocional**.", "Lectura de mente": "**No.** No supone lo que piensan otros: toma su propio sentimiento como prueba. Es **razonamiento emocional**." } }, { "id": "errores", "type": "info", "title": "Errores frecuentes", "content": "Qué se confunde y cómo evitarlo:\n\n- **Usar la etiqueta de la distorsión como insulto.** «Otra vez catastrofizando» no ayuda; el fin es entender, no juzgarse.\n- **Creer que nombrar la distorsión ya la resuelve.** Nombrarla es el primer paso; después hay que cuestionarla (lo vas a ver en «Cuestionamiento socrático y reestructuración»).\n- **Forzar una sola categoría.** Un pensamiento puede tener dos o tres distorsiones a la vez.\n- **Confundir una distorsión con una emoción legítima.** Estar triste tras una pérdida no es una distorsión; pensar «no merezco estar bien nunca más» sí puede serlo." }, { "id": "diferencias", "type": "info", "title": "Diferencias con conceptos similares", "content": "Una distorsión no es lo mismo que:\n\n- **Un pensamiento automático:** es el pensamiento en sí; la distorsión es el **tipo** de error que contiene.\n- **Una creencia nuclear:** es más profunda y estable; las distorsiones operan en la superficie.\n- **Una opinión razonable:** una opinión admite matices y evidencia; la distorsión es rígida y absoluta." }, { "id": "rodrigo", "type": "info", "title": "Caso clínico: Rodrigo, 29 años", "content": "**Perfeccionismo laboral.** Rodrigo entrega un informe muy valorado, pero con una cifra mal tipeada. Piensa:\n\n- «Está todo arruinado» (todo o nada).\n- «Van a pensar que soy un incompetente» (lectura de mente).\n- «Soy un desastre» (etiquetación).\n\nPasa la noche rehaciéndolo entero.\n\n**Trabajo en sesión:** se nombran las tres distorsiones. Rodrigo descubre que el mismo error, cometido por un compañero, le parecería «un detalle sin importancia». Ese **doble estándar** es la puerta de entrada al cuestionamiento." }, { "id": "guiado_intro", "type": "info", "title": "Ejercicio guiado: tu distorsión frecuente", "content": "Ahora vas a buscar tu «lente» más frecuente:\n\n1. Volvé a tus registros de «Los pensamientos automáticos» y elegí tres pensamientos calientes.\n2. Para cada uno, buscá qué distorsión(es) encaja(n) mejor.\n3. Anotá qué palabra o pista te lo indicó («siempre», una etiqueta, una predicción).\n4. Identificá cuál distorsión aparece más seguido: esa es tu «lente» más frecuente.\n5. Escribí, para esa distorsión, la pregunta que mejor la desafía.\n\nTus registros están guardados en cada ejercicio, en «Mis respuestas». Si todavía no tenés, usá pensamientos de estos días." }, { "id": "calientes", "type": "list", "prompt": "Anotá tres pensamientos calientes de tus registros", "help": "Los que más emoción te trajeron, tal como aparecieron. Por ejemplo, Rodrigo: «Está todo arruinado».", "count": 3 }, { "id": "calientes_distorsion", "type": "list", "prompt": "Para cada pensamiento: ¿qué distorsión encaja y qué pista te lo indicó?", "help": "Uno por renglón, en el mismo orden. Puede haber más de una distorsión. Por ejemplo: todo o nada, la pista fue «todo».\n\nLas doce: todo o nada, sobregeneralización, filtro mental, descalificar lo positivo, lectura de mente, adivinación del futuro, catastrofización, razonamiento emocional, debería / tener que, etiquetación, personalización y culpabilización.", "count": 3 }, { "id": "lente", "type": "choice", "prompt": "¿Cuál aparece más seguido? Esa es tu «lente» más frecuente", "help": "Mirá tus tres respuestas anteriores.", "options": [ "Todo o nada", "Sobregeneralización", "Filtro mental", "Descalificar lo positivo", "Lectura de mente", "Adivinación del futuro", "Catastrofización", "Razonamiento emocional", "Debería / tener que", "Etiquetación", "Personalización", "Culpabilización" ], "feedback": { "Todo o nada": "Pregunta de la tabla para desafiarla: ¿Hay puntos intermedios? ¿Qué habría entre 0 y 100?", "Sobregeneralización": "Pregunta de la tabla para desafiarla: ¿«Siempre»? ¿Podés nombrar excepciones concretas?", "Filtro mental": "Pregunta de la tabla para desafiarla: ¿Qué datos positivos estoy dejando afuera?", "Descalificar lo positivo": "Pregunta de la tabla para desafiarla: Si un amigo lograra esto, ¿le dirías que fue solo suerte?", "Lectura de mente": "Pregunta de la tabla para desafiarla: ¿Qué evidencia tengo? ¿Lo comprobé o lo asumí?", "Adivinación del futuro": "Pregunta de la tabla para desafiarla: ¿Cuántas veces esta predicción se cumplió tal cual?", "Catastrofización": "Pregunta de la tabla para desafiarla: ¿Qué es lo más probable, no lo peor? ¿Y si pasara, cómo lo afrontaría?", "Razonamiento emocional": "Pregunta de la tabla para desafiarla: ¿Un sentimiento es una prueba? ¿Los hechos coinciden?", "Debería / tener que": "Pregunta de la tabla para desafiarla: ¿Esa regla es realista? ¿La aplicarías a otro?", "Etiquetación": "Pregunta de la tabla para desafiarla: ¿Un error define a toda la persona? Describí la conducta, no la etiqueta.", "Personalización": "Pregunta de la tabla para desafiarla: ¿Qué otros factores pudieron influir?", "Culpabilización": "Pregunta de la tabla para desafiarla: ¿Qué parte es mía, qué parte del contexto y qué parte de otros?" } }, { "id": "lente_pregunta", "type": "text", "prompt": "Escribí la pregunta que mejor desafía esa distorsión", "help": "Podés usar la pregunta de la tabla tal cual o escribirla con tus palabras." }, { "id": "hoja_intro", "type": "info", "title": "Hoja de trabajo: identificando distorsiones", "content": "Ahora completá una fila de la hoja con una situación concreta: reciente o de tus registros.\n\nSon cinco preguntas: la situación, el pensamiento automático, la distorsión o distorsiones, la pista que la revela y la pregunta que la desafía. En cada una vas a ver cómo lo haría Rodrigo." }, { "id": "hoja_situacion", "type": "text", "prompt": "Situación: ¿qué pasó?", "help": "Breve y concreta: dónde, cuándo, con quién. Rodrigo: entregó un informe muy valorado, pero con una cifra mal tipeada." }, { "id": "hoja_pensamiento", "type": "text", "prompt": "Pensamiento automático: ¿qué pensaste?", "help": "La frase tal como apareció. Rodrigo: «Está todo arruinado»." }, { "id": "hoja_distorsiones", "type": "checklist", "prompt": "Distorsión(es): ¿cuáles encajan?", "help": "Marcá todas las que veas: un pensamiento puede tener dos o tres a la vez. Rodrigo: todo o nada.", "options": [ "Todo o nada", "Sobregeneralización", "Filtro mental", "Descalificar lo positivo", "Lectura de mente", "Adivinación del futuro", "Catastrofización", "Razonamiento emocional", "Debería / tener que", "Etiquetación", "Personalización", "Culpabilización" ] }, { "id": "hoja_pista", "type": "text", "prompt": "¿Qué pista lo revela?", "help": "Una palabra absoluta, una etiqueta, una predicción, un «debería», un sentimiento usado como prueba… Rodrigo: «todo»." }, { "id": "hoja_pregunta", "type": "text", "prompt": "¿Qué pregunta la desafía?", "help": "Para el «está todo arruinado» de Rodrigo: «¿Hay puntos intermedios? ¿Qué habría entre 0 y 100?»." }, { "id": "refl_areas", "type": "text", "prompt": "¿En qué áreas de tu vida aparece más tu lente?", "help": "Preguntas de reflexión: respondé las que quieras, podés saltear cualquiera.\n\nPor ejemplo: trabajo, pareja, estudio.", "optional": true }, { "id": "refl_estandar", "type": "text", "prompt": "¿Te tratás con el mismo estándar con el que tratás a los demás?", "help": "Acordate del doble estándar de Rodrigo.", "optional": true }, { "id": "refl_palabras", "type": "checklist", "prompt": "¿Qué palabras absolutas usás más seguido?", "options": [ "Siempre", "Nunca", "Todo", "Nadie", "Todos", "Debería", "Tengo que", "No puedo fallar" ], "optional": true }, { "id": "refl_sin_distorsion", "type": "text", "prompt": "¿Cómo cambiaría una situación si sacaras la distorsión de la ecuación?", "optional": true }, { "id": "refl_herencia", "type": "text", "prompt": "¿Qué distorsión heredaste de tu entorno o de tu historia?", "optional": true }, { "id": "resumen", "type": "reflect", "title": "Tu lente y tu hoja", "template": "Tu lente más frecuente: {{lente}}. La pregunta que la desafía: «{{lente_pregunta}}». En tu hoja, el pensamiento «{{hoja_pensamiento}}» mostró: {{hoja_distorsiones}}. Para desafiarlo: «{{hoja_pregunta}}».", "content": "Tus respuestas quedan guardadas: las podés volver a ver en este ejercicio, en «Mis respuestas». Si en tu perfil está activado «Compartir mis registros con mi psicólogo», tu psicólogo también las puede ver." }, { "id": "para_llevar", "type": "info", "title": "Para llevar", "content": "- Las distorsiones son errores sistemáticos que deforman cómo procesamos la información.\n- Las tenemos todos; reconocerlas es más útil que juzgarlas.\n- Cada distorsión tiene un punto débil y una pregunta que la desafía.\n- Un pensamiento puede contener varias distorsiones a la vez.\n- Nombrarla es el primer paso; cuestionarla viene después." }, { "id": "semana", "type": "info", "title": "Para esta semana", "content": "Tareas para casa, a lo largo de la semana:\n\n- Detectá y clasificá **cinco pensamientos** con distorsión. Por cada uno, volvé a completar la hoja de este ejercicio o usá «Registro de distorsiones».\n- Elegí tu distorsión más frecuente y llevá una «cuenta» de cuántas veces aparece por día.\n- Por cada una, escribí una frase alternativa más ajustada (sin exagerar hacia el otro extremo).\n- Aplicá el «doble estándar»: preguntate qué le dirías a un amigo que pensara eso.\n\nEl próximo capítulo es **«Creencias intermedias y nucleares»**. Cuestionar las distorsiones lo vas a trabajar en «Cuestionamiento socrático y reestructuración»." } ]$steps$::jsonb),
  ('tcc-creencias', 'Creencias intermedias y nucleares', 'Bajá de un pensamiento automático a la creencia de fondo con la flecha descendente y empezá a revisarla.', 'custom', 'tcc', 'adultos', 'tcc', 30, 204,
   $steps$[ { "id": "intro", "type": "info", "title": "Hojas, tronco y raíz", "content": "Debajo de los pensamientos automáticos hay estructuras más profundas: reglas de vida y creencias sobre uno mismo que funcionan como el sistema operativo de la mente. Casi nunca las decimos en voz alta, pero deciden mucho.\n\nPensá en un árbol. Los **pensamientos automáticos** son las hojas: se ven, cambian con el clima, hay miles. Las **creencias intermedias** son el tronco y las ramas: las reglas con las que te movés por la vida. Las **creencias nucleares** son la raíz: ideas absolutas sobre quién sos, aprendidas muy temprano.\n\nSi solo cortás hojas, vuelven a crecer. Para un cambio duradero hay que llegar al tronco y a la raíz." }, { "id": "profundizar", "type": "info", "title": "Para profundizar (opcional)", "content": "Beck describió tres niveles cognitivos:\n\n- **Creencias nucleares (esquemas):** ideas globales, rígidas y sobregeneralizadas sobre el self, los otros y el mundo, habitualmente formadas en experiencias tempranas.\n- **Creencias intermedias:** actitudes, reglas y supuestos condicionales que la persona desarrolla para sobrellevar esas creencias nucleares.\n- **Pensamientos automáticos:** la manifestación situacional de todo ese sistema." }, { "id": "tres_formas", "type": "info", "title": "Las tres formas de la creencia intermedia", "content": "- **Actitud:** una valoración. «Es terrible cometer errores.»\n- **Regla:** un imperativo. «Nunca debo mostrar debilidad.»\n- **Supuesto condicional:** un «si… entonces…». «Si pido ayuda, entonces soy débil.» / «Si soy perfecto, entonces me van a querer.»" }, { "id": "dominios", "type": "info", "title": "Los tres dominios de las creencias nucleares", "content": "Las creencias nucleares negativas sobre uno mismo suelen agruparse en tres grandes dominios (Judith Beck):\n\n- **Desamparo:** «soy impotente / incapaz». Por ejemplo: «no puedo con nada», «soy débil», «no tengo control», «estoy atrapado».\n- **Desamor:** «no soy querible». Por ejemplo: «no merezco cariño», «voy a terminar solo», «hay algo malo en mí».\n- **Desvalorización:** «no valgo / soy defectuoso». Por ejemplo: «soy un fracaso», «no sirvo», «soy mala persona»." }, { "id": "desarrollo", "type": "info", "title": "¿Cómo se desarrollan y cómo mantienen el malestar?", "content": "Las creencias nucleares se forman a partir de experiencias repetidas, especialmente tempranas, y del significado que se les dio.\n\nUna vez instaladas, se auto-perpetúan. La persona:\n\n- presta más atención a la información que las confirma;\n- reinterpreta o descarta la que las contradice;\n- y desarrolla estrategias (reglas y conductas) para no sentir su dolor." }, { "id": "circulo", "type": "info", "title": "El círculo que las mantiene", "content": "**Creencia nuclear** (por ejemplo, «no valgo»)\n→ **regla o supuesto** («si logro todo, valdré»)\n→ **estrategia** (exigencia, control, evitación)\n→ **pensamientos automáticos** ante cada situación\n→ **emoción y conducta** que, al final, confirman la creencia.\n\nLa creencia se protege a sí misma: cuando la regla se cumple, hay alivio; cuando se rompe, se dispara la creencia nuclear en toda su fuerza." }, { "id": "reconocer", "type": "info", "title": "¿Cómo reconocerlas?", "content": "- Reglas que aparecen como «debería», «tengo que», «nunca», «siempre».\n- Supuestos «si… entonces…» que ordenan tu conducta sin que lo notes.\n- Reacciones desproporcionadas: cuando la emoción es mucho más grande que la situación, suele haber una creencia nuclear tocada.\n- Temas que se repiten en distintas áreas (pareja, trabajo, estudio): esa constante suele ser la raíz." }, { "id": "flecha", "type": "info", "title": "La técnica de la flecha descendente", "content": "Para pasar de un pensamiento automático a la creencia nuclear se usa la **flecha descendente**: tomás un pensamiento y preguntás, una y otra vez, «si eso fuera cierto, ¿qué significaría?», hasta llegar a la idea de fondo.\n\n**Ejemplo**\nPensamiento: «Me equivoqué en la reunión.»\n↓ ¿Y si eso fuera cierto, qué significaría? «Que van a notar que no sé.»\n↓ ¿Y eso qué significaría? «Que no estoy a la altura del puesto.»\n↓ ¿Y eso qué diría de vos? «Que no sirvo.» ← creencia nuclear (desvalorización)" }, { "id": "areas", "type": "info", "title": "Ejemplos por área", "content": "De la regla o supuesto (creencia intermedia) a la creencia nuclear probable:\n\n- **Autoestima:** «Si otro me critica, es que tiene razón» → desvalorización: «soy defectuoso».\n- **Trabajo:** «Si pido ayuda, soy un inútil» → desamparo: «soy incapaz».\n- **Universidad:** «Si no soy el mejor, no valgo nada» → desvalorización: «no soy suficiente».\n- **Duelo:** «Debería haber podido evitarlo» → desamparo / culpa: «fallé».\n- **Perfeccionismo:** «Si algo tiene un error, todo mi trabajo no sirve» → desvalorización: «no soy suficiente».\n\nAhora probá vos con otros tres." }, { "id": "quiz_ansiedad", "type": "choice", "prompt": "«Si mantengo todo bajo control, no pasará nada malo»: ¿a qué dominio apunta?", "help": "Ejemplo del área ansiedad (1 de 3). Pensá qué creencia nuclear podría estar debajo de esa regla.", "options": [ "Desamparo", "Desamor", "Desvalorización" ], "feedback": { "Desamparo": "**Exacto.** La creencia nuclear probable es «no puedo con la incertidumbre». La idea central del desamparo es «soy impotente / incapaz».", "Desamor": "**No en este caso.** La regla no habla de ser querido: habla de control. La creencia probable es «no puedo con la incertidumbre», del dominio **desamparo** («soy impotente / incapaz»).", "Desvalorización": "**No en este caso.** La regla no habla de valer o de ser defectuoso: habla de control. La creencia probable es «no puedo con la incertidumbre», del dominio **desamparo** («soy impotente / incapaz»)." } }, { "id": "quiz_pareja", "type": "choice", "prompt": "«Si me muestro como soy, me van a dejar»: ¿a qué dominio apunta?", "help": "Ejemplo del área pareja (2 de 3).", "options": [ "Desamparo", "Desamor", "Desvalorización" ], "feedback": { "Desamor": "**Exacto.** La creencia nuclear probable es «no soy querible», la idea central del desamor.", "Desamparo": "**No en este caso.** El temor no es a no poder, sino a que lo dejen. La creencia probable es «no soy querible», del dominio **desamor**.", "Desvalorización": "**No en este caso.** El temor central no es no valer, sino que lo dejen. La creencia probable es «no soy querible», del dominio **desamor**." } }, { "id": "quiz_depresion", "type": "choice", "prompt": "«Si no soy productivo, no valgo»: ¿a qué dominio apunta?", "help": "Ejemplo del área depresión (3 de 3).", "options": [ "Desamparo", "Desamor", "Desvalorización" ], "feedback": { "Desvalorización": "**Exacto.** La creencia nuclear probable es «no sirvo». La idea central de la desvalorización es «no valgo / soy defectuoso».", "Desamparo": "**No en este caso.** No dice «no puedo», dice «no valgo». La creencia probable es «no sirvo», del dominio **desvalorización**.", "Desamor": "**No en este caso.** No habla de ser querido, sino de valer. La creencia probable es «no sirvo», del dominio **desvalorización**." } }, { "id": "tecnicas", "type": "info", "title": "Técnicas para empezar a modificarlas", "content": "- **Registro de datos positivos:** anotar cada día evidencia, por pequeña que sea, que contradiga la creencia nuclear negativa.\n- **Continuo cognitivo:** en vez de «valgo / no valgo», ubicar la situación en una escala de 0 a 100 para romper el todo o nada.\n- **Reescribir la regla:** convertir «tengo que ser perfecto» en «prefiero hacerlo bien, y el error es parte de aprender».\n- **Actuar contra la regla (experimentos):** pedir ayuda a propósito y observar qué pasa realmente.\n- **Creencia nuclear alternativa:** formular una versión más ajustada («soy suficiente, con virtudes y límites») y buscar evidencia que la sostenga." }, { "id": "carla", "type": "info", "title": "Caso clínico: Carla, 38 años", "content": "**Depresión y sobreexigencia.** Carla llega agotada. Trabaja de más, no delega y se siente vacía. Con la flecha descendente aparece: «si dejo de rendir, van a ver quién soy realmente» → creencia nuclear de desvalorización: «no valgo por mí, solo por lo que produzco».\n\n**Trabajo en sesión:** se identifica el supuesto («si produzco, valgo»), se reescribe la regla y se diseña un experimento: delegar una tarea y registrar qué pasa con su valor a los ojos de los demás. La creencia empieza a resquebrajarse cuando la evidencia real no coincide con la predicción." }, { "id": "guiado_intro", "type": "info", "title": "Ejercicio guiado: de la hoja a la raíz", "content": "Ahora vas a recorrer el camino con un pensamiento tuyo. Tus respuestas van a formar tu hoja de trabajo «reglas, supuestos y creencia nuclear».\n\n1. Elegí un pensamiento automático que te traiga mucha emoción.\n2. Aplicá la flecha descendente al menos tres veces.\n3. Cuando llegues a una frase corta sobre vos («soy…», «no…»), detenete: probablemente sea una creencia nuclear.\n4. Ubicala en uno de los tres dominios.\n5. Escribí la regla o supuesto que usás para no sentir esa creencia.\n6. Formulá una creencia alternativa más ajustada y realista.\n\nAndá a tu ritmo. Si te moviliza mucho, podés frenar, ir a **Calmarme** y retomarlo en sesión." }, { "id": "pensamiento", "type": "text", "prompt": "¿Qué pensamiento automático te trae mucha emoción?", "help": "Escribilo tal como aparece. En el ejemplo: «Me equivoqué en la reunión.»" }, { "id": "flecha_1", "type": "text", "prompt": "Si eso fuera cierto, ¿qué significaría?", "help": "En el ejemplo: «Que van a notar que no sé.»" }, { "id": "flecha_2", "type": "text", "prompt": "Y si eso fuera cierto, ¿qué significaría?", "help": "En el ejemplo: «Que no estoy a la altura del puesto.»" }, { "id": "flecha_3", "type": "text", "prompt": "¿Y eso qué diría de vos?", "help": "En el ejemplo: «Que no sirvo.» Si llegaste a una frase corta sobre vos («soy…», «no…»), probablemente sea la creencia nuclear." }, { "id": "flecha_4", "type": "text", "prompt": "Si todavía no llegaste a una frase corta sobre vos: ¿y eso qué significaría?", "help": "Seguí preguntando hasta llegar a la idea de fondo. Si ya llegaste, tocá «Saltar».", "optional": true }, { "id": "creencia", "type": "text", "prompt": "¿A qué creencia nuclear llegaste?", "help": "Una frase corta sobre vos: «soy…», «no…». En el ejemplo: «No sirvo.»" }, { "id": "dominio", "type": "choice", "prompt": "¿En qué dominio la ubicás?", "options": [ "Desamparo: «soy impotente / incapaz»", "Desamor: «no soy querible»", "Desvalorización: «no valgo / soy defectuoso»", "No lo tengo claro" ], "feedback": { "Desamparo: «soy impotente / incapaz»": "Otras creencias de este dominio: «no puedo con nada», «soy débil», «no tengo control», «estoy atrapado».", "Desamor: «no soy querible»": "Otras creencias de este dominio: «no merezco cariño», «voy a terminar solo», «hay algo malo en mí».", "Desvalorización: «no valgo / soy defectuoso»": "Otras creencias de este dominio: «soy un fracaso», «no sirvo», «soy mala persona». Es el dominio del ejemplo de la reunión y del caso de Carla.", "No lo tengo claro": "Está bien. Volvé a mirar los ejemplos de cada dominio y, si seguís con dudas, revisalo en sesión con tu psicólogo." } }, { "id": "regla", "type": "text", "prompt": "¿Qué regla o supuesto usás para no sentir esa creencia?", "help": "Puede ser una actitud («es terrible…»), una regla («nunca debo…», «tengo que…») o un «si… entonces…». Carla: «si produzco, valgo»." }, { "id": "alternativa", "type": "text", "prompt": "¿Qué creencia alternativa, más ajustada y realista, podés formular?", "help": "Por ejemplo: «soy suficiente, con virtudes y límites»." }, { "id": "hoja", "type": "reflect", "title": "Tu hoja: reglas, supuestos y creencia nuclear", "template": "Pensamiento de partida: «{{pensamiento}}». Flecha descendente: «{{flecha_1}}» → «{{flecha_2}}» → «{{flecha_3}}». Creencia nuclear: «{{creencia}}» ({{dominio}}). Regla o supuesto que la protege: «{{regla}}». Creencia alternativa: «{{alternativa}}».", "content": "Tus respuestas quedan guardadas: las podés volver a ver en este ejercicio, en «Mis respuestas». Si en tu perfil está activado «Compartir mis registros con mi psicólogo», tu psicólogo también las puede ver." }, { "id": "registro", "type": "reflect", "title": "Registro de creencia nuclear alternativa", "template": "Creencia antigua: «{{creencia}}». Creencia nueva, más ajustada: «{{alternativa}}».", "content": "La creencia nueva se sostiene con evidencia. En la próxima pantalla anotá pruebas que la apoyen, por pequeñas que sean." }, { "id": "registro_evidencia", "type": "list", "prompt": "¿Qué evidencia apoya tu creencia nueva?", "help": "Hechos de hoy o de tu historia, por mínimos que sean. El registro original tiene un renglón por día: completá los que puedas hoy y seguí durante la semana en «Registro de creencias nucleares».", "count": 5, "min": 1 }, { "id": "refl_herencia", "type": "text", "prompt": "¿Qué reglas de vida heredaste sin haberlas elegido?", "help": "Preguntas de reflexión: respondé las que quieras, podés saltear cualquiera.", "optional": true }, { "id": "refl_dominio", "type": "choice", "prompt": "¿Cuál de los tres dominios resuena más con vos?", "options": [ "Desamparo", "Desamor", "Desvalorización" ], "optional": true }, { "id": "refl_tema", "type": "text", "prompt": "¿Qué tema se repite en tus conflictos, sin importar el área?", "optional": true }, { "id": "refl_evitar", "type": "text", "prompt": "¿Qué hacés para no sentir tu creencia nuclear más dolorosa?", "optional": true }, { "id": "refl_regla", "type": "text", "prompt": "¿Cómo sería tu vida si esa regla dejara de mandar?", "optional": true }, { "id": "refl_creerte", "type": "text", "prompt": "¿Qué creencia alternativa te gustaría poder creerte de verdad?", "optional": true }, { "id": "refl_historia", "type": "text", "prompt": "¿Qué evidencia de tu historia contradice tu creencia negativa?", "optional": true }, { "id": "para_llevar", "type": "info", "title": "Para llevar", "content": "- Hay tres niveles: pensamientos automáticos (hojas), creencias intermedias (tronco) y nucleares (raíz).\n- Las creencias intermedias son actitudes, reglas y supuestos condicionales.\n- Las creencias nucleares negativas se agrupan en desamparo, desamor y desvalorización.\n- Se llega a ellas con la flecha descendente: «si fuera cierto, ¿qué significaría?».\n- Se modifican con evidencia, continuo cognitivo, reescritura de reglas y experimentos." }, { "id": "semana", "type": "info", "title": "Para esta semana", "content": "Tareas para casa, a lo largo de la semana:\n\n- Aplicá la flecha descendente a **dos pensamientos** distintos: podés volver a hacer este ejercicio con cada uno.\n- Identificá una regla «si… entonces…» que ordena tu conducta y escribila.\n- Registrá cada día una prueba, mínima, a favor de tu creencia alternativa (podés usar «Registro de creencias nucleares»).\n- Diseñá un pequeño experimento para actuar en contra de una de tus reglas y anotá el resultado.\n\nEl próximo capítulo es **«Cuestionamiento socrático y reestructuración»**." } ]$steps$::jsonb),
  ('tcc-reestructuracion', 'Cuestionamiento socrático y reestructuración', 'Poné a prueba un pensamiento con preguntas socráticas y construí uno alternativo con el registro de 7 columnas.', 'thought_record', 'tcc', 'adultos', 'tcc', 30, 205,
   $steps$[ { "id": "intro", "type": "info", "title": "El motor del cambio", "content": "Ya sabés detectar pensamientos, distorsiones y creencias. Ahora viene el motor del cambio: aprender a ponerlos a prueba con preguntas y a construir formas de pensar más ajustadas y útiles.\n\nCuestionar no es discutir con vos mismo ni obligarte a pensar bonito. Es hacerte buenas preguntas, como un **detective curioso** que quiere ver toda la evidencia antes de dar un veredicto. En vez de creerle al primer pensamiento, lo tratás como una hipótesis: «¿es esto realmente cierto?, ¿qué pruebas tengo a favor y en contra?, ¿hay otra forma de verlo?»." }, { "id": "profundizar", "type": "info", "title": "Para profundizar (opcional)", "content": "El **cuestionamiento socrático** es un método de descubrimiento guiado: mediante preguntas abiertas, el terapeuta ayuda a la persona a examinar sus propios pensamientos y llegar a conclusiones más ajustadas por sí misma, en lugar de imponerle una interpretación.\n\nLa **reestructuración cognitiva** es el proceso más amplio de identificar, evaluar y modificar cogniciones desadaptativas; el diálogo socrático es una de sus herramientas centrales, junto con los experimentos conductuales y la búsqueda de evidencia." }, { "id": "actitud", "type": "info", "title": "La actitud correcta", "content": "El objetivo no es «ganar» ni convencer, sino abrir la mirada. Una buena pregunta socrática genera una duda genuina, no una respuesta forzada.\n\n**La regla de oro:** preguntar con curiosidad real, no para llevar a la persona a donde ya decidimos." }, { "id": "preguntas", "type": "info", "title": "Las preguntas fundamentales", "content": "Podés agrupar el cuestionamiento en cuatro familias de preguntas:\n\n- **Examinar la evidencia:** ¿Qué pruebas tengo a favor de este pensamiento? ¿Qué pruebas tengo en contra? ¿Estoy tomando una suposición como un hecho?\n- **Buscar alternativas:** ¿Hay otra forma de ver esto? ¿Qué diría alguien que me quiere bien? ¿Qué le diría yo a un amigo en esta situación?\n- **Descatastrofizar:** ¿Qué es lo peor que podría pasar? ¿Y lo mejor? ¿Qué es lo más probable? Si pasara lo peor, ¿cómo lo afrontaría?\n- **Evaluar la utilidad:** ¿Me sirve pensar así? ¿Qué efecto tiene en mí creer esto? ¿Qué ganaría pensándolo de otro modo?" }, { "id": "quiz_familia_1", "type": "choice", "prompt": "«Si pasara lo peor, ¿cómo lo afrontaría?»: ¿de qué familia es?", "help": "Repaso rápido (1 de 2).", "options": [ "Examinar la evidencia", "Buscar alternativas", "Descatastrofizar", "Evaluar la utilidad" ], "feedback": { "Descatastrofizar": "**Exacto.** Es de la familia descatastrofizar, junto con «¿Qué es lo peor que podría pasar? ¿Y lo mejor? ¿Qué es lo más probable?».", "Examinar la evidencia": "**No.** Esa familia pregunta por pruebas a favor y en contra. Esta mira lo peor y cómo lo afrontarías: es de **descatastrofizar**.", "Buscar alternativas": "**No.** Esa familia busca otra forma de ver la situación. Esta mira lo peor y cómo lo afrontarías: es de **descatastrofizar**.", "Evaluar la utilidad": "**No.** Esa familia pregunta si te sirve pensar así. Esta mira lo peor y cómo lo afrontarías: es de **descatastrofizar**." } }, { "id": "quiz_familia_2", "type": "choice", "prompt": "«¿Qué le diría yo a un amigo en esta situación?»: ¿de qué familia es?", "help": "Repaso rápido (2 de 2).", "options": [ "Examinar la evidencia", "Buscar alternativas", "Descatastrofizar", "Evaluar la utilidad" ], "feedback": { "Buscar alternativas": "**Exacto.** Es de la familia buscar alternativas, junto con «¿Hay otra forma de ver esto?» y «¿Qué diría alguien que me quiere bien?».", "Examinar la evidencia": "**No.** Esa familia pregunta por pruebas a favor y en contra. Esta busca otra forma de ver la situación: es de **buscar alternativas**.", "Descatastrofizar": "**No.** Esa familia mira lo peor, lo mejor y lo más probable. Esta busca otra forma de ver la situación: es de **buscar alternativas**.", "Evaluar la utilidad": "**No.** Esa familia pregunta si te sirve pensar así. Esta busca otra forma de ver la situación: es de **buscar alternativas**." } }, { "id": "quiz_retorica", "type": "choice", "prompt": "¿Cuál de estas dos es una pregunta socrática?", "options": [ "«¿No te parece que exagerás?»", "«¿Qué pruebas tengo en contra de este pensamiento?»" ], "feedback": { "«¿No te parece que exagerás?»": "**No es socrática.** Es una pregunta retórica disfrazada: ya trae la respuesta metida. Una buena pregunta socrática genera una duda genuina, no una respuesta forzada.", "«¿Qué pruebas tengo en contra de este pensamiento?»": "**Exacto.** Es una pregunta abierta, de la familia examinar la evidencia: no trae la respuesta puesta, invita a mirar los datos con curiosidad." } }, { "id": "errores", "type": "info", "title": "Errores frecuentes", "content": "Qué se confunde y cómo evitarlo:\n\n- **Convertir el socrático en interrogatorio.** Si la persona (o vos mismo) se siente acorralada, se cierra. Preguntá desde la curiosidad.\n- **Preguntas retóricas disfrazadas.** «¿No te parece que exagerás?» no es socrático: ya trae la respuesta metida.\n- **Buscar el pensamiento «positivo».** La meta es un pensamiento creíble y ajustado, no uno alegre que no te creés.\n- **Saltar la evidencia en contra propia.** Es fácil listar pruebas a favor del pensamiento negativo y olvidar las de en contra: forzate a buscar ambas.\n- **Quedarse solo en las palabras.** A veces el mejor cuestionamiento es un experimento: probar en la realidad, no solo debatir en la cabeza." }, { "id": "pasos", "type": "info", "title": "Reestructuración cognitiva paso a paso", "content": "1. Identificá la situación y la emoción (con intensidad 0–100).\n2. Escribí el pensamiento automático caliente y su credibilidad (0–100).\n3. Nombrá la distorsión, si la hay.\n4. Buscá evidencia **a favor** del pensamiento (hechos, no interpretaciones).\n5. Buscá evidencia **en contra** (lo que solés pasar por alto).\n6. Construí un pensamiento alternativo que integre toda la evidencia, no que niegue lo negativo.\n7. Volvé a puntuar: credibilidad del pensamiento original e intensidad de la emoción. ¿Bajaron?" }, { "id": "alternativo_info", "type": "info", "title": "Cómo construir un buen pensamiento alternativo", "content": "- Que sea creíble para vos (si no te lo creés, no funciona).\n- Que integre lo cierto del pensamiento original sin quedarse solo en eso.\n- Que sea equilibrado, no un eslogan optimista.\n- Que puedas usarlo la próxima vez que aparezca la situación." }, { "id": "quiz_alternativo", "type": "choice", "prompt": "Para «voy a fracasar seguro», ¿cuál es un pensamiento alternativo ajustado?", "options": [ "«Me va a salir perfecto»", "«No sé cómo va a salir, me preparé razonablemente y, pase lo que pase, puedo manejarlo»" ], "feedback": { "«Me va a salir perfecto»": "**No.** Es el opuesto forzado: un eslogan optimista que difícilmente te creas. Un alternativo ajustado sería: «no sé cómo va a salir, me preparé razonablemente y, pase lo que pase, puedo manejarlo».", "«No sé cómo va a salir, me preparé razonablemente y, pase lo que pase, puedo manejarlo»": "**Exacto.** Es creíble, equilibrado y lo podés usar la próxima vez. No es «voy a fracasar seguro» ni su opuesto forzado, «me va a salir perfecto»." } }, { "id": "areas_1", "type": "info", "title": "Ejemplos por área (1 de 2)", "content": "Del pensamiento automático al alternativo ajustado:\n\n- **Ansiedad:** «Me va a dar un ataque y no lo soporto» → «La ansiedad es intensa pero pasa; ya la atravesé antes».\n- **Depresión:** «No sirvo para nada» → «Hoy me cuesta, pero hay cosas que sí hago y sí me importan».\n- **Pareja:** «No le importo» → «No me escribió; puede haber muchas razones que no tienen que ver conmigo».\n- **Autoestima:** «Todos lo hacen mejor que yo» → «Cada uno tiene su ritmo; yo también tengo avances»." }, { "id": "areas_2", "type": "info", "title": "Ejemplos por área (2 de 2)", "content": "- **Trabajo:** «Un error y arruiné todo» → «Cometí un error puntual; el resto del trabajo sigue en pie».\n- **Universidad:** «Si repruebo, soy un fracaso» → «Reprobar una materia es un traspié, no una definición de quién soy».\n- **Duelo:** «No tengo derecho a estar bien» → «Puedo extrañar y a la vez seguir viviendo; ambas cosas conviven».\n- **Perfeccionismo:** «Si no es perfecto, no vale» → «Bien hecho es suficiente; lo perfecto no existe y me agota»." }, { "id": "ana", "type": "info", "title": "Caso clínico: Ana, 26 años", "content": "**Ansiedad social.** Ana evita reuniones por miedo a «quedar en ridículo». Pensamiento caliente: «todos van a ver que estoy nerviosa y me van a juzgar» (lectura de mente + catastrofización), credibilidad 90.\n\n- **Evidencia a favor:** «a veces me tiembla la voz».\n- **Evidencia en contra:** «nunca nadie me lo comentó, me han invitado de nuevo, yo no juzgo a otros por estar nerviosos».\n- **Alternativo:** «puedo estar algo nerviosa y aun así participar; la mayoría está pendiente de lo suyo, no de mí».\n\nLa credibilidad del original baja a 40; la ansiedad, de 80 a 50. Se cierra con un experimento: ir a una reunión y registrar cuántos comentarios recibe realmente." }, { "id": "guiado_intro", "type": "info", "title": "Ejercicio guiado: tu primera reestructuración", "content": "Tomá un pensamiento caliente de tus registros y recorré el formulario completo, columna por columna, **sin saltarte la evidencia en contra**.\n\nEs el registro de pensamientos de 7 columnas: situación, emoción, pensamiento automático, distorsión, evidencia a favor, evidencia en contra y pensamiento alternativo con nueva puntuación. En cada pregunta vas a ver cómo lo hizo Ana.\n\nSi empezaste un registro en «Los pensamientos automáticos», retomalo acá: lo encontrás en ese ejercicio, en «Mis respuestas»." }, { "id": "situacion", "type": "text", "prompt": "1. Situación: ¿qué pasó?", "help": "Dónde, cuándo, con quién. Ana: una reunión, de esas que suele evitar por miedo a «quedar en ridículo»." }, { "id": "emocion", "type": "checklist", "prompt": "2. Emoción: ¿qué sentiste?", "help": "Cada emoción se nombra con una sola palabra. Marcá hasta tres. Ana sintió ansiedad.", "options": [ "Angustia", "Ansiedad", "Miedo", "Nerviosismo", "Pánico", "Bronca", "Tristeza", "Vergüenza", "Culpa", "Frustración", "Inseguridad", "Otra" ], "max": 3 }, { "id": "emocion_otra", "type": "text", "prompt": "Si marcaste «Otra», ¿cuál fue?", "help": "Una sola palabra. Si no marcaste «Otra», tocá «Saltar».", "optional": true }, { "id": "emocion_intensidad", "type": "scale", "prompt": "¿Con qué intensidad la sentiste? (de 0 a 100)", "help": "Si marcaste más de una, puntuá la más fuerte. Ana: ansiedad, 80.", "min": 0, "max": 100, "min_label": "Nada", "max_label": "Máxima" }, { "id": "pensamiento", "type": "text", "prompt": "3. Pensamiento automático: ¿qué pensaste?", "help": "El pensamiento caliente, tal como apareció. Ana: «todos van a ver que estoy nerviosa y me van a juzgar»." }, { "id": "credibilidad", "type": "scale", "prompt": "¿Cuánto creés ese pensamiento? (de 0 a 100)", "help": "Ana: 90.", "min": 0, "max": 100, "min_label": "Nada", "max_label": "Totalmente" }, { "id": "distorsion", "type": "checklist", "prompt": "4. Distorsión: ¿cuál o cuáles encajan?", "help": "Si la hay; puede haber más de una. Ana: lectura de mente + catastrofización.", "options": [ "Todo o nada", "Sobregeneralización", "Filtro mental", "Descalificar lo positivo", "Lectura de mente", "Adivinación del futuro", "Catastrofización", "Razonamiento emocional", "Debería / tener que", "Etiquetación", "Personalización", "Culpabilización", "No encuentro ninguna" ] }, { "id": "evidencia_favor", "type": "text", "prompt": "5. Evidencia a favor: ¿qué hechos apoyan el pensamiento?", "help": "Hechos, no interpretaciones. Ana: «a veces me tiembla la voz»." }, { "id": "evidencia_contra", "type": "text", "prompt": "6. Evidencia en contra: ¿qué hechos no encajan con el pensamiento?", "help": "Lo que solés pasar por alto: forzate a buscarla. Te pueden ayudar estas preguntas: ¿estoy tomando una suposición como un hecho? ¿Qué le diría yo a un amigo en esta situación?\n\nAna: «nunca nadie me lo comentó, me han invitado de nuevo, yo no juzgo a otros por estar nerviosos»." }, { "id": "alternativo", "type": "text", "prompt": "7. Pensamiento alternativo: ¿qué forma más ajustada hay de verlo?", "help": "Que integre toda la evidencia, no que niegue lo negativo: creíble, equilibrado y que puedas usar la próxima vez.\n\nAna: «puedo estar algo nerviosa y aun así participar; la mayoría está pendiente de lo suyo, no de mí»." }, { "id": "credibilidad_alternativo", "type": "scale", "prompt": "¿Cuánto creés el pensamiento alternativo? (de 0 a 100)", "help": "Si no te lo creés, no funciona: si da muy bajo, volvé atrás y ajustalo.", "min": 0, "max": 100, "min_label": "Nada", "max_label": "Totalmente" }, { "id": "credibilidad_despues", "type": "scale", "prompt": "¿Cuánto creés ahora el pensamiento automático del principio? (de 0 a 100)", "help": "Ana: bajó de 90 a 40.", "min": 0, "max": 100, "min_label": "Nada", "max_label": "Totalmente" }, { "id": "emocion_despues", "type": "scale", "prompt": "¿Con qué intensidad sentís ahora la emoción? (de 0 a 100)", "help": "Puntuá la misma emoción de antes. Ana: la ansiedad bajó de 80 a 50.", "min": 0, "max": 100, "min_label": "Nada", "max_label": "Máxima" }, { "id": "resumen", "type": "reflect", "title": "Tu reestructuración", "template": "Situación: «{{situacion}}». Pensamiento automático: «{{pensamiento}}». Distorsión: {{distorsion}}. Evidencia en contra: «{{evidencia_contra}}». Pensamiento alternativo: «{{alternativo}}».", "content": "Compará tus puntuaciones de antes y de ahora: ¿bajaron la credibilidad del pensamiento y la intensidad de la emoción?\n\nTus respuestas quedan guardadas: las podés volver a ver en este ejercicio, en «Mis respuestas». Si en tu perfil está activado «Compartir mis registros con mi psicólogo», tu psicólogo también las puede ver." }, { "id": "refl_preguntas", "type": "text", "prompt": "¿Qué preguntas socráticas te resultan más útiles?", "help": "Preguntas de reflexión: respondé las que quieras, podés saltear cualquiera.", "optional": true }, { "id": "refl_cuesta", "type": "choice", "prompt": "¿Te cuesta más buscar la evidencia en contra o construir el alternativo?", "options": [ "Buscar la evidencia en contra", "Construir el alternativo", "Las dos por igual" ], "optional": true }, { "id": "refl_cuerpo", "type": "text", "prompt": "¿Qué pasa en tu cuerpo cuando un pensamiento pierde credibilidad?", "optional": true }, { "id": "refl_experimento", "type": "text", "prompt": "¿En qué situaciones el mejor cuestionamiento sería un experimento y no un debate?", "optional": true }, { "id": "refl_hablarte", "type": "text", "prompt": "¿Cómo te hablarías si te trataras como a alguien que querés?", "optional": true }, { "id": "refl_a_mano", "type": "text", "prompt": "¿Qué pensamiento alternativo te gustaría tener a mano para tu situación más difícil?", "optional": true }, { "id": "para_llevar", "type": "info", "title": "Para llevar", "content": "- El cuestionamiento socrático es descubrimiento guiado, no discusión ni interrogatorio.\n- Cuatro familias de preguntas: evidencia, alternativas, descatastrofizar y utilidad.\n- La reestructuración va de la situación al pensamiento alternativo, pasando por la evidencia.\n- Un buen alternativo es creíble, equilibrado y utilizable, no un eslogan optimista.\n- A veces el mejor cuestionamiento es un experimento en la realidad." }, { "id": "semana", "type": "info", "title": "Para esta semana", "content": "Tareas para casa, a lo largo de la semana:\n\n- Completá el formulario de 7 columnas con al menos **tres pensamientos**: volvé a hacer este ejercicio con cada uno.\n- En cada uno, obligate a escribir tanta evidencia en contra como a favor.\n- Diseñá un experimento conductual para poner a prueba una predicción negativa.\n- Anotá si, al usar el pensamiento alternativo, la emoción baja de intensidad.\n- Repasá «50 preguntas socráticas» y elegí tus cinco favoritas.\n\nEl próximo capítulo es **«El modelo ABC de Ellis»**." } ]$steps$::jsonb),
  ('tcc-abc-ellis', 'El modelo ABC de Ellis', 'Descubrí cómo tus «debo» inflan el malestar y convertilos en preferencias flexibles con el registro ABCDE.', 'thought_record', 'tcc', 'adultos', 'tcc', 30, 206,
   $steps$[ { "id": "intro", "type": "info", "title": "El modelo ABC de Ellis", "content": "Albert Ellis llegó, por otro camino, a una idea muy parecida a la de Beck: **no son los hechos los que nos perturban, sino las creencias con las que los interpretamos**.\n\nSu modelo ABC ordena ese proceso de una forma simple y potente." }, { "id": "sencilla", "type": "info", "title": "Explicación sencilla", "content": "Ellis lo resumía con una frase antigua, de Epicteto: «Las personas no se perturban por las cosas, sino por la opinión que tienen de ellas».\n\nEl modelo ABC dice: pasa algo (**A**), lo interpretás con ciertas creencias (**B**), y de ahí surge lo que sentís y hacés (**C**).\n\nLa mayoría cree que A causa C directamente («me dejaron, por eso sufro»), pero **en el medio siempre está B**." }, { "id": "clinica", "type": "info", "title": "Para profundizar", "content": "Esta es la explicación clínica. Si preferís, pasá a la pantalla siguiente.\n\nLa Terapia Racional Emotiva Conductual (TREC/REBT) de Ellis sostiene que la perturbación emocional deriva de **creencias irracionales**: exigencias absolutas y rígidas («debo», «tengo que», «debería») desde las que se derivan tres conclusiones típicas:\n\n- el **tremendismo** (catastrofizar);\n- la **baja tolerancia a la frustración** («no lo soporto»);\n- la **condena global** de sí mismo o de otros («soy un inútil», «es una mala persona»).\n\nEl trabajo terapéutico consiste en detectar esas exigencias, debatirlas y sustituirlas por preferencias flexibles." }, { "id": "letras", "type": "info", "title": "Las letras del modelo", "content": "- **A — Acontecimiento activador.** El hecho o situación (real o imaginado) que dispara el proceso.\n- **B — Creencias (Beliefs).** Lo que la persona piensa y cree sobre A. Aquí está el corazón del malestar.\n- **C — Consecuencias.** Las emociones, sensaciones físicas y conductas que resultan de B.\n- **D — Debate (Disputa).** Cuestionar y confrontar las creencias irracionales de B.\n- **E — Nueva filosofía (Effect).** El efecto: una creencia más racional y una emoción más adaptativa." }, { "id": "irracional_racional", "type": "info", "title": "Creencias irracionales vs. racionales", "content": "- **Irracional (exigencia):** «Debo caerle bien a todos; si no, es horrible y no lo soporto.»\n- **Racional (preferencia):** «Me gustaría caer bien, pero no siempre va a pasar, y puedo tolerarlo.»\n\nEl giro central de Ellis: pasar de la **exigencia rígida** («tengo que») a la **preferencia flexible** («prefiero»)." }, { "id": "reconocer", "type": "info", "title": "¿Cómo reconocer una creencia irracional?", "content": "- Contiene una **exigencia absoluta**: «debo», «tengo que», «debería», «no puede ser que».\n- Concluye en **tremendismo**: «es horrible», «es lo peor que podría pasar».\n- Expresa **baja tolerancia a la frustración**: «no lo soporto», «no puedo con esto».\n- Termina en **condena global**: «soy un inútil», «es un desastre de persona»." }, { "id": "debate", "type": "info", "title": "Debate: cómo disputar la creencia (D)", "content": "Ellis proponía tres tipos de debate, que podés combinar:\n\n- **Empírico (¿es verdad?):** ¿Dónde está la prueba de que esto DEBE ser así?\n- **Lógico (¿tiene sentido?):** ¿Se sigue lógicamente que, porque lo prefiero, tenga que ocurrir?\n- **Pragmático (¿me sirve?):** ¿Adónde me lleva sostener esta exigencia? ¿Me ayuda o me hunde?" }, { "id": "ejemplos_1", "type": "info", "title": "Ejemplos por área (1 de 2)", "content": "Del hecho (A) a la creencia irracional (B) y a la racional (E):\n\n- **Ansiedad.** A: debo dar una charla. B: «Tengo que hacerlo perfecto o es un desastre». E: «Quiero hacerlo bien; equivocarme es humano».\n- **Depresión.** A: un plan se cae. B: «Nada me sale, no lo soporto». E: «Es frustrante, y aun así puedo seguir».\n- **Pareja.** A: una discusión. B: «Si discutimos, es que no me ama». E: «Discutir es normal; no define el amor».\n- **Autoestima.** A: una crítica. B: «No debería equivocarme nunca». E: «Puedo equivocarme y seguir valiendo»." }, { "id": "ejemplos_2", "type": "info", "title": "Ejemplos por área (2 de 2)", "content": "- **Trabajo.** A: un pedido difícil. B: «Debo poder con todo solo». E: «Puedo pedir ayuda; no me hace menos».\n- **Universidad.** A: una nota baja. B: «Tengo que ser el mejor siempre». E: «Prefiero ir bien; una nota no me define».\n- **Duelo.** A: sentir alivio. B: «No debería sentir esto, soy horrible». E: «Los sentimientos mezclados son normales».\n- **Perfeccionismo.** A: un detalle falla. B: «No puede tener ni un error». E: «Prefiero la excelencia, no la perfección»." }, { "id": "te_suena", "type": "checklist", "prompt": "¿Alguna de estas exigencias te suena?", "help": "Marcá las que se parezcan a cosas que te decís. Si ninguna, tocá «Saltar».", "optional": true, "options": [ "«Tengo que hacerlo perfecto o es un desastre»", "«Nada me sale, no lo soporto»", "«Si discutimos, es que no me ama»", "«No debería equivocarme nunca»", "«Debo poder con todo solo»", "«Tengo que ser el mejor siempre»", "«No debería sentir esto, soy horrible»", "«No puede tener ni un error»" ] }, { "id": "ellis_beck", "type": "info", "title": "Ellis y Beck: comparación", "content": "Los dos modelos son primos: ambos ubican la interpretación en el centro. Se diferencian en el énfasis y el estilo.\n\n- **Foco principal.** Beck: pensamientos automáticos, distorsiones y esquemas. Ellis: creencias irracionales y exigencias absolutas.\n- **Diana del cambio.** Beck: ajustar la interpretación a la evidencia. Ellis: cambiar exigencias por preferencias.\n- **Método típico.** Beck: descubrimiento guiado (socrático), experimentos. Ellis: debate más directo y confrontativo de creencias.\n- **Estructura.** Beck: situación → pensamiento → emoción → conducta. Ellis: A → B → C → D → E.\n- **Estilo del terapeuta.** Beck: colaborativo, empírico. Ellis: activo, didáctico, a veces provocador.\n- **Qué comparten.** La interpretación (B / pensamiento) media entre el hecho y la emoción: el malestar no viene del hecho, sino de la creencia." }, { "id": "errores", "type": "info", "title": "Errores frecuentes", "content": "Qué se confunde y cómo evitarlo:\n\n- **Confundir A con C.** «Me sentí humillado» no es el hecho (A), es la consecuencia (C). El hecho es «me corrigieron delante de otros».\n- **Meter la creencia dentro de A.** «Me trataron injustamente» ya es interpretación (B). En A va solo lo observable.\n- **Debatir la emoción en vez de la creencia.** No se debate sentir tristeza; se debate la exigencia que la infla.\n- **Cambiar exigencia por otra exigencia.** «Debo dejar de exigirme» sigue siendo un «debo». Apuntá a la preferencia flexible.\n\nEn las próximas pantallas, probá distinguirlos." }, { "id": "quiz_1", "type": "choice", "prompt": "«Me corrigieron delante de otros». ¿Qué letra es?", "help": "1 de 4.", "options": [ "A — Acontecimiento", "B — Creencia", "C — Consecuencia" ], "feedback": { "A — Acontecimiento": "**¡Bien! Es A:** el hecho observable, sin interpretaciones. En A va solo lo observable.", "B — Creencia": "**Es A:** el hecho observable. B sería lo que la persona piensa y cree sobre ese hecho; por ejemplo, «me trataron injustamente».", "C — Consecuencia": "**Es A:** el hecho observable. C es lo que resulta de B: emociones, sensaciones físicas y conductas, como sentirse humillado." } }, { "id": "quiz_2", "type": "choice", "prompt": "«Me sentí humillado». ¿Qué letra es?", "help": "2 de 4.", "options": [ "A — Acontecimiento", "B — Creencia", "C — Consecuencia" ], "feedback": { "A — Acontecimiento": "**Es C, no A.** Es un error frecuente: «me sentí humillado» no es el hecho, es la consecuencia. El hecho es «me corrigieron delante de otros».", "B — Creencia": "**Es C:** una emoción, no una creencia. B es lo que la persona piensa sobre el hecho; la humillación es lo que resulta de eso.", "C — Consecuencia": "**¡Bien! Es C:** la consecuencia. Las emociones, sensaciones físicas y conductas que resultan de B." } }, { "id": "quiz_3", "type": "choice", "prompt": "«Me trataron injustamente». ¿Qué letra es?", "help": "3 de 4.", "options": [ "A — Acontecimiento", "B — Creencia", "C — Consecuencia" ], "feedback": { "A — Acontecimiento": "**Es B.** Parece un hecho, pero ya es interpretación. Meter la creencia dentro de A es un error frecuente: en A va solo lo observable.", "B — Creencia": "**¡Bien! Es B:** ya es interpretación. Meter la creencia dentro de A es un error frecuente; en A va solo lo observable.", "C — Consecuencia": "**Es B:** una interpretación del hecho. C sería la emoción o la conducta que resulta de esa creencia." } }, { "id": "quiz_4", "type": "choice", "prompt": "«Debo dejar de exigirme». ¿Qué es?", "help": "4 de 4.", "options": [ "Una exigencia rígida", "Una preferencia flexible" ], "feedback": { "Una exigencia rígida": "**¡Bien!** Aunque hable de exigirse menos, sigue siendo un «debo». Cambiar una exigencia por otra es un error frecuente: apuntá a la preferencia flexible («prefiero», «me gustaría»).", "Una preferencia flexible": "**Es una exigencia.** Aunque hable de exigirse menos, sigue siendo un «debo». Cambiar una exigencia por otra es un error frecuente: apuntá a la preferencia flexible («prefiero», «me gustaría»)." } }, { "id": "diego", "type": "info", "title": "Diego, 31 años", "content": "Ira y pareja.\n\nDiego estalla cuando su pareja llega tarde.\n\n- **A:** la pareja llega 20 minutos tarde.\n- **B:** «no tiene ningún derecho a hacerme esperar, debería respetarme siempre, esto es intolerable».\n- **C:** ira intensa, reproche, portazo.\n\n**Debate (D):** ¿dónde está escrito que SIEMPRE debe ser puntual? ¿Es intolerable o muy molesto? ¿Le sirve reaccionar así?\n\n**Nueva filosofía (E):** «prefiero que sea puntual y me molesta que no lo sea, pero no es una catástrofe ni una falta de respeto absoluta; puedo decirlo con calma». La emoción pasa de ira a fastidio manejable." }, { "id": "guiado", "type": "info", "title": "Tu primer ABCDE", "content": "Elegí una situación reciente que te haya alterado. Vas a completar tu registro ABCDE en este orden, una pregunta por vez:\n\n- En **A**, escribí solo el hecho observable, sin interpretaciones.\n- En **C**, anotá qué sentiste y qué hiciste.\n- En **B**, buscá la creencia: ¿qué exigencia («debo/debería/tengo que») estaba detrás?\n- En **D**, debatila con las tres preguntas: ¿es verdad?, ¿tiene lógica?, ¿me sirve?\n- En **E**, escribí la versión racional, en forma de preferencia flexible." }, { "id": "a_hecho", "type": "text", "prompt": "A — ¿Qué pasó? Escribí solo el hecho observable", "help": "Sin interpretaciones. Diego anotó: «la pareja llega 20 minutos tarde». Ojo: «me trataron injustamente» ya es interpretación (B), y «me sentí humillado» es consecuencia (C)." }, { "id": "c_emocion", "type": "checklist", "prompt": "C — ¿Qué sentiste?", "help": "Marcá hasta tres. Diego sintió ira intensa.", "max": 3, "options": [ "Ira", "Fastidio", "Ansiedad", "Miedo", "Angustia", "Tristeza", "Frustración", "Humillación", "Vergüenza", "Culpa", "Otra" ] }, { "id": "c_emocion_otra", "type": "text", "prompt": "Si marcaste «Otra», ¿cuál fue?", "help": "Una sola palabra. Si no marcaste «Otra», tocá «Saltar».", "optional": true }, { "id": "c_intensidad", "type": "scale", "prompt": "¿Con qué intensidad lo sentiste?", "help": "Si marcaste más de una emoción, puntuá la más fuerte.", "min": 0, "max": 10, "min_label": "Nada", "max_label": "Máxima", "maps_to": "emotion_before" }, { "id": "c_conducta", "type": "text", "prompt": "C — ¿Qué hiciste?", "help": "Lo que hiciste (o dejaste de hacer) en ese momento. Diego: reproche y portazo." }, { "id": "b_creencia", "type": "text", "prompt": "B — ¿Qué exigencia («debo», «debería», «tengo que») estaba detrás?", "help": "Escribí la creencia tal como apareció, con tus palabras. Diego: «no tiene ningún derecho a hacerme esperar, debería respetarme siempre, esto es intolerable»." }, { "id": "b_senales", "type": "checklist", "prompt": "¿Qué señales de creencia irracional encontrás en tu B?", "help": "Es como subrayar las palabras de exigencia. Marcá todas las que aparezcan. Si no encontrás ninguna, tocá «Atrás» y preguntate qué exigencia («debo/debería/tengo que») estaba detrás.", "options": [ "Exigencia absoluta: «debo», «tengo que», «debería», «no puede ser que»", "Tremendismo: «es horrible», «es lo peor que podría pasar»", "Baja tolerancia a la frustración: «no lo soporto», «no puedo con esto»", "Condena global: «soy un inútil», «es un desastre de persona»", "Todavía no encuentro ninguna" ] }, { "id": "d_empirico", "type": "text", "prompt": "D — ¿Es verdad? ¿Dónde está la prueba de que esto DEBE ser así?", "help": "Es el debate empírico. Recordá: no se debate la emoción, sino la exigencia que la infla. En el caso de Diego: «¿dónde está escrito que SIEMPRE debe ser puntual?»." }, { "id": "d_logico", "type": "text", "prompt": "¿Tiene lógica? ¿Se sigue lógicamente que, porque lo prefiero, tenga que ocurrir?", "help": "Es el debate lógico. Para Diego, otra pregunta útil fue: «¿Es intolerable o muy molesto?»." }, { "id": "d_pragmatico", "type": "text", "prompt": "¿Me sirve? ¿Adónde me lleva sostener esta exigencia? ¿Me ayuda o me hunde?", "help": "Es el debate pragmático. En el caso de Diego: «¿Le sirve reaccionar así?»." }, { "id": "e_preferencia", "type": "text", "prompt": "E — ¿Cómo queda tu creencia como preferencia flexible?", "help": "Cambiá el «debo» por «prefiero» o «me gustaría», y el «no lo soporto» por «puedo tolerarlo». Ojo: «debo dejar de exigirme» sigue siendo un «debo». Diego: «prefiero que sea puntual y me molesta que no lo sea, pero no es una catástrofe ni una falta de respeto absoluta; puedo decirlo con calma»." }, { "id": "e_emocion", "type": "text", "prompt": "¿Qué sentís ahora, con esta nueva filosofía?", "help": "E también es una emoción más adaptativa. En Diego, la emoción pasó de ira a fastidio manejable.", "optional": true }, { "id": "e_intensidad", "type": "scale", "prompt": "¿Con qué intensidad sentís ahora lo que anotaste en C?", "help": "Puntuá la misma emoción que antes.", "min": 0, "max": 10, "min_label": "Nada", "max_label": "Máxima", "maps_to": "emotion_after" }, { "id": "preferencia_semana", "type": "text", "prompt": "¿Qué preferencia flexible te gustaría adoptar esta semana?", "help": "Elegí una para repetirla en voz alta cuando aparezca la situación. Puede ser la que acabás de escribir u otra." }, { "id": "resumen", "type": "reflect", "title": "Tu registro ABCDE", "template": "A: «{{a_hecho}}». B: «{{b_creencia}}». C: {{c_emocion}}; «{{c_conducta}}». E: «{{e_preferencia}}». Mi preferencia para esta semana: «{{preferencia_semana}}».", "content": "El malestar nace en B, no en A: la creencia media entre el hecho y la emoción.\n\nTu registro, con el debate (D), queda guardado en «Mis respuestas»." }, { "id": "reflexion", "type": "info", "title": "Preguntas de reflexión", "content": "- ¿Qué exigencias absolutas repetís más seguido?\n- ¿Con qué te decís «no lo soporto» cuando en realidad lo estás soportando?\n- ¿Qué cambiaría si tus «debo» se volvieran «prefiero»?\n- ¿En qué áreas te condenás globalmente por un error puntual?\n\nY una más, en la pantalla siguiente." }, { "id": "estilo", "type": "choice", "prompt": "¿Preferís el estilo más directo de Ellis o el más exploratorio de Beck?", "optional": true, "options": [ "El más directo de Ellis", "El más exploratorio de Beck", "Los dos me sirven", "Todavía no lo sé" ] }, { "id": "reflexion_respuesta", "type": "text", "prompt": "Si querés, respondé alguna de estas preguntas", "help": "Por ejemplo, por qué preferís uno u otro estilo. Podés llevar tu respuesta a la próxima sesión.", "optional": true }, { "id": "para_llevar", "type": "info", "title": "Para llevar", "content": "- ABC: Acontecimiento → Creencia → Consecuencia. Se amplía con D (debate) y E (nueva filosofía).\n- El malestar nace en B, no en A: la creencia media entre el hecho y la emoción.\n- Las creencias irracionales son exigencias rígidas: «debo», «tengo que», «no lo soporto».\n- Se debaten con tres preguntas: ¿es verdad?, ¿tiene lógica?, ¿me sirve?\n- Beck y Ellis coinciden en lo esencial; se diferencian en el énfasis y el estilo." }, { "id": "semana", "type": "info", "title": "Para esta semana", "content": "- Completá **tres registros ABCDE** durante la semana: repetí este ejercicio cada vez (unos 10 minutos; las pantallas de lectura las podés pasar rápido). Para anotar en el momento, también tenés el «Registro ABC», al final de la colección.\n- En cada B, marcá las palabras de exigencia («debo», «tengo que», «debería»), como hiciste hoy.\n- Reescribí cada exigencia como una preferencia flexible.\n- Repetí en voz alta la preferencia que elegiste cuando aparezca la situación.\n\nEl próximo capítulo es **«Tríada cognitiva y activación conductual»**." } ]$steps$::jsonb)
on conflict (slug) do nothing;

-- Recursos de la biblioteca de Materiales (abren el ejercicio correspondiente).
insert into public.materials (title, description, type, category_id, exercise_template_id, duration_minutes, visibility, is_published)
select v.title, v.description, 'exercise', c.id, t.id, t.estimated_minutes, 'public', true
from (values
  ('brujula-entender-lo-que-me-pasa', 'Entender lo que me pasa', 'La cadena situación, pensamiento, emoción, cuerpo, conducta y consecuencia, con el ejemplo de Cami. Para adolescentes (Brújula, página 3).', 'adolescentes'),
  ('brujula-detector-de-pensamientos', 'Mi detector de pensamientos', 'Hechos y pensamientos, la prueba de la cámara y las ocho trampas frecuentes de la mente. Para adolescentes (Brújula, página 4).', 'adolescentes'),
  ('brujula-poner-a-prueba', 'Poner a prueba lo que pienso', 'Hoja de detective para adolescentes: revisar un pensamiento con datos a favor y en contra, con el ejemplo de Lucas.', 'adolescentes'),
  ('brujula-cuando-me-quiero-aislar', 'Cuando me quiero aislar', 'El círculo del aislamiento, ideas que no cuestan plata (placer, logro y conexión), una escalera de pasos y un plan de 7 días.', 'adolescentes'),
  ('brujula-no-todo-lo-que-pienso', 'No todo lo que pienso es una orden', 'Defusión para adolescentes: pensamiento no es hecho, orden ni quién sos; la frase que da distancia y «Hojas en el río».', 'adolescentes'),
  ('brujula-lo-que-me-importa', 'Lo que realmente me importa', 'Valores para adolescentes: la diferencia entre un valor y una meta, elegir tus 3 valores y una acción chiquita para cada uno.', 'adolescentes'),
  ('brujula-emocion-sube-a-100', 'Cuando la emoción sube a 100', 'Regulación emocional para adolescentes: el termómetro de 0 a 10, regular no es reprimir, STOP y una caja de herramientas.', 'adolescentes'),
  ('brujula-decir-lo-que-necesito', 'Decir lo que necesito sin explotar ni callarme', 'Asertividad para adolescentes: callarme, decirlo claro o explotar; la fórmula «Cuando… me siento… necesito… te pido…» y poner límites.', 'adolescentes'),
  ('brujula-cuando-me-hacen-sentir-menos', 'Cuando otros me hacen sentir menos', 'Conflicto, broma, bullying y cyberbullying; el semáforo, qué hacer en redes, lo que pensé sobre mí y un plan anti-bullying.', 'adolescentes'),
  ('brujula-red-de-apoyo', 'Mi red de apoyo', 'Qué es una persona segura, dónde buscarla si en casa no hay, el mapa de apoyo con al menos 2 adultos y a quién recurrir según el tema.', 'adolescentes'),
  ('brujula-pod-vape-presion', 'POD, vape y presión de grupo', 'Cómo aprende el cerebro con la nicotina, la cadena de las ganas, surfear la ola, un plan de 10 minutos y cómo decir que no.', 'adolescentes'),
  ('brujula-plan-momentos-dificiles', 'Mi plan para momentos muy difíciles', 'Plan para adolescentes: señales de alerta, qué hacer para ganar tiempo, a quién pedir ayuda y cómo hacer el entorno más seguro.', 'adolescentes'),
  ('tcc-antes-de-empezar', 'Antes de empezar: cómo usar el cuadernillo de TCC', 'Qué vas a aprender, por qué funciona la TCC, la evidencia, preguntas frecuentes y el mapa de los siete capítulos.', 'psicoeducacion'),
  ('tcc-modelo-cognitivo', 'El modelo cognitivo de Beck', 'Situación, pensamiento, emoción, respuesta física y conducta: por qué el pensamiento es la bisagra. Con ejemplos, un caso y un desglose guiado.', 'psicoeducacion'),
  ('tcc-pensamientos-automaticos', 'Los pensamientos automáticos', 'Qué son, la pregunta de oro, cómo distinguirlos de emociones, preocupaciones y rumiaciones, y cómo registrarlos en el RPD.', 'psicoeducacion'),
  ('tcc-distorsiones', 'Las distorsiones cognitivas', 'Las 12 distorsiones cognitivas con ejemplos y preguntas para cuestionarlas, un quiz y la hoja para identificarlas.', 'psicoeducacion'),
  ('tcc-creencias', 'Creencias intermedias y nucleares', 'Reglas, supuestos y creencias nucleares: los tres dominios, la flecha descendente, el caso de Carla y hojas para trabajarlas.', 'psicoeducacion'),
  ('tcc-reestructuracion', 'Cuestionamiento socrático y reestructuración', 'Las cuatro familias de preguntas socráticas, cómo construir un pensamiento alternativo, el caso de Ana y el RPD de 7 columnas.', 'psicoeducacion'),
  ('tcc-abc-ellis', 'El modelo ABC de Ellis', 'Acontecimiento, creencia y consecuencia: cómo pasar de la exigencia rígida a la preferencia flexible. Con ejemplos, un caso y un registro ABCDE.', 'psicoeducacion')
) as v(slug, title, description, category)
join public.exercise_templates t on t.slug = v.slug
left join public.material_categories c on c.slug = v.category
where not exists (select 1 from public.materials m where m.exercise_template_id = t.id);
